TURATH_CHUNK(57,[{"num":11400,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ: أَنَّهُ قَالَ:  قَدِمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْيٍ، فَإِذَا امْرَأَةٌ مِنَ السَّبْيِ، تَبْتَغِي، إِذَا وَجَدَتْ صَبِيًّا فِي السَّبْيِ، أَخَذَتْهُ، فَأَلْصَقَتْهُ بِبَطْنِهَا، وَأَرْضَعَتْهُ، فَقَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَرَوْنَ هَذِهِ الْمَرْأَةَ طَارِحَةً وَلَدَهَا فِي النَّارِ؟ قُلْنَا: لَا، وَاللهِ وَهِيَ تَقْدِرُ عَلَى أَنْ لَا تَطْرَحَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَلَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ هَذِهِ بِوَلَدِهَا."],"takhrij":"متفق عليه: رواه البخاري في الأدب (5999)، ومسلم في التوبة (2754) كلاهما من طريق أبي غسان، حدثني زيد بن أسلم، عن أبيه، عن عمر بن الخطاب فذكره.","grade":"متفق عليه","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5999) and Muslim (2754).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated: Captives were brought before the Messenger of Allah ﷺ. Among them was a woman searching anxiously. Whenever she found a child among the captives, she took him, pressed him against her stomach, and nursed him. The Messenger of Allah ﷺ asked us: “Do you think this woman would throw her child into the Fire?” We replied: “No, by Allah, not while she is able to prevent it.” The Messenger of Allah ﷺ said: “Allah is more merciful to His servants than this woman is to her child.”"]}},"tuhfa":{},"full":1,"rep":[13081],"tks":"متفق عليه: رواه البخاري (5999)، ومسلم (2754)."},{"num":11401,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ، فَهْوَ عِنْدَهُ فَوْقَ الْعَرْشِ: إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3194)، ومسلم في التوبة (2751) كلاهما عن قتيبة بن سعيد، حدثنا مغيرة بن عبد الرحمن القرشي، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3194) and Muslim (2751).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Allah completed the creation, He wrote in His Book, which is with Him above the Throne: ‘Indeed, My mercy has overcome My wrath.’”"]}},"tuhfa":{},"full":1,"rep":[281,492,1009,12307],"tks":"متفق عليه: رواه البخاري (3194)، ومسلم (2751)."},{"num":11402,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ خَلَقَ الرَّحْمَةَ يَوْمَ خَلَقَهَا مِائَةَ رَحْمَةٍ، فَأَمْسَكَ عِنْدَهُ تِسْعًا وَتِسْعِينَ رَحْمَةً، وَأَرْسَلَ فِي خَلْقِهِ كُلِّهِمْ رَحْمَةً وَاحِدَةً، فَلَوْ يَعْلَمُ الْكَافِرُ بِكُلِّ الَّذِي عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ لَمْ يَيْأَسْ مِنَ الْجَنَّةِ، وَلَوْ يَعْلَمُ الْمُؤْمِنُ بِكُلِّ الَّذِي عِنْدَ اللَّهِ مِنَ الْعَذَابِ لَمْ يَأْمَنْ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6469) عن قتيبة بن سعيد، حدثنا يعقوب بن عبد الرحمن، عن عمرو بن أبي عمرو، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6469).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “When Allah created mercy, He made it one hundred portions. He retained ninety-nine portions with Himself and sent one portion among all His creation. If the disbeliever knew the full extent of the mercy that is with Allah, he would never despair of Paradise. If the believer knew the full extent of the punishment that is with Allah, he would never feel secure from the Fire.”"]}},"tuhfa":{},"full":1,"rep":[8261,12609],"tks":"صحيح: رواه البخاري (6469)."},{"num":11403,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ مِنَ الْعُقُوبَةِ مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ، وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ مَا قَنَِطَ مِنْ جَنَّتِهِ أَحَدٌ."],"takhrij":"صحيح: رواه مسلم في التوبة (2755) من طرق عن إسماعيل بن جعفر، أخبرني العلاء (هو ابن عبد الرحمن بن يعقوب)، عن ابيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2755).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If the believer knew the full extent of the punishment that is with Allah, no one would feel confident of attaining His Paradise. If the disbeliever knew the full extent of the mercy that is with Allah, no one would despair of His Paradise.”"]}},"tuhfa":{},"full":1,"rep":[16512],"tks":"صحيح: رواه مسلم (2755)."},{"num":11404,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ لِلَّهِ مِائَةَ رَحْمَةٍ، قَسَمَ رَحْمَةً بَيْنَ أَهْلِ الدُّنْيَا وَسِعَتْهُمْ إِلَى آجَالِهِمْ، وَأَخَّرَ تِسْعًا وَتِسْعِينَ رَحْمَةً لِأَوْلِيَائِهِ، وَإِنَّ اللَّهَ تَعَالَى قَابِضٌ تِلْكَ الرَّحْمَةَ الَّتِي قَسَمَهَا بَيْنَ أَهْلِ الدُّنْيَا إِلَى التِّسْعِ وَالتِّسْعِينَ، فَيُكْمِلُهَا مِائَةَ رَحْمَةٍ لِأَوْلِيَائِهِ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه أحمد (10672) عن روح (هو ابن عبادة)، عن عوف (وهو ابن أبي جميلة)، عن محمد (هو ابن سيرين)، عن أبي هريرة فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (10672).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah has one hundred portions of mercy. He distributed one portion among the people of this world, and it encompasses them until the ends of their lives. He reserved ninety-nine portions for His close servants. Allah, the Exalted, will take back the portion He distributed among the people of this world and add it to the ninety-nine, completing one hundred portions of mercy for His close servants on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (10672)."},{"num":11405,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَلَقَ اللَّهُ عَزَّ وَجَلَّ، يَوْمَ خَلَقَ السَّمَوَاتِ وَالأَرْضَ، مِائَةَ رَحْمَةٍ، فَجَعَلَ فِي الأَرْضِ مِنْهَا رَحْمَةً، فَبِهَا تَعْطِفُ الْوَالِدَةُ عَلَى وَلَدِهَا، وَالْبَهَائِمُ بَعْضُهَا عَلَى بَعْضٍ، وَالطَّيْرُ، وَأَخَّرَ تِسْعَةً وَتِسْعِينَ إِلَى يَوْمِ الْقِيَامَةٍ، فَإِذَا كَانَ يَوْمُ الْقِيَامَةِ، أَكْمَلَهَا اللَّهُ بِهَذِهِ الرَّحْمَةِ."],"takhrij":"صحيح: رواه ابن ماجه (4294)، وأحمد (11530)، وأبو يعلى (1098) كلهم من طريق الأعمش، عن أبي صالح، عن أبي سعيد قال: فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (4294), Aḥmad (11530), and Abū Yaʿlā (1098).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Saʿīd narrated that the Messenger of Allah ﷺ said: “When Allah, Mighty and Majestic, created the heavens and the earth, He created one hundred portions of mercy. He placed one portion upon the earth. Through it, a mother shows tenderness toward her child, animals show mercy to one another, and birds show mercy to one another. He reserved ninety-nine portions until the Day of Resurrection. When the Day of Resurrection comes, Allah will complete them with this portion.”"]}},"tuhfa":{},"full":1,"rep":[8265],"tks":"صحيح: رواه ابن ماجه (4294)، وأحمد (11530)، وأبو يعلى (1098)."},{"num":11406,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَفَرٍ مِنْ أَصْحَابِهِ، وَصَبِيٌّ فِي الطَّرِيقِ، فَلَمَّا رَأَتْ أُمُّهُ الْقَوْمَ، خَشِيَتْ عَلَى وَلَدِهَا أَنْ يُوطَأَ، فَأَقْبَلَتْ تَسْعَى وَتَقُولُ: ابْنِي ابْنِي، وَسَعَتْ فَأَخَذَتْهُ، فَقَالَ الْقَوْمُ: يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا كَانَتْ هَذِهِ لِتُلْقِيَ ابْنَهَا فِي النَّارِ. قَالَ: فَخَفَّضَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: وَلَاءُ اللهِ عَزَّ وَجَلَّ، لَا يُلْقِي حَبِيبَهُ فِي النَّارِ."],"takhrij":"صحيح: رواه أحمد (12018، 13467)، والبزار (كشف الأستار 3476)، وصحّحه الحاكم (1/58، 4/177) كلهم من طرق عن حميد الطويل، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب في سعة رحمة اللّٰه وأنها سبقت غضبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12018, 13467), al-Bazzār in Kashf al-Astār (3476), and authenticated by al-Ḥākim (1/58, 4/177).","chapter_en":"The Vastness of Allah’s Mercy and That It Precedes His Wrath","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ passed by with a group of his Companions while a child was in the road. When the child’s mother saw the group, she feared that her son might be trampled. She rushed forward crying: “My son! My son!” She ran and picked him up. The people said: “O Messenger of Allah, this woman would never throw her son into the Fire.” The Prophet ﷺ calmed them and said: “Nor, by Allah, will Allah, Mighty and Majestic, throw His beloved servant into the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13082],"tks":"صحيح: رواه أحمد (12018، 13467)، والبزار في كشف الأستار (3476)، وصححه الحاكم (1/58، 4/177)."},{"num":11407,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ اللَّهُ عَزَّ وَجَلَّ:  ﴿مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا﴾ [سورة الأنعام: 160] وَأَزِيدُ، وَمَنْ جَاءَ بِالسَّيِّئَةِ فَجَزَاؤُهُ سَيِّئَةٌ مِثْلُهَا أَوْ أَغْفِرُ، وَمَنْ تَقَرَّبَ مِنِّي شِبْرًا تَقَرَّبْتُ مِنْهُ ذِرَاعًا، وَمَنْ تَقَرَّبَ مِنِّي ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا، وَمَنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً، وَمَنْ لَقِيَنِي بِقُرَابِ الْأَرْضِ خَطِيئَةً لَا يُشْرِكُ بِي شَيْئًا لَقِيتُهُ بِمِثْلِهَا مَغْفِرَةً."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2687) عن أبي بكر بن أبي شيبة، حدثنا وكيع، حدثنا الأعمش، عن المعرور بن سويد، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب في سعة مغفرة اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2687).","chapter_en":"The Vastness of Allah the Exalted’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said: Allah, Mighty and Majestic, says: “Whoever comes with a good deed will receive ten times its like, and I may increase it further. Whoever comes with an evil deed will receive only an evil deed equal to it, or I may forgive him. Whoever draws near to Me by a handspan, I draw near to him by a forearm’s length. Whoever draws near to Me by a forearm’s length, I draw near to him by an armspan. Whoever comes to Me walking, I come to him swiftly. Whoever meets Me with sins nearly filling the earth, without associating anything with Me, I will meet him with forgiveness equal to them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2687)."},{"num":11408,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِيمَا رَوَى عَنِ اللَّهِ تَبَارَكَ وَتَعَالَى أَنَّهُ قَالَ:  يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا، فَلَا تَظَالَمُوا، يَا عِبَادِي كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ، فَاسْتَهْدُونِي أَهْدِكُمْ، يَا عِبَادِي كُلُّكُمْ جَائِعٌ، إِلَّا مَنْ أَطْعَمْتُهُ، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ، يَا عِبَادِي كُلُّكُمْ عَارٍ، إِلَّا مَنْ كَسَوْتُهُ، فَاسْتَكْسُونِي أَكْسُكُمْ، يَا عِبَادِي إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا، فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ، يَا عِبَادِي إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي، فَتَنْفَعُونِي، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا، يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي فَأَعْطَيْتُ كُلَّ إِنْسَانٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ، يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا، فَلْيَحْمَدِ اللهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ، فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2577: 55) عن عبد الله بن عبد الرحمن بن بهرام الدارمي، حدثنا مروان يعني ابن محمد الدمشقي، حدثنا سعيد بن عبدالعزيز، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب في سعة مغفرة اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2577/55).","chapter_en":"The Vastness of Allah the Exalted’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Dharr narrated from the Prophet ﷺ, among what he related from Allah, Blessed and Exalted, that He said: “O My servants, I have forbidden oppression for Myself and have made it forbidden among you, so do not oppress one another. O My servants, all of you are astray except those whom I guide, so seek guidance from Me and I will guide you. O My servants, all of you are hungry except those whom I feed, so ask Me for food and I will feed you. O My servants, all of you are unclothed except those whom I clothe, so ask Me for clothing and I will clothe you. O My servants, you commit sins by night and by day, while I forgive all sins, so seek My forgiveness and I will forgive you. O My servants, you can never reach a level at which you could harm Me, nor can you reach a level at which you could benefit Me. O My servants, if the first of you and the last of you, the humans among you and the jinn among you, were all as righteous as the most righteous heart of any one man among you, that would not increase My dominion in the least. O My servants, if the first of you and the last of you, the humans among you and the jinn among you, were all as wicked as the most wicked heart of any one man, that would not diminish My dominion in the least. O My servants, if the first of you and the last of you, the humans among you and the jinn among you, were all to stand together in one place and ask Me, and I were to give every person what he requested, that would diminish what I possess no more than a needle diminishes the sea when dipped into it. O My servants, these are only your deeds. I record them for you and then repay you for them in full. Whoever finds good should praise Allah, and whoever finds anything else should blame no one but himself.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12401,12532,12946,13188],"tks":"صحيح: رواه مسلم (2577: 55)."},{"num":11409,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللَّهُ: يَا ابْنَ آدَمَ إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي، غَفَرْتُ لَكَ عَلَى مَا كَانَ فِيكَ وَلاَ أُبَالِي، يَا ابْنَ آدَمَ لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ، ثُمَّ اسْتَغْفَرْتَنِي، غَفَرْتُ لَكَ، وَلاَ أُبَالِي، يَا ابْنَ آدَمَ إِنَّكَ لَوْ أَتَيْتَنِي بِقُرَابِ الأَرْضِ خَطَايَا، ثُمَّ لَقِيتَنِي لاَ تُشْرِكُ بِي شَيْئًا، لأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً."],"takhrij":"حسن: رواه الترمذي (3540) عن عبد الله بن إسحاق الجوهري البصري، حدثنا أبوعاصم، حدثنا كثير بن فائد، حدثنا سعيد بن عبيد، قال: سمعت بكر بن عبدالله المزني، يقول: حدثنا أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب في سعة مغفرة اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3540).","chapter_en":"The Vastness of Allah the Exalted’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik narrated: I heard the Messenger of Allah ﷺ say that Allah said: “O son of Adam, so long as you call upon Me and place your hope in Me, I will forgive you for whatever you have done, and I do not mind. O son of Adam, if your sins were to reach the clouds of the sky and then you sought My forgiveness, I would forgive you, and I do not mind. O son of Adam, if you were to come to Me with sins nearly filling the earth and then meet Me without associating anything with Me, I would come to you with forgiveness nearly filling the earth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3540)."},{"num":11410,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجِيءُ يَوْمَ الْقِيَامَةِ نَاسٌ مِنَ الْمُسْلِمِينَ بِذُنُوبٍ أَمْثَالِ الْجِبَالِ، فَيَغْفِرُهَا اللهُ لَهُمْ وَيَضَعُهَا عَلَى الْيَهُودِ وَالنَّصَارَى فِيمَا أَحْسِبُ أَنَا.","قَالَ أَبُو رَوْحٍ: لَا أَدْرِي مِمَّنِ الشَّكُّ."],"takhrij":"صحيح: رواه مسلم في التوبة (2767: 51) عن محمد بن عمرو بن عباد بن جبلة بن أبي رواد، حدثنا حرمي بن عمارة، حدثنا شداد أبو طلحة الراسبي، عن غيلان بن جرير، عن أبي بردة، عن أبيه أبي موسى الاشعري فذكره.","grade":"صحيح","chapter_ar":"باب في سعة مغفرة اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2767/51).","chapter_en":"The Vastness of Allah the Exalted’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Prophet ﷺ said: “On the Day of Resurrection, some Muslims will come with sins like mountains. Allah will forgive them and place them upon the Jews and Christians,” as far as I recall. Abū Rawḥ said: “I do not know from whom the uncertainty in the wording came.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2767: 51)."},{"num":11411,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّيْطَانَ قَالَ: وَعِزَّتِكَ يَا رَبِّ، لَا أَبْرَحُ أُغْوِي عِبَادَكَ مَا دَامَتْ أَرْوَاحُهُمْ فِي أَجْسَادِهِمْ، قَالَ الرَّبُّ: وَعِزَّتِي وَجَلَالِي لَا أَزَالُ أَغْفِرُ لَهُمْ مَا اسْتَغْفَرُونِي."],"takhrij":"حسن: رواه أحمد (11237، 11729) من طريقين عن ابن لهيعة، حدثنا دراج، عن أبي الهيثم، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب في سعة مغفرة اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (11237, 11729).","chapter_en":"The Vastness of Allah the Exalted’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Satan said, ‘By Your might, my Lord, I will never cease leading Your servants astray for as long as their souls remain within their bodies.’ The Lord said, ‘By My might and majesty, I will continue forgiving them for as long as they seek My forgiveness.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12132,13295],"tks":"حسن: رواه أحمد (11237، 11729)."},{"num":11412,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  وَالَّذِي نَفْسِي بِيَدِهِ، لَوْ لَمْ تُذْنِبُوا لَذَهَبَ اللهُ بِكُمْ، وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ، فَيَسْتَغْفِرُونَ اللهَ، فَيَغْفِرُ لَهُمْ."],"takhrij":"صحيح: رواه مسلم في التوبة (2749) عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا معمر، عن جعفر الجزري، عن يزيد بن الأصم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب أن كل ابن آدم خطاء، واللّٰه يحب أن يستغفر ابن آدم فيغفر له","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2749).","chapter_en":"Every Child of Adam Commits Errors, and Allah Loves That He Seek Forgiveness So That He May Forgive Him","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “By the One in whose hand is my soul, if you did not commit sins, Allah would remove you and bring a people who would commit sins, seek Allah’s forgiveness, and then be forgiven by Him.”"]},"intro":{"ar":["قال تعالى: ﴿وَمَنْ يَعْمَلْ سُوءًا أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُورًا رَحِيمًا﴾ [النساء: ١١٠]."],"en":["Allah, the Exalted, said:","“Whoever commits evil or wrongs himself and then seeks Allah’s forgiveness will find Allah Most Forgiving, Most Merciful.”","[Sūrat al-Nisāʾ 4:110]"]}},"tuhfa":{},"full":1,"rep":[13203],"tks":"صحيح: رواه مسلم (2749)."},{"num":11413,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ، أَنَّهُ قَالَ حِينَ حَضَرَتْهُ الْوَفَاةُ: كُنْتُ كَتَمْتُ عَنْكُمْ شَيْئًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،   سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،   يَقُولُ: لَوْلاَ أَنَّكُمْ تُذْنِبُونَ لَخَلَقَ اللَّهُ خَلْقًا يُذْنِبُونَ يَغْفِرُ لَهُمْ.","وفي لفظ: لَوْ أَنَّكُمْ لَمْ تَكُنْ لَكُمْ ذُنُوبٌ يَغْفِرُهَا اللَّهُ لَكُمْ لَجَاءَ اللَّهُ بِقَوْمٍ لَهُمْ ذُنُوبٌ يَغْفِرُهَا لَهُمْ."],"takhrij":"صحيح: رواه مسلم في التوبة (2748، 9) عن قتيبة بن سعيد، حدثنا ليث، عن محمد بن قيس قاص عمر بن عبد العزيز، عن أبي صرمة، عن أبي أيوب فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب أن كل ابن آدم خطاء، واللّٰه يحب أن يستغفر ابن آدم فيغفر له","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in al-Tawbah (2748/9) with the first wording.","chapter_en":"Every Child of Adam Commits Errors, and Allah Loves That He Seek Forgiveness So That He May Forgive Him","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["When Abū Ayyūb was approaching death, he said: “I had concealed from you something I heard from the Messenger of Allah ﷺ.” I heard the Messenger of Allah ﷺ say: “Were it not that you commit sins, Allah would create people who would commit sins and then forgive them.” Another wording states: “If you had no sins for Allah to forgive, Allah would bring a people who had sins and would forgive them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2748/9) باللفظ الأول."},{"num":11414,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ أَنَّ الْعِبَادَ لَمْ يُذْنِبُوا لَخَلَقَ اللَّهُ عَزَّ وَجَلَّ خَلْقًا يُذْنِبُونَ، ثُمَّ يَغْفِرُ لَهُمْ، وَهُوَ الْغَفُورُ الرَّحِيمُ."],"takhrij":"حسن: رواه الحاكم (7623) من طريق يحيى بن كثير بن درهم و أبي عباد يحيى بن عباد قالا: حدثنا شعبة، عن أبي بلج يحيى بن أبي سليم، عن عمرو بن ميمون، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب أن كل ابن آدم خطاء، واللّٰه يحب أن يستغفر ابن آدم فيغفر له","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (7623).","chapter_en":"Every Child of Adam Commits Errors, and Allah Loves That He Seek Forgiveness So That He May Forgive Him","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “If the servants did not commit sins, Allah, Mighty and Majestic, would create people who would commit sins and then forgive them. He is the Most Forgiving, the Most Merciful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (7623)."},{"num":11415,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ كُلُّ ابْنِ آدَمَ خَطَّاءٌ، وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ."],"takhrij":"حسن: رواه الترمذي (2499)، وابن ماجه (4251)، وأحمد (13049)، وابن حبان في المجروحين (2/87)، وابن عدي في الكامل (669)، والحاكم (7617) كلهم من طريق علي بن مسعدة الباهلي، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب أن كل ابن آدم خطاء، واللّٰه يحب أن يستغفر ابن آدم فيغفر له","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2499), Ibn Mājah (4251), Aḥmad (13049), Ibn Ḥibbān in al-Majrūḥīn (2/87), Ibn ʿAdī in al-Kāmil (5/1850), and al-Ḥākim (7617).","chapter_en":"Every Child of Adam Commits Errors, and Allah Loves That He Seek Forgiveness So That He May Forgive Him","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “Every child of Adam repeatedly commits errors, and the best of those who commit errors are those who repeatedly repent.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2499)، وابن ماجه (4251)، وأحمد (13049)، وابن حبان في المجروحين (2/87)، وابن عدي في الكامل (669)، والحاكم (7617)."},{"num":11416,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ ذَكَرَ رَجُلاً فِيمَنْ سَلَفَ، ـ أَوْ فِيمَنْ كَانَ قَبْلَكُمْ، قَالَ: كَلِمَةً: يَعْنِي ـ أَعْطَاهُ اللَّهُ مَالاً وَوَلَدًا، ـ فَلَمَّا حَضَرَتِ الْوَفَاةُ، قَالَ لِبَنِيهِ: أَىَّ أَبٍ كُنْتُ لَكُمْ؟ قَالُوا: خَيْرَ أَبٍ. قَالَ: فَإِنَّهُ لَمْ يَبْتَئِرْ، ـ أَوْ لَمْ يَبْتَئِزْ ـ عِنْدَ اللَّهِ خَيْرًا، وَإِنْ يَقْدِرِ اللَّهُ عَلَيْهِ يُعَذِّبْهُ، فَانْظُرُوا إِذَا مُتُّ فَأَحْرِقُونِي، حَتَّى إِذَا صِرْتُ فَحْمًا فَاسْحَقُونِي، ـ أَوْ قَالَ: فَاسْحَكُونِي، ـ فَإِذَا كَانَ يَوْمُ رِيحٍ عَاصِفٍ فَأَذْرُونِي فِيهَا، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَأَخَذَ مَوَاثِيقَهُمْ عَلَى ذَلِكَ وَرَبِّي، فَفَعَلُوا ثُمَّ أَذْرَوْهُ فِي يَوْمٍ عَاصِفٍ، فَقَالَ اللَّهُ عَزَّ وَجَلَّ: كُنْ. فَإِذَا هُوَ رَجُلٌ قَائِمٌ. قَالَ اللَّهُ: أَىْ عَبْدِي مَا حَمَلَكَ عَلَى أَنْ فَعَلْتَ مَا فَعَلْتَ؟ قَالَ: مَخَافَتُكَ، أَوْ: فَرَقٌ مِنْكَ، قَالَ: فَمَا تَلاَفَاهُ أَنْ رَحِمَهُ عِنْدَهَا ـ وَقَالَ مَرَّةً أُخْرَى: فَمَا تَلاَفَاهُ غَيْرُهَا."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7508)، ومسلم في كتاب التوبة (2757-27) كلاهما من طريق قتادة، سمع عقبة بن عبد الغافر يقول: سمعت أبا سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب فيمن خاف عقاب اللّٰه فأمر بإحراق جثته بعد موته، ولم يعلم بأن اللّٰه غفور رحيم","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7508) and Muslim (2757/27).","chapter_en":"The One Who Feared Allah’s Punishment and Ordered His Body to Be Burned after Death, Not Knowing That Allah Is Most Forgiving and Most Merciful","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Saʿīd narrated that the Prophet ﷺ mentioned a man from among the people of the past—or those who came before you. Allah had granted him wealth and children. When death approached him, he said to his sons: “What kind of father was I to you?” They replied: “The best of fathers.” He said: “I have not stored up any good with Allah. If Allah gains power over me, He will surely punish me. When I die, burn me. When I have become charcoal, crush me into powder. Then, on a day of violent wind, scatter me into it.” The Prophet ﷺ said: “By my Lord, he made them give firm pledges that they would do this. They did so and scattered him on a stormy day. Allah, Mighty and Majestic, said, ‘Be,’ and there he was, a man standing. Allah said, ‘My servant, what caused you to do what you did?’ He replied, ‘Fear of You,’ or, ‘Being terrified of You.’ Nothing then met him except Allah’s mercy.” On another occasion, he said: “Nothing else brought about his forgiveness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7508)، ومسلم (2757/27)."},{"num":11417,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَسْرَفَ رَجُلٌ عَلَى نَفْسِهِ، فَلَمَّا حَضَرَهُ الْمَوْتُ أَوْصَى بَنِيهِ فَقَالَ: إِذَا أَنَا مُتُّ فَأَحْرِقُونِي، ثُمَّ اسْحَقُونِي، ثُمَّ اذْرُونِي فِي الرِّيحِ فِي الْبَحْرِ، فَوَاللهِ لَئِنْ قَدَرَ عَلَيَّ رَبِّي لَيُعَذِّبُنِي عَذَابًا مَا عَذَّبَهُ بِهِ أَحَدًا، قَالَ: فَفَعَلُوا ذَلِكَ بِهِ، فَقَالَ لِلْأَرْضِ: أَدِّي مَا أَخَذْتِ، فَإِذَا هُوَ قَائِمٌ، فَقَالَ لَهُ: مَا حَمَلَكَ عَلَى مَا صَنَعْتَ؟ فَقَالَ: خَشْيَتُكَ يَا رَبِّ، أَوْ قَالَ: مَخَافَتُكَ فَغَفَرَ لَهُ بِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3481) ومسلم في كتاب التوبة (2756-25) كلاهما من طريق معمر قال: قال لي الزهري: ألا أحدثك بحديثين عجيبين؟ قال الزهري: أخبرني حميد بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فيمن خاف عقاب اللّٰه فأمر بإحراق جثته بعد موته، ولم يعلم بأن اللّٰه غفور رحيم","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3481) and Muslim (2756/25).","chapter_en":"The One Who Feared Allah’s Punishment and Ordered His Body to Be Burned after Death, Not Knowing That Allah Is Most Forgiving and Most Merciful","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “A man greatly transgressed against himself. When death approached him, he instructed his sons, saying, ‘When I die, burn me, crush me into powder, and scatter me in the wind over the sea. By Allah, if my Lord gains power over me, He will punish me with a punishment unlike that given to anyone else.’ They did that to him. Allah then commanded the earth, ‘Return what you took,’ and there he was, standing. Allah asked him, ‘What caused you to do what you did?’ He replied, ‘Fear of You, my Lord,’ or he said, ‘Being afraid of You.’ Allah forgave him because of that.”"]},"buhuth":{"en":["Muslim (2756/26) also narrated:","“Allah, Mighty and Majestic, said to everything that had taken a part of him, ‘Return what you took from him.’”","Al-Bukhārī (7506) and Muslim (2756/24) narrated through another route from Abū Hurayrah that the Messenger of Allah ﷺ said:","“A man who had never performed a good deed said to his family, ‘When he dies, burn him, then scatter half of him upon the land and half of him in the sea. By Allah, if Allah gains power over him…’”","This forms part of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8297],"tks":"متفق عليه: رواه البخاري (3481)، ومسلم (2756/25)."},{"num":11418,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: سَمِعْتَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ رَجُلاً حَضَرَهُ الْمَوْتُ، لَمَّا أَيِسَ مِنَ الْحَيَاةِ أَوْصَى أَهْلَهُ، إِذَا متّ فَاجْمَعُوا لِي حَطَبًا كَثِيرًا، ثُمَّ أَوْرُوا نَارًا، حَتَّى إِذَا أَكَلَتْ لَحْمِي وَخَلَصَتْ إِلَى عَظْمِي فَخُذُوهَا فَاطْحَنُوهَا، فَذَرُّونِي فِي الْيَمِّ فِي يَوْمٍ حَارٍّ أَوْ راحٍ، فَجَمَعَهُ اللَّهُ فَقَالَ: لِمَ فَعَلْتَ؟ قَالَ: خَشْيَتَكَ فَغَفَرَ لَهُ."],"takhrij":"صحيح: رواه البخاري في أحاديث الأنبياء (3479) عن مسدد، حدثنا أبو عوانة، عن عبد الملك بن عمير، عن ربعي بن حراش قال: قال عقبة لحذيفة: ألا تحدثنا ما سمعت من النبي صلى الله عليه وسلم قال: فذكره.","grade":"صحيح","chapter_ar":"باب فيمن خاف عقاب اللّٰه فأمر بإحراق جثته بعد موته، ولم يعلم بأن اللّٰه غفور رحيم","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3479).","chapter_en":"The One Who Feared Allah’s Punishment and Ordered His Body to Be Burned after Death, Not Knowing That Allah Is Most Forgiving and Most Merciful","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ḥudhayfah narrated: I heard the Prophet ﷺ say: “A man was overtaken by death. When he despaired of remaining alive, he instructed his family: ‘When I die, gather a great amount of firewood for me and kindle a fire. When it has consumed my flesh and reached my bones, take them and grind them. Then scatter me into the sea on a hot or windy day.’ Allah then gathered him and asked, ‘Why did you do that?’ He replied, ‘Out of fear of You.’ So Allah forgave him.”"]}},"tuhfa":{},"full":1,"rep":[8299],"tks":"صحيح: رواه البخاري (3479)."},{"num":11419,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ، وَعَنْ حُذَيْفَةَ، قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ رَجُلٌ مِمَّنْ كَانَ قَبْلَكُمْ يَعْمَلُ بِالْمَعَاصِي، فَلَمَّا حَضَرَهُ الْمَوْتُ قَالَ لِأَهْلِهِ: إِذَا أَنَا مُتُّ فَأَحْرِقُونِي، ثُمَّ اطْحَنُونِي، ثُمَّ ذَرُّونِي فِي الْبَحْرِ فِي يَوْمِ رِيحٍ عَاصِفٍ، قَالَ: فَلَمَّا مَاتَ فَعَلُوا، قَالَ: فَجَمَعَهُ اللَّهُ فِي يَدِهِ، فَقَالَ لَهُ: مَا حَمَلَكَ عَلَى مَا صَنَعْتَ؟ قَالَ: خَوْفُكَ، قَالَ: فَإِنِّي قَدْ غَفَرْتُ لَكَ."],"takhrij":"صحيح: رواه أحمد (23253) عن أبي معاوية، حدثنا أبو مالك الأشجعي، عن ربعي بن حراش، عن أبي مسعود الأنصاري وحذيفة فذكراه.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فيمن خاف عقاب اللّٰه فأمر بإحراق جثته بعد موته، ولم يعلم بأن اللّٰه غفور رحيم","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23253).","chapter_en":"The One Who Feared Allah’s Punishment and Ordered His Body to Be Burned after Death, Not Knowing That Allah Is Most Forgiving and Most Merciful","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Masʿūd al-Anṣārī and Ḥudhayfah narrated that the Messenger of Allah ﷺ said: “A man from among those who came before you used to commit sins. When death approached him, he said to his family, ‘When I die, burn me, grind me into powder, and scatter me into the sea on a day of violent wind.’ When he died, they did so. Allah, Mighty and Majestic, gathered him and asked, ‘What caused you to do what you did?’ He replied, ‘Fear of You.’ Allah said, ‘I have forgiven you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23253)."},{"num":11420,"demo":false,"sanad":"","matn":["عن بَهْزِ بْنِ حَكِيمٍ بْنِ مُعَاوِيَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: سَمِعْتُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّهُ كَانَ عَبْدٌ مِنْ عِبَادِ اللَّهِ أَعْطَاهُ اللهُ مَالًا وَوَلَدًا، فَكَانَ لَا يَدِينُ اللهَ دِينًا، فَلَبِثَ حَتَّى إِذَا ذَهَبَ مِنْهُ عُمُرٌ، وَبَقِيَ عُمُرٌ، تَذَكَّرَ، فَعَلِمَ أَنْ لَنْ يَبْتَئِرَ عِنْدَ اللَّهِ خَيْرًا، دَعَا بَنِيهِ فَقَالَ: أَيَّ أَبٍ تَعْلَمُونِي؟ قَالُوا: خَيْرَهُ يَا أَبَانَا. قَالَ: فَوَاللهِ لَا أَدَعُ عِنْدَ أَحَدٍ مِنْكُمْ مَالًا هُوَ مِنِّي إِلَّا أَنَا آخِذُهُ مِنْهُ، وَلَتَفْعَلُنَّ بِي مَا آمُرُكُمْ. قَالَ: فَأَخَذَ مِنْهُمْ مِيثَاقًا وَرَبِّي، فَقَالَ: إِمَّا لَا فَإِذَا أَنَا مُتُّ فَأَلْقُونِي فِي النَّارِ حَتَّى إِذَا كُنْتُ حُمَمًا فَدُقُّونِي، قَالَ: فَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ بِيَدِهِ عَلَى فَخِذِهِ، ثُمَّ اذْرُونِي فِي الرِّيحِ لَعَلِّي أَضِلُّ اللهَ. قَالَ: فَفَعَلُوا ذَلِكَ بِهِ وَرَبِّ مُحَمَّدٍ حِينَ مَاتَ، فَجِيءَ بِهِ فِي أَحْسَنِ مَا كَانَ قَطُّ، فَعُرِضَ عَلَى رَبِّهِ فَقَالَ: مَا حَمَلَكَ عَلَى النَّارِ؟ قَالَ: خَشْيَتُكَ يَا رَبَّاهُ. قَالَ: إِنِّي أَسْمَعُكَ لَرَاهِبًا، فَتِيبَ عَلَيْهِ."],"takhrij":"حسن: رواه أحمد (20044، 20039)، والدارمي (2855)، والطحاوي في شرح المشكل (566) كلهم من طرق عن بهز بن حكيم بن معاوية، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب فيمن خاف عقاب اللّٰه فأمر بإحراق جثته بعد موته، ولم يعلم بأن اللّٰه غفور رحيم","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20039, 20044), al-Dārimī (2855), and al-Ṭaḥāwī in Sharḥ Mushkil al-Āthār (566).","chapter_en":"The One Who Feared Allah’s Punishment and Ordered His Body to Be Burned after Death, Not Knowing That Allah Is Most Forgiving and Most Merciful","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Bahz ibn Ḥakīm ibn Muʿāwiyah narrated from his father, from his grandfather: I heard the Prophet of Allah ﷺ say: “There was a servant among the servants of Allah, Mighty and Majestic, to whom Allah had granted wealth and children. He did not follow any religion devoted to Allah, Blessed and Exalted. He remained in that condition until much of his life had passed—or only a little remained—then he reflected and realized that he had stored up no good with Allah, Blessed and Exalted. He summoned his sons and asked, ‘What kind of father do you know me to have been?’ They replied, ‘The best of fathers, our father.’ He said, ‘By Allah, I will not leave any wealth of mine with any one of you without taking it back unless you do exactly what I command you.’” The Prophet ﷺ said: “By my Lord, he took a firm covenant from them. He said, ‘When I die, throw me into the fire. When I have become charcoal, crush me.’” The narrator said: It was as though I could see the Messenger of Allah ﷺ gesturing with his hand upon his thigh. The man continued: “Then scatter me into the wind, so that perhaps I may escape Allah.” The Prophet ﷺ said: “By the Lord of Muḥammad, when he died, they did that to him. He was then brought back in the finest form he had ever possessed and presented before his Lord. Allah asked, ‘What caused you to enter the fire?’ He replied, ‘Fear of You, my Lord.’ Allah said, ‘I hear that you were deeply fearful,’ and He accepted his repentance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20039، 20044)، والدارمي (2855)، والطحاوي في شرح مشكل الآثار (566)."},{"num":11421,"demo":false,"sanad":"","matn":["عَنْ جُنْدَبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَ  أَنَّ رَجُلًا قَالَ: وَاللهِ لَا يَغْفِرُ اللَّهُ لِفُلَانٍ، وَإِنَّ اللَّهَ تَعَالَى قَالَ: مَنْ ذَا الَّذِي يَتَأَلَّى عَلَيَّ أَنْ لَا أَغْفِرَ لِفُلَانٍ، فَإِنِّي قَدْ غَفَرْتُ لِفُلَانٍ، وَأَحْبَطْتُ عَمَلَكَ أَوْ كَمَا قَالَ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2621) عن سويد بن سعيد، عن معتمر بن سليمان، عن أبيه، حدثنا أبو عمران الجوني، عن جندب فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من قول الرجل: لا يغفر اللّٰه لفلان","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2621).","chapter_en":"Warning against Saying, “Allah Will Not Forgive So-and-So”","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Jundub narrated that the Messenger of Allah ﷺ related that a man said: “By Allah, Allah will never forgive so-and-so.” Allah, the Exalted, then said: “Who is this who swears by Me that I will not forgive so-and-so? I have indeed forgiven so-and-so and nullified your deeds,” or words to that effect."]}},"tuhfa":{},"full":1,"rep":[7076,14615],"tks":"صحيح: رواه مسلم (2621)."},{"num":11422,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بْنِ مُحْرِزٍ الْمَازِنِيِّ، قَالَ: بَيْنَمَا أَنَا أَمْشِي، مَعَ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا آخِذٌ بِيَدِهِ، إِذْ عَرَضَ رَجُلٌ، فَقَالَ: كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّجْوَى؟ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ يُدْنِي الْمُؤْمِنَ، فَيَضَعُ عَلَيْهِ كَنَفَهُ، وَيَسْتُرُهُ، فَيَقُولُ: أَتَعْرِفُ ذَنْبَ كَذَا، أَتَعْرِفُ ذَنْبَ كَذَا؟ فَيَقُولُ: نَعَمْ أَىْ رَبِّ. حَتَّى إِذَا قَرَّرَهُ بِذُنُوبِهِ، وَرَأَى فِي نَفْسِهِ أَنَّهُ هَلَكَ، قَالَ: سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا، وَأَنَا أَغْفِرُهَا لَكَ الْيَوْمَ. فَيُعْطَى كِتَابَ حَسَنَاتِهِ، وَأَمَّا الْكَافِرُ وَالْمُنَافِقُونَ، ﴿فَيَقُولُ الأَشْهَادُ: هَؤُلاَءِ الَّذِينَ كَذَبُوا عَلَى رَبِّهِمْ، أَلاَ لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ﴾ [سورة هود: 18]."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2441)، ومسلم في التوبة (2768) كلاهما من طريق قتادة، عن صفوان بن محرز المازني فذكره.","grade":"متفق عليه","chapter_ar":"باب أن اللّٰه تعالى يقرر العبد بذنوبه يوم القيامة ثم يغفرها له","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2441) and Muslim (2768). The wording cited here is that of al-Bukhārī, while Muslim’s wording is similar.","chapter_en":"Allah the Exalted Will Make the Servant Acknowledge His Sins on the Day of Resurrection and Then Forgive Him","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ṣafwān ibn Muḥriz al-Māzinī narrated: While I was walking with Ibn ʿUmar and holding his hand, a man approached and asked: “How did you hear the Messenger of Allah ﷺ describe the private conversation?” Ibn ʿUmar replied: I heard the Messenger of Allah ﷺ say: “Allah will bring the believer near, place His covering over him, and conceal him. He will ask, ‘Do you recognize such-and-such a sin? Do you recognize such-and-such a sin?’ The believer will reply, ‘Yes, my Lord.’ When Allah has made him acknowledge his sins and he believes within himself that he is ruined, Allah will say, ‘I concealed them for you in the world, and today I forgive them for you.’ He will then be given the record of his good deeds. As for the disbelievers and hypocrites, the witnesses will say: ‘These are the ones who lied against their Lord. Unquestionably, the curse of Allah is upon the wrongdoers.’” [Sūrat Hūd 11:18]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[418],"tks":"متفق عليه: رواه البخاري (2441)، ومسلم (2768). واللفظ للبخاري، ولفظ مسلم نحوه."},{"num":11423,"demo":false,"sanad":"","matn":["عن شداد بن أَوْسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَيِّدُ الاِسْتِغْفَارِ أَنْ تَقُولَ: اللَّهُمَّ أَنْتَ رَبِّي، لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَىَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ. قَالَ وَمَنْ قَالَهَا مِنَ النَّهَارِ مُوقِنًا بِهَا، فَمَاتَ مِنْ يَوْمِهِ قَبْلَ أَنْ يُمْسِيَ، فَهُوَ مِنْ أَهْلِ الْجَنَّةِ، وَمَنْ قَالَهَا مِنَ اللَّيْلِ وَهْوَ مُوقِنٌ بِهَا، فَمَاتَ قَبْلَ أَنْ يُصْبِحَ، فَهْوَ مِنْ أَهْلِ الْجَنَّةِ."],"takhrij":"صحيح: رواه البخاري في الدعوات (6306) عن أبي معمر، حدثنا عبدالوارث، حدثنا الحسين (هو المعلم)، حدثنا عبد الله بن بريدة، عن بشير بن كعب العدوي قال: حدثني شداد بن أوس فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر بعض ما ورد من أدعية الاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6306).","chapter_en":"Some of the Reported Supplications for Seeking Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Shaddād ibn Aws narrated that the Prophet ﷺ said: “The master supplication for seeking forgiveness is to say: ‘O Allah, You are my Lord. There is no deity worthy of worship except You. You created me, and I am Your servant. I remain faithful to Your covenant and promise as much as I am able. I seek refuge in You from the evil of what I have done. I acknowledge before You Your blessing upon me, and I acknowledge my sin, so forgive me, for no one forgives sins except You.’” He continued: “Whoever says it during the day with certainty in it and dies that same day before evening will be among the people of Paradise. Whoever says it during the night with certainty in it and dies before morning will be among the people of Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6306)."},{"num":11424,"demo":false,"sanad":"","matn":["عَن جَابر قَالَ: قَالَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تعلمُوا سيد الاسْتِغْفَار: اللَّهُمَّ أَنْت رَبِّي، لَا إِلَه إِلَّا أَنْت، خلقتني وَأَنا عَبْدُكَ، على عَهْدك وَوَعدك مَا اسْتَطَعْت، وَأَعُوذ بِكَ من شَرّ مَا صنعت، أَبُوء بنعمتك عَليّ، وأبوء بذنبي، فَاغْفِر لِي ذَنْبِي، إِنَّه لَا يَغْفِرُ الذُّنُوب إِلَّا أَنْت."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (467-468)، وابن السني (372) كلاهما من طريق السري بن يحيى، عن هشام، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب في ذكر بعض ما ورد من أدعية الاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (467, 468) and Ibn al-Sunnī (372).","chapter_en":"Some of the Reported Supplications for Seeking Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “Learn the master supplication for seeking forgiveness: ‘O Allah, You are my Lord. There is no deity worthy of worship except You. You created me, and I am Your servant, remaining faithful to Your covenant and promise as much as I am able. I seek refuge in You from the evil of what I have done. I acknowledge Your blessing upon me, and I acknowledge my sin, so forgive my sin, for no one forgives sins except You.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (467، 468)، وابن السني (372)."},{"num":11425,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَالَ: أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ، وَأَتُوبُ إِلَيْهِ ثَلَاثًا، غُفِرَتْ لَهُ ذُنُوبُهُ، وَإِنْ كَانَ فَارًّا مِنَ الزَّحْفِ."],"takhrij":"صحيح: رواه ابن خزيمة في التوكل (كما في إتحاف المهرة 10/438)، والحاكم (1/511، و2/117-118) –وعنه البيهقي في الدعوات (161) من طرق عن إسرائيل، عن أبي سنان، عن أبي الأحوص، عن ابن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر بعض ما ورد من أدعية الاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah in al-Tawakkul, as cited in Itḥāf al-Maharah (10/438), and by al-Ḥākim (1/511, 2/117).","chapter_en":"Some of the Reported Supplications for Seeking Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Whoever says three times, ‘I seek forgiveness from Allah the Magnificent, besides whom there is no deity worthy of worship, the Ever-Living, the Sustainer of all, and I repent to Him,’ his sins will be forgiven, even if he had fled from the battlefield.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة في التوكل، كما في إتحاف المهرة (10/438)، والحاكم (1/511، 2/117)."},{"num":11426,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: كُنَّا نُمْسِكُ عَنِ الِاسْتِغْفَارِ لِأَهْلِ الْكَبَائِرِ، حَتَّى سَمِعْنَا نبينا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾ [النساء: 48] وَقَالَ: أخرت شَفَاعَتِي لِأَهْلِ الْكَبَائِرِ مِنْ أُمَّتِي يَوْمَ الْقِيَامَةِ.قَالَ: فَأَمْسَكْنَا عَنْ كَثِيرٍ مِمَّا كَانَ فِي أَنْفُسِنَا، ثُمَّ نَطَقْنَا بَعْدُ وَرَجَوْنَا."],"takhrij":"حسن: رواه البزار (5840)، وأبو يعلى (5813)، وابن أبي عاصم في السنة (854)، وابن عدي (536) كلهم من حديث شيبان بن فروخ بن أبي شيبة، حدثنا حرب بن سريج المنقري، عن أيوب السختياني، عن نافع، عن ابن عمر فذكره.والسياق لأبي يعلى.","grade":"حسن","chapter_ar":"باب ما جاء في الاستغفار لأهل الكبائر","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (5840), Abū Yaʿlā (5813), Ibn Abī ʿĀṣim in al-Sunnah (854), and Ibn ʿAdī (2/825).","chapter_en":"Seeking Forgiveness for Those Who Commit Major Sins","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar narrated: We used to refrain from seeking forgiveness for those who committed major sins until we heard our Prophet ﷺ recite: “Indeed, Allah does not forgive associating partners with Him, but He forgives what is less than that for whomever He wills.” [Sūrat al-Nisāʾ 4:48] He also said: “I have reserved my intercession for those among my nation who commit major sins on the Day of Resurrection.” Ibn ʿUmar said: “We then restrained much of what had been within ourselves, after which we began speaking and hoping for them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (5840)، وأبو يعلى (5813)، وابن أبي عاصم في السنة (854)، وابن عدي (536)."},{"num":11427,"demo":false,"sanad":"","matn":["عَنْ المسيب بن حَزْن قَالَ: لَمَّا حضر أَبَا طَالِبٍ الْوَفَاةُ دَخَلَ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ أَبُو جَهْلٍ وعبدالله بْنُ أَبِي أُمَيَّةَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أي عَمِّ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أُحَاجُّ لَكَ بِهَا عِنْدَ اللَّهِ فَقَالَ أَبُو جَهْلٍ وعبدالله بْنُ أَبِي أُمَيَّةَ: يَا أَبَا طَالِبٍ! أَتَرْغَبُ عَنْ مِلَّةِ عبدالمطلب؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنه عَنْكَ فَنَزَلَتْ: ﴿مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ﴾ [سورة التَّوْبَةِ:113]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4675)، ومسلم في الإيمان (24/40) كلاهما عن إسحاق بن إبراهيم، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن سعيد بن المسيب، عن أبيه فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن الاستغفار للمشركين","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4675) and Muslim (24/40). The wording cited here is that of al-Bukhārī.","chapter_en":"The Prohibition of Seeking Forgiveness for the Polytheists","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Al-Musayyib ibn Ḥazn narrated: When death approached Abū Ṭālib, the Prophet ﷺ entered upon him while Abū Jahl and ʿAbdullāh ibn Abī Umayyah were present. The Prophet ﷺ said: “My uncle, say: ‘There is no deity worthy of worship except Allah,’ a statement with which I can plead on your behalf before Allah.” Abū Jahl and ʿAbdullāh ibn Abī Umayyah said: “Abū Ṭālib, will you abandon the religion of ʿAbd al-Muṭṭalib?” The Prophet ﷺ said: “I will continue seeking forgiveness for you unless I am forbidden from doing so.” Then the following verse was revealed: “It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they are close relatives, after it has become clear to them that they are the inhabitants of the Blazing Fire.” [Sūrat al-Tawbah 9:113]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3741],"tks":"متفق عليه: رواه البخاري (4675)، ومسلم (24/40)، واللفظ للبخاري."},{"num":11428,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَتْ قُرَيْشٌ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ادْعُ لَنَا رَبَّكَ أَنْ يَجْعَلَ لَنَا الصَّفَا ذَهَبًا، وَنُؤْمِنُ بِكَ، قَالَ: وَتَفْعَلُونَ؟ قَالُوا: نَعَمْ، قَالَ: فَدَعَا، فَأَتَاهُ جِبْرِيلُ، فَقَالَ: إِنَّ رَبَّكَ يَقْرَأُ عَلَيْكَ السَّلامَ، وَيَقُولُ: إِنْ شِئْتَ أَصْبَحَ لَهُمُ الصَّفَا ذَهَبًا، فَمَنْ كَفَرَ بَعْدَ ذَلِكَ مِنْهُمْ عَذَّبْتُهُ عَذَابًا لَا أُعَذِّبُهُ أَحَدًا مِنَ العَالَمِينَ، وَإِنْ شِئْتَ فَتَحْتُ لَهُمْ بَابَ التَّوْبَةِ وَالرَّحْمَةِ، قَالَ: بَلْ بَابُ التَّوْبَةِ وَالرَّحْمَةِ."],"takhrij":"صحيح: رواه الإمام أحمد (3223،2166) والبزار – كشف الأستار (2224) والطبراني في الكبير (12736) والحاكم (174) والبيهقي في الدلائل (306) كلهم من طريق سفيان الثوري، عن سلمة بن كُهيل، عن عمران بن الحكم، عن ابن عباس فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أن اللّٰه تعالى فتح لعباده باب التوبة رحمة بهم","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Imām Aḥmad (2166, 3223), al-Bazzār in Kashf al-Astār (2224), and al-Ṭabarānī in al-Muʿjam al-Kabīr (12736).","chapter_en":"Allah the Exalted Opened the Door of Repentance for His Servants as a Mercy to Them","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿAbbās narrated: Quraysh said to the Prophet ﷺ: “Ask your Lord to turn al-Ṣafā into gold for us, and we will believe in you.” He asked: “Will you truly do so?” They replied: “Yes.” He supplicated, and Gabriel came to him and said: “Your Lord conveys His greeting of peace to you and says: ‘If you wish, al-Ṣafā will become gold for them by morning. Then whoever among them disbelieves afterward, I will punish with a punishment unlike any punishment I have given to anyone in the worlds. Alternatively, if you wish, I will open for them the door of repentance and mercy.’” The Prophet ﷺ replied: “Rather, the door of repentance and mercy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8579,12662],"tks":"صحيح: رواه الإمام أحمد (2166، 3223)، والبزار في كشف الأستار (2224)، والطبراني في الكبير (12736)."},{"num":11429,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: قَالَ اللَّهُ عَزَّ وَجَلَّ:  أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ حَيْثُ يَذْكُرُنِي، وَاللهِ، لَلَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ يَجِدُ ضَالَّتَهُ بِالْفَلَاةِ، وَمَنْ تَقَرَّبَ إِلَيَّ شِبْرًا، تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا، وَمَنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا، تَقَرَّبْتُ إِلَيْهِ بَاعًا، وَإِذَا أَقْبَلَ إِلَيَّ يَمْشِي، أَقْبَلْتُ إِلَيْهِ أُهَرْوِلُ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7405)، ومسلم في التوبة (2675) كلاهما من طريق أبي صالح (وهو السمان)، عن أبي هريرة فذكره، والسياق لمسلم ، والبخاري لم يذكر قوله: والله لله أفرح بتوبة عبده...","grade":"متفق عليه","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7405) and Muslim (2675). The sequence cited here is that of Muslim.","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: Allah, Mighty and Majestic, says: “I am as My servant thinks of Me, and I am with him wherever he remembers Me. By Allah, Allah rejoices more at the repentance of His servant than one of you rejoices upon finding his lost mount in the wilderness. Whoever draws near to Me by a handspan, I draw near to him by a forearm’s length. Whoever draws near to Me by a forearm’s length, I draw near to him by an armspan. When he comes toward Me walking, I come toward him swiftly.”"]},"buhuth":{"en":["Muslim also narrated through another route from Abū Hurayrah that the Messenger of Allah ﷺ said:","“Allah rejoices more intensely at the repentance of one of you than one of you rejoices over his lost animal when he finds it.”","Narrated by Muslim (2765)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7405)، ومسلم (2675)، والسياق لمسلم."},{"num":11430,"demo":false,"sanad":"","matn":["عَنْ سِمَاكٍ، قَالَ: خَطَبَ النُّعْمَانُ بْنُ بَشِيرٍ، فَقَالَ:  لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ رَجُلٍ، حَمَلَ زَادَهُ وَمَزَادَهُ عَلَى بَعِيرٍ، ثُمَّ سَارَ حَتَّى كَانَ بِفَلَاةٍ مِنَ الْأَرْضِ، فَأَدْرَكَتْهُ الْقَائِلَةُ، فَنَزَلَ، فَقَالَ تَحْتَ شَجَرَةٍ، فَغَلَبَتْهُ عَيْنُهُ، وَانْسَلَّ بَعِيرُهُ، فَاسْتَيْقَظَ فَسَعَى شَرَفًا فَلَمْ يَرَ شَيْئًا، ثُمَّ سَعَى شَرَفًا ثَانِيًا فَلَمْ يَرَ شَيْئًا، ثُمَّ سَعَى شَرَفًا ثَالِثًا فَلَمْ يَرَ شَيْئًا، فَأَقْبَلَ حَتَّى أَتَى مَكَانَهُ الَّذِي قَالَ فِيهِ، فَبَيْنَمَا هُوَ قَاعِدٌ إِذْ جَاءَهُ بَعِيرُهُ يَمْشِي، حَتَّى وَضَعَ خِطَامَهُ فِي يَدِهِ، فَلَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ الْعَبْدِ مِنْ هَذَا حِينَ وَجَدَ بَعِيرَهُ عَلَى حَالِهِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2745) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا أبو يونس، عن سماك، قال: خطب النعمان بن بشير فذكره.","grade":"صحيح","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2745).","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Simāk narrated: Al-Nuʿmān ibn Bashīr delivered a sermon and said: “Allah rejoices more intensely at the repentance of His servant than a man who loaded his provisions and water upon a camel and then traveled until he reached a barren wilderness. The midday heat overtook him, so he stopped beneath a tree and fell asleep. His camel slipped away. He awoke and climbed to a high place but saw nothing. He then climbed a second height and saw nothing. He climbed a third height and still saw nothing. He returned to the place where he had rested. While he was sitting there, his camel came walking toward him until it placed its reins in his hand. Allah rejoices more intensely at the servant’s repentance than this man rejoiced when he found his camel exactly as it had been.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2745)."},{"num":11431,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ، سَقَطَ عَلَى بَعِيرِهِ، وَقَدْ أَضَلَّهُ فِي أَرْضِ فَلاَةٍ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6309)، ومسلم في التوبة (2747: 8) كلاهما من طريق همام، حدثنا قتادة، حدثنا أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6309) and Muslim (2747/8). The wording cited here is that of al-Bukhārī.","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “Allah rejoices more at the repentance of His servant than one of you who suddenly comes upon his camel after losing it in a barren wilderness.”"]},"buhuth":{"en":["The phrase “suddenly comes upon his camel” means that he finds it without searching or exerting himself."]}},"tuhfa":{},"full":1,"dr":1,"rep":[385],"tks":"متفق عليه: رواه البخاري (6309)، ومسلم (2747: 8)، واللفظ للبخاري."},{"num":11432,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ وَهُوَ عَمُّهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ، وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا، فَأَتَى شَجَرَةً، فَاضْطَجَعَ فِي ظِلِّهَا، قَدْ أَيِسَ مِنْ رَاحِلَتِهِ، فَبَيْنَا هُوَ كَذَلِكَ إِذَا هُوَ بِهَا قَائِمَةً عِنْدَهُ، فَأَخَذَ بِخِطَامِهَا، ثُمَّ قَالَ مِنْ شِدَّةِ الْفَرَحِ: اللَّهُمَّ أَنْتَ عَبْدِي، وَأَنَا رَبُّكَ، أَخْطَأَ مِنْ شِدَّةِ الْفَرَحِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2747) من طرق عن عمر بن يونس، حدثنا عكرمة بن عمار، حدثنا إسحاق بن عبد الله بن أبي طلحة، حدثنا أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2747).","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Allah rejoices more intensely at His servant’s repentance when he repents to Him than one of you who was riding his mount in a barren wilderness when it escaped from him, carrying his food and drink. He despaired of recovering it, went to a tree, and lay down in its shade, having lost all hope of finding his mount. While he was in that state, he suddenly found it standing beside him. He seized its reins and, because of the intensity of his joy, said, ‘O Allah, You are my servant and I am Your lord.’ He made this mistake because of the intensity of his joy.”"]}},"tuhfa":{},"full":1,"rep":[13235],"tks":"صحيح: رواه مسلم (2747)."},{"num":11433,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ الْمُؤْمِنِ، مِنْ رَجُلٍ فِي أَرْضٍ دَوِّيَّةٍ مَهْلَكَةٍ، مَعَهُ رَاحِلَتُهُ، عَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَنَامَ فَاسْتَيْقَظَ، وَقَدْ ذَهَبَتْ، فَطَلَبَهَا حَتَّى أَدْرَكَهُ الْعَطَشُ، ثُمَّ قَالَ: أَرْجِعُ إِلَى مَكَانِيَ الَّذِي كُنْتُ فِيهِ، فَأَنَامُ حَتَّى أَمُوتَ، فَوَضَعَ رَأْسَهُ عَلَى سَاعِدِهِ لِيَمُوتَ، فَاسْتَيْقَظَ وَعِنْدَهُ رَاحِلَتُهُ، وَعَلَيْهَا زَادُهُ وَطَعَامُهُ وَشَرَابُهُ، فَاللهُ أَشَدُّ فَرَحًا بِتَوْبَةِ الْعَبْدِ الْمُؤْمِنِ مِنْ هَذَا بِرَاحِلَتِهِ وَزَادِهِ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6308)، ومسلم في التوبة (2744) كلاهما من طريق الأعمش، عن عمارة بن عمير، عن الحارث بن سويد، قال: دخلت على عبد الله أعوده وهو مريض، فحدثنا بحديثين: حديثا عن نفسه، وحديثا عن رسول الله صلى الله عليه وسلم قال: فذكره.واللفظ لمسلم ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6308) and Muslim (2744). The wording cited here is that of Muslim.","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ibn Masʿūd narrated: I heard the Messenger of Allah ﷺ say: “Allah rejoices more intensely at the repentance of His believing servant than a man in a barren, deadly wilderness who has his mount with him carrying his food and drink. He falls asleep and awakens to find that it has gone. He searches for it until thirst overtakes him. He then says, ‘I will return to the place where I was and sleep there until I die.’ He places his head upon his forearm, expecting to die. Then he awakens and finds his mount beside him, carrying his provisions, food, and drink. Allah rejoices more intensely at the repentance of the believing servant than this man rejoices at his mount and provisions.”"]},"buhuth":{"en":["The expression “a barren wilderness” means a desert in which no vegetation grows."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6308)، ومسلم (2744)، واللفظ لمسلم."},{"num":11434,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  كَيْفَ تَقُولُونَ بِفَرَحِ رَجُلٍ انْفَلَتَتْ مِنْهُ رَاحِلَتُهُ، تَجُرُّ زِمَامَهَا بِأَرْضٍ قَفْرٍ لَيْسَ بِهَا طَعَامٌ وَلَا شَرَابٌ، وَعَلَيْهَا لَهُ طَعَامٌ وَشَرَابٌ، فَطَلَبَهَا حَتَّى شَقَّ عَلَيْهِ، ثُمَّ مَرَّتْ بِجِذْلِ شَجَرَةٍ، فَتَعَلَّقَ زِمَامُهَا، فَوَجَدَهَا مُتَعَلِّقَةً بِهِ؟ قُلْنَا: شَدِيدًا، يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا وَاللهِ لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ، مِنَ الرَّجُلِ بِرَاحِلَتِهِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2746) من طرق عن عبيد الله بن إياد بن لقيط، عن إياد، عن البراء بن عازب فذكره.","grade":"صحيح","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2746).","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated: The Messenger of Allah ﷺ asked: “What would you say about the joy of a man whose mount escaped from him, dragging its reins through a barren land containing neither food nor drink, while his food and drink were upon it? He searched for it until the search became extremely difficult for him. It then passed by the stump of a tree, where its reins became caught, and he found it fastened there.” We replied: “His joy would be intense, O Messenger of Allah.” The Messenger of Allah ﷺ said: “By Allah, Allah rejoices more intensely at the repentance of His servant than that man rejoices at his mount.”"]}},"tuhfa":{},"full":1,"rep":[389],"tks":"صحيح: رواه مسلم (2746)."},{"num":11435,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَلَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ الَّذِي قَدْ أَسْرَفَ عَلَى نَفْسِهِ مِنْ رَجُلٍ سَافَرَ فِي أَرْضٍ فَلَاةٍ مُعْطِبَةٍ مُهْلِكَةٍ، فَلَمَّا تَوَسَّطَ أَضَلَّ رَاحِلَتَهُ، فَسَعَى فِي بُغَائِهَا يَمِينًا وَشِمَالًا حَتَّى أَعْيَى، - أَوْ أَيِسَ - مِنْهَا، وَظَنَّ أَنْ قَدْ هَلَكَ، نَظَرَ فَوَجَدَهَا فِي مَكَانٍ لَمْ يَكُنْ يَرْجُو أَنْ يَجِدَهَا، فَاللَّهُ عَزَّ وَجَلَّ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ الْمُسْرِفِ مِنْ ذَلِكَ الرَّجُلِ بِرَاحِلَتِهِ حِينَ وَجَدَهَا."],"takhrij":"صحيح: رواه أبو يعلى (6285) عن إبراهيم بن سعيد، حدثنا أبو أسامة، حدثنا بريد بن عبد الله، عن أبي بردة، عن أبي موسى فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أن اللّٰه تعالى يفرح بتوبة عبده","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Yaʿlā (6285).","chapter_en":"Allah the Exalted Rejoices at His Servant’s Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā narrated that the Messenger of Allah ﷺ said: “Allah rejoices more at the repentance of His servant who has greatly transgressed against himself than a man who traveled through a barren, dangerous, and deadly wilderness. When he reached its middle, he lost his mount. He searched for it to his right and left until he became exhausted—or despaired of finding it—and believed that he was doomed. He then looked and found it in a place where he had never expected to find it. Allah, Mighty and Majestic, rejoices more at the repentance of His servant who has transgressed against himself than that man rejoices at his mount when he finds it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (6285)."},{"num":11436,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَاللَّهِ إِنِّي لأسغفر اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً.","وفي لفظ: إني لأستغفر لله وأتوب إليه في اليوم مائة مرة."],"takhrij":"صحيح: رواه البخاري في الدعوات (6307) عن أبي اليمان، أخبرنا شعيب، عن الزهري قال: أخبرني أبو سلمة بن عبد الرحمن قال: قال أبو هريرة فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Al-Bukhārī (6307) narrated the first wording, while Ibn Mājah (3815) narrated the second.","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “By Allah, I seek Allah’s forgiveness and repent to Him more than seventy times each day.” Another wording states: “I seek Allah’s forgiveness and repent to Him one hundred times each day.”"]},"buhuth":{"en":["Al-Nasā’ī also narrated through another route in ʿAmal al-Yawm wa al-Laylah (438):","“I seek Allah’s forgiveness one hundred times each day.”","There is no contradiction between seventy and one hundred, because the precise number is not the primary objective. Rather, the intended meaning is to frequently repent and seek forgiveness, whether seventy or one hundred times."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَتُوبُوا إِلَى اللّٰهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ﴾ [النور: ٣١].","وقال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللّٰهِ تَوْبَةً نَصُوحًا﴾ [التحريم: ٨].","وقال تعالى: ﴿وَأَنِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ﴾ [هود: ٣].","وقال تعالى: ﴿لِلَّذِينَ اتَّقَوْا عِنْدَ رَبِّهِمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا، وَأَزْوَاجٌ مُطَهَّرَةٌ، وَرِضْوَانٌ مِنَ اللّٰهِ، وَاللّٰهُ بَصِيرٌ بِالْعِبَادِ ۝ الَّذِينَ يَقُولُونَ رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ ۝ الصَّابِرِينَ وَالصَّادِقِينَ وَالْقَانِتِينَ وَالْمُنْفِقِينَ وَالْمُسْتَغْفِرِينَ بِالْأَسْحَارِ﴾ [آل عمران: ١٥-١٧].","وقال تعالى: ﴿فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ، إِنَّهُ كَانَ غَفَّارًا ۝ يُرْسِلِ السَّمَاءَ عَلَيْكُمْ مِدْرَارًا ۝ وَيُمْدِدْكُمْ بِأَمْوَالٍ وَبَنِينَ، وَيَجْعَلْ لَكُمْ جَنَّاتٍ، وَيَجْعَلْ لَكُمْ أَنْهَارًا﴾ [نوح: ١٠-١٢]."],"en":["Allah, the Exalted, said:","“Turn to Allah in repentance, all of you, O believers, so that you may succeed.”","[Sūrat al-Nūr 24:31]","He also said:","“O you who believe, turn to Allah in sincere repentance.”","[Sūrat al-Taḥrīm 66:8]","He also said:","“Seek forgiveness from your Lord, then turn to Him in repentance.”","[Sūrat Hūd 11:3]","He also said:","“For those who are mindful of Allah, there are gardens with rivers flowing beneath them, in which they will remain forever, purified spouses, and approval from Allah. Allah sees His servants—those who say, ‘Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire’; those who are patient, truthful, devoutly obedient, charitable, and who seek forgiveness before dawn.”","[Sūrat Āl ʿImrān 3:15–17]","He also said:","“I said, ‘Seek forgiveness from your Lord, for He is truly Most Forgiving. He will send abundant rain upon you, increase you in wealth and children, provide you with gardens, and provide you with rivers.’”","[Sūrat Nūḥ 71:10–12]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6307) باللفظ الأول، ورواه ابن ماجه (3815) باللفظ الثاني."},{"num":11437,"demo":false,"sanad":"","matn":["عَن أَبِي هُرَيْرَة أَن رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمَعَ النَّاس فَقَالَ: يَا أَيهَا النَّاس، تُوبُوا إِلَى اللَّهِ، فَإِنِّي أَتُوب إِلَى اللَّهِ فِي الْيَوْم مائَة مرّة."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (431)، والطبراني في الدعاء (1820) كلاهما من طريق سريج بن النعمان، حدثنا محمد بن مسلم، عن إبراهيم بن ميسرة، عن عطاء (هو ابن أبي رباح)، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (431) and al-Ṭabarānī in al-Duʿāʾ (1820).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ gathered the people and said: “O people, repent to Allah, for I repent to Allah one hundred times each day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (431)، والطبراني في الدعاء (1820)."},{"num":11438,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: مَا رَأَيْت أَحَدًا أَكثر أَن يَقُول: أسْتَغْفر اللَّهَ وَأَتُوب إِلَيْهِ من رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (454)، وابن السني (364)، وصحّحه ابن حبان (928) كلهم من طريق سعيد بن عبد العزيز، عن إسماعيل بن عيبد الله بن أبي المهاجر، عن خالد بن عبد الله بن الحسين قال: سمعت أبا هريرة يقول: فذكره.","grade":"حسن","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (454), Ibn al-Sunnī (364), and authenticated by Ibn Ḥibbān (928).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah said: “I never saw anyone say, ‘I seek Allah’s forgiveness and repent to Him,’ more frequently than the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (454)، وابن السني (364)، وصححه ابن حبان (928)."},{"num":11439,"demo":false,"sanad":"","matn":["عَنِ الْأَغَرِّ الْمُزَنِيِّ، وَكَانَتْ لَهُ صُحْبَةٌ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّهُ لَيُغَانُ عَلَى قَلْبِي، وَإِنِّي لَأَسْتَغْفِرُ اللهَ، فِي الْيَوْمِ مِائَةَ مَرَّةٍ.","وفي لفظ: يا أيها الناس توبوا إلى الله، فإني أتوب في اليوم إليه مائة مرة."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2702: 41) من طرق عن حماد بن زيد، عن ثابت، عن أبي بردة، عن الأغر المزني فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Muslim narrated the first wording (2702/41) and the second wording (2702/42).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Al-Agharr al-Muzanī, who was a Companion, narrated that the Messenger of Allah ﷺ said: “A covering sometimes comes over my heart, and I seek Allah’s forgiveness one hundred times each day.” Another wording states: “O people, repent to Allah, for I repent to Him one hundred times each day.”"]}},"tuhfa":{},"voc":["seerah",1337],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2702: 41) باللفظ الأول، ورواه أيضا (42/2702) باللفظ الثاني."},{"num":11440,"demo":false,"sanad":"","matn":["عَن أنس عَن النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنِّي (لأتوب) أَفِي الْيَوْم سَبْعِينَ مرّة."],"takhrij":"صحيح: رواه النسائي في عمل اليوم والليلة (432)، وصحّحه ابن حبان (924) كلاهما من طريق المعتمر بن سليمان قال: سمعت أبي يقول: حدثنا قتادة، عن أنس فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (432) and authenticated by Ibn Ḥibbān (924).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “I repent seventy times each day.”"]},"buhuth":{"en":["Another wording states:","“I seek Allah’s forgiveness and repent to Him more than seventy times each day.”","Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (433)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في عمل اليوم والليلة (432)، وصححه ابن حبان (924)."},{"num":11441,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: إِنْ كُنَّا لَنَعُدُّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَجْلِسِ الْوَاحِدِ مِائَةَ مَرَّةٍ: رَبِّ اغْفِرْ لِي، وَتُبْ عَلَىَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ."],"takhrij":"صحيح: رواه أبو داود (1516)، والترمذي (3434)، وابن ماجه (3814)، وأحمد (4726)، والبخاري في الأدب المفرد (618)، والنسائي في عمل اليوم والليلة (458)، وابن السني (371)، وصحّحه ابن حبان (927) كلهم من طريق محمد بن سوقة، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by Abū Dāwūd (1516), al-Tirmidhī (3434), Ibn Mājah (3814), and Aḥmad (4726).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿUmar narrated: “We used to count the Messenger of Allah ﷺ saying one hundred times during a single gathering: ‘My Lord, forgive me and accept my repentance. Indeed, You are the Accepter of repentance, the Most Merciful.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1516)، والترمذي (3434)، وابن ماجه (3814)، وأحمد (4726)."},{"num":11442,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَنْصَارِ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةٍ وَهُوَ يَقُولُ: رَبِّ اغْفِرْ لِي -أَوْ قَالَ اللهُمَّ اغْفِرْ لِي- وتُبْ عليَّ، إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ مِائَةَ مَرَّةٍ."],"takhrij":"حسن: رواه الإمام أحمد (23150)، والنسائي في الكبرى (9852) كلاهما من طريق شعبة، عن حُصين، عن هلال بن يساف، عن زاذان، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"حسن","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by Imām Aḥmad (23150) and al-Nasā’ī in al-Sunan al-Kubrā (9852).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["A man from among the Anṣār who was one of the Companions of the Prophet ﷺ narrated that he heard the Prophet ﷺ saying during a prayer one hundred times: “My Lord, forgive me—or he said: O Allah, forgive me—and accept my repentance. Indeed, You are the Accepter of repentance, the Most Forgiving.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (23150)، والنسائي في الكبرى (9852)."},{"num":11443,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن بُسْرٍ يَقُولُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: طُوبَى لِمَنْ وَجَدَ فِي صَحِيفَتِهِ اسْتِغْفَارًا كَثِيرًا."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (455)، وابن ماجه (3818) كلاهما عن عمرو بن عثمان بن سعيد بن كثير بن دينار الحمصي قال: حدثنا أبي، حدثنا محمد بن عبد الرحمن بن عرق قال: سمعت عبد الله بن بسر يقول: فذكره.","grade":"حسن","chapter_ar":"باب استحباب الاستكثار من التوبة والاستغفار","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (455) and Ibn Mājah (3818).","chapter_en":"The Recommendation to Frequently Repent and Seek Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Busr narrated that the Prophet ﷺ said: “Glad tidings are for the one who finds abundant seeking of forgiveness recorded in his book of deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (455)، وابن ماجه (3818)."},{"num":11444,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ فِي قِصَّةِ الإفك: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا بَعْدُ يَا عَائِشَةُ، فَإِنَّهُ قَدْ بَلَغَنِي عَنْكِ كَذَا وَكَذَا، فَإِنْ كُنْتِ بَرِيئَةً، فَسَيُبَرِّئُكِ اللَّهُ وَإِنْ كُنْتِ أَلْمَمْتِ بِذَنْبٍ فَاسْتَغْفِرِي اللَّهَ وَتُوبِي إِلَيْهِ، فَإِنَّ الْعَبْدَ إِذَا اعْتَرَفَ بِذَنْبٍ، ثُمَّ تَابَ تَابَ اللَّهُ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4141)، ومسلم في التوبة (2770) كلاهما من طريق الزهري قال: أخبرني سعيد بن المسيب وعروة بن الزبير وعلقمة بن وقاص وعبيد الله بن عبد الله بن عتبة بن مسعود، عن عائشة زوج النبي صلى الله عليه وسلم حين قال لها أهل الإفك ما قالوا: وكلهم حدثني طائفةً من حديثها فذكر حديثا طويلا في أثنائه الجزء المذكور.","grade":"متفق عليه","chapter_ar":"باب من أذنب ذنبًا ثم تاب، تاب اللّٰه عليه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Agreed upon (Muttafaqun ʿAlayh).\nNarrated by al-Bukhārī in al-Maghāzī (4141) and Muslim in al-Tawbah (2770).","chapter_en":"Whoever Commits a Sin and Then Repents, Allah Accepts His Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿĀ’ishah narrated concerning the incident of the false accusation: The Prophet ﷺ said: “To proceed, O ʿĀ’ishah, such-and-such has reached me concerning you. If you are innocent, Allah will declare your innocence. But if you have committed a sin, then seek Allah’s forgiveness and repent to Him, for when a servant acknowledges his sin and then repents, Allah accepts his repentance.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4141)، ومسلم (2770)."},{"num":11445,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ عَبْدٍ مُؤْمِنٍ إِلَّا وَلَهُ ذَنْبٌ يَعْتَادُهُ الْفَيْنَةَ بَعْدَ الْفَيْنَةِ، أَوْ ذَنْبٌ هُوَ مُقِيمٌ عَلَيْهِ، لَا يُفَارِقُهُ حَتَّى يُفَارِقَ، وَإِنَّ الْمُؤْمِنَ خُلِقَ مُفَتَّنًا، تَوَّابًا، نَسَّاءً، إِذَا ذُكِّرَ ذَكَرَ."],"takhrij":"حسن: رواه الطبراني في الكبير (11810) عن الحسين بن العباس الرازي، حدثنا أحمد بن أبي سريج الرازي، حدثنا علي بن حفص المدائني، حدثنا عبيد المكتب الكوفي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب من أذنب ذنبًا ثم تاب، تاب اللّٰه عليه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (11/304).","chapter_en":"Whoever Commits a Sin and Then Repents, Allah Accepts His Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “There is no believing servant except that he has a sin which he returns to from time to time, or a sin in which he persists and which does not leave him until he leaves this world. The believer was created to be repeatedly tested, repeatedly repentant, and forgetful; when he is reminded, he remembers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11810)."},{"num":11446,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَ فِي بَنِي إِسْرَائِيلَ رَجُلٌ قَتَلَ تِسْعَةً وَتِسْعِينَ إِنْسَانًا، ثُمَّ خَرَجَ يَسْأَلُ، فَأَتَى رَاهِبًا فَسَأَلَهُ، فَقَالَ لَهُ: هَلْ مِنْ تَوْبَةٍ؟ قَالَ: لاَ. فَقَتَلَهُ، فَجَعَلَ يَسْأَلُ، فَقَالَ لَهُ رَجُلٌ: ائْتِ قَرْيَةَ كَذَا وَكَذَا. فَأَدْرَكَهُ الْمَوْتُ، فَنَاءَ بِصَدْرِهِ نَحْوَهَا، فَاخْتَصَمَتْ فِيهِ مَلاَئِكَةُ الرَّحْمَةِ وَمَلاَئِكَةُ الْعَذَابِ، فَأَوْحَى اللَّهُ إِلَى هَذِهِ أَنْ تَقَرَّبِي. وَأَوْحَى اللَّهُ إِلَى هَذِهِ أَنْ تَبَاعَدِي. وَقَالَ: قِيسُوا مَا بَيْنَهُمَا. فَوُجِدَ إِلَى هَذِهِ أَقْرَبُ بِشِبْرٍ، فَغُفِرَ لَهُ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3470)، ومسلم في التوبة والاستغفار (2766: 48)كلاهما عن محمد بن بشار، حدثنا محمد بن أبي عدي، عن شعبة، عن قتادة، عن أبي الصديق الناجي، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب أن اللّٰه تعالى يقبل توبة عبده وإن كثرت ذنوبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Agreed upon (Muttafaqun ʿAlayh).\nNarrated by al-Bukhārī (3470) and Muslim (2766/48).","chapter_en":"Allah the Exalted Accepts His Servant’s Repentance Even When His Sins Are Many","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Prophet ﷺ said: “Among the Children of Israel was a man who had killed ninety-nine people. He then went out asking whether repentance was possible. He came to a monk and asked him, ‘Is there any repentance for me?’ The monk replied, ‘No,’ so he killed him as well. He continued asking until a man told him, ‘Go to such-and-such a town.’ Death overtook him while he was traveling, so he inclined his chest toward that town. The angels of mercy and the angels of punishment disputed over him. Allah revealed to one land that it should draw nearer and to the other that it should move farther away. He then commanded, ‘Measure the distance between them.’ They found him closer to the town of righteousness by a handspan, so he was forgiven.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3470)، ومسلم (2766: 48)."},{"num":11447,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ، قَالَ:  أَذْنَبَ عَبْدٌ ذَنْبًا، فَقَالَ: اللَّهُمَّ اغْفِرْ لِي ذَنْبِي، فَقَالَ تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِي ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، ثُمَّ عَادَ فَأَذْنَبَ، فَقَالَ: أَيْ رَبِّ اغْفِرْ لِي ذَنْبِي، فَقَالَ تَبَارَكَ وَتَعَالَى: عَبْدِي أَذْنَبَ ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، ثُمَّ عَادَ فَأَذْنَبَ فَقَالَ: أَيْ رَبِّ اغْفِرْ لِي ذَنْبِي، فَقَالَ تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِي ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، اعْمَلْ مَا شِئْتَ فَقَدْ غَفَرْتُ لَكَ.","قال عبد الأعلى (أحد رواة الحديث): لا أدري أقال في الثالثة أو الرابعة: اعمل ما شئت."],"takhrij":"متفق عليه: رواه مسلم في التوبة (2758) عن عبد الأعلى بن حماد، حدثنا حماد بن سلمة، عن إسحاق بن عبد الله بن أبي طلحة، عن عبد الرحمن بن أبي عمرة، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب أن اللّٰه تعالى يقبل توبة عبده إذا كان مخلصًا وإن تكرر منه الذنب","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Agreed upon (Muttafaqun ʿAlayh).\nNarrated by Muslim (2758) and al-Bukhārī (7507).","chapter_en":"Allah the Exalted Accepts His Servant’s Repentance When He Is Sincere, Even If the Sin Is Repeated","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ related from his Lord, Mighty and Majestic: “A servant committed a sin and said, ‘O Allah, forgive my sin.’ Allah, Blessed and Exalted, said, ‘My servant committed a sin and knew that he has a Lord who forgives sins and punishes for sins.’ He then committed another sin and said, ‘My Lord, forgive my sin.’ Allah, Blessed and Exalted, said, ‘My servant committed a sin and knew that he has a Lord who forgives sins and punishes for sins.’ He then committed another sin and said, ‘My Lord, forgive my sin.’ Allah, Blessed and Exalted, said, ‘My servant committed a sin and knew that he has a Lord who forgives sins and punishes for sins. Do as you wish, for I have forgiven you.’” ʿAbd al-Aʿlā, one of the narrators of the hadith, said: “I do not know whether the words ‘Do as you wish’ were spoken after the third or fourth occurrence.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2758)، والبخاري (7507)."},{"num":11448,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَحَدُنَا يُذْنِبُ؟ قَالَ: يُكْتَبُ عَلَيْهِ قَالَ: ثُمَّ يَسْتَغْفِرُ مِنْهُ وَيَتُوبُ؟ قَالَ: يُغْفَرُ لَهُ وَيُتَابُ عَلَيْهِ قَالَ: فَيَعُودُ فَيُذْنِبُ؟ قَالَ:يُكْتَبُ عَلَيْهِ قَالَ: ثُمَّ يَسْتَغْفِرُ مِنْهُ وَيَتُوبُ؟ قَالَ: يُغْفَرُ لَهُ وَيُتَابُ عَلَيْهِ، وَلَا يَمَلُّ اللَّهُ حَتَّى تَمَلُّوا."],"takhrij":"حسن: رواه الطبراني في الأوسط (مجمع البحرين (4718)، والروياني في مسنده (173)، والحاكم (7658) كلهم من طريق أبي صالح عبد الله بن صالح، حدثني الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب أن اللّٰه تعالى يقبل توبة عبده إذا كان مخلصًا وإن تكرر منه الذنب","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, Majmaʿ al-Baḥrayn (4718), al-Rūyānī in his Musnad (173), and al-Ḥākim (7658).","chapter_en":"Allah the Exalted Accepts His Servant’s Repentance When He Is Sincere, Even If the Sin Is Repeated","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: A man came to the Messenger of Allah ﷺ and asked: “O Messenger of Allah, what happens when one of us commits a sin?” He replied: “It is recorded against him.” The man asked: “Then he seeks forgiveness for it and repents?” He replied: “He is forgiven, and his repentance is accepted.” The man asked: “Then he returns and commits the sin again?” He replied: “It is recorded against him.” The man asked: “Then he seeks forgiveness for it and repents?” He replied: “He is forgiven, and his repentance is accepted. Allah does not grow weary until you grow weary.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، مجمع البحرين (4718)، والروياني في مسنده (173)، والحاكم (7658)."},{"num":11449,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمُؤْمِنَ إِذَا أَذْنَبَ كَانَتْ نُكْتَةٌ سَوْدَاءُ فِي قَلْبِهِ فَإِنْ تَابَ وَنَزَعَ وَاسْتَغْفَرَ صُقِلَ قَلْبُهُ فَإِنْ زَادَ زَادَتْ فَذَلِكَ الرَّانُ الَّذِي ذَكَرَهُ اللَّهُ فِي كِتَابِهِ: ﴿كَلاَّ بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾ [سورة المطففين: 14]}."],"takhrij":"حسن: رواه الترمذي (3334)، وابن ماجه (4244)، وأحمد (7952)، وصحّحه ابن حبان (930)، والحاكم (3908) كلهم من حديث محمد بن عجلان، عن القعقاع بن حكيم، عن أبي صالح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب من أذنب ذنبًا نُكت في قلبه نكتة سوداء، فإذا أقلع عن ذنبه وتاب صُقل قلبه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by al-Tirmidhī (3334), Ibn Mājah (4244), and Aḥmad (7952), and authenticated by Ibn Ḥibbān (930).","chapter_en":"When a Person Commits a Sin, a Black Mark Is Placed upon His Heart; If He Abandons the Sin and Repents, His Heart Is Polished","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When a believer commits a sin, a black mark is placed upon his heart. If he repents, abandons the sin, and seeks forgiveness, his heart is polished. But if he increases in sin, the mark increases. That is the covering which Allah mentioned in His Book: ‘No! Rather, what they used to earn has covered their hearts.’” [Sūrat al-Muṭaffifīn 83:14]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11889,13694],"tks":"حسن: رواه الترمذي (3334)، وابن ماجه (4244)، وأحمد (7952)، وصححه ابن حبان (930)."},{"num":11450,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَعْقِلٍ، قَالَ: كُنْتُ مَعَ أَبِي وَأَنَا إِلَى جَنْبِهِ عِنْدَ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، فَقَالَ لَهُ أَبِي: أَسَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: النَّدَمُ تَوْبَةٌ؟، فَقَالَ: نَعَمْ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه الطيالسي (380) عن زهير بن معاوية- وأحمد (4012) من طريق فرات- كلاهما عن عبد الكريم الجزري، عن زياد بن الجراح (وهو ليس بابن أبي مريم) عن عبد الله بن معقل فذكره.والسياق للطيالسي.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أن الندم توبة","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by al-Ṭayālisī (380) and Aḥmad (4012).","chapter_en":"Remorse Is Repentance","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Maʿqil narrated: I was with my father, sitting beside him in the presence of ʿAbdullāh ibn Masʿūd. My father asked him: “Did you hear the Messenger of Allah ﷺ say, ‘Remorse is repentance’?” He replied: “Yes. I heard the Messenger of Allah ﷺ say: ‘Remorse is repentance.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطيالسي (380)، وأحمد (4012)."},{"num":11451,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ يَقْبَلُ تَوْبَةَ الْعَبْدِ مَا لَمْ يُغَرْغِرْ."],"takhrij":"حسن: رواه الترمذي (3537)، وابن ماجه (4253)، وأحمد (6160)، وصحّحه ابن حبان (628)، والحاكم (4/257) كلهم من طرق عن عبد الرحمن بن ثابت بن ثوبان، عن أبيه، عن مكحول، عن جبير بن نفير، عن ابن عمر فذكره.إلا أن ابن ماجه قال: \"عبد الله بن عمرو\" وهو خطأ كما نبّه عليه المزي في التحفة (5/328).","grade":"حسن","chapter_ar":"باب أن اللّٰه يقبل توبة العبد ما لم يغرغر أو تطلع الشمس من مغربها","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by al-Tirmidhī (3537), Ibn Mājah (4253), and Aḥmad (6160), and authenticated by Ibn Ḥibbān (628) and al-Ḥākim (7659).","chapter_en":"Allah Accepts the Servant’s Repentance So Long as His Soul Has Not Reached His Throat and the Sun Has Not Risen from the West","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Prophet ﷺ said: “Allah accepts the repentance of His servant so long as his soul has not reached his throat.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12541],"tks":"حسن: رواه الترمذي (3537)، وابن ماجه (4253)، وأحمد (6160)، وصححه ابن حبان (628)، والحاكم (7659)."},{"num":11452,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللَّهُ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الكر والدعاء (2703) من طرق عن هشام بن حسان، عن محمد بن سيرين، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب أن اللّٰه يقبل توبة العبد ما لم يغرغر أو تطلع الشمس من مغربها","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by Muslim (2703).","chapter_en":"Allah Accepts the Servant’s Repentance So Long as His Soul Has Not Reached His Throat and the Sun Has Not Risen from the West","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever repents before the sun rises from the west, Allah will accept his repentance.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2703)."},{"num":11453,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ، حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا."],"takhrij":"صحيح: رواه مسلم في التوبة (2759) عن محمد بن المثنى، حدثنا محمد بن جعفر، حدثنا شعبة، عن عمرو بن مرة، قال: سمعت أبا عبيدة، يحدث عن أبي موسى قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن اللّٰه يقبل توبة العبد ما لم يغرغر أو تطلع الشمس من مغربها","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by Muslim (2759).","chapter_en":"Allah Accepts the Servant’s Repentance So Long as His Soul Has Not Reached His Throat and the Sun Has Not Risen from the West","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Prophet ﷺ said: “Allah, Mighty and Majestic, extends His hand during the night so that the sinner of the day may repent, and He extends His hand during the day so that the sinner of the night may repent, until the sun rises from the west.”"]}},"tuhfa":{},"full":1,"rep":[345,12511,12914],"tks":"صحيح: رواه مسلم (2759)."},{"num":11454,"demo":false,"sanad":"","matn":["عَنْ زِرِّ بْنِ حُبَيْشٍ، قَالَ: أَتَيْتُ صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ أَسْأَلُهُ عَنِ الْمَسْحِ، عَلَى الْخُفَّيْنِ فَقَالَ: مَا جَاءَ بِكَ يَا زِرُّ فَقُلْتُ: ابْتِغَاءَ الْعِلْمِ، فَقَالَ: إِنَّ الْمَلاَئِكَةَ تَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا يَطْلُبُ. قُلْتُ إِنَّهُ حَكَّ فِي صَدْرِي الْمَسْحُ عَلَى الْخُفَّيْنِ بَعْدَ الْغَائِطِ وَالْبَوْلِ، وَكُنْتَ امْرَأً مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجِئْتُ أَسْأَلُكَ هَلْ سَمِعْتَهُ يَذْكُرُ فِي ذَلِكَ شَيْئًا؟ قَالَ: نَعَمْ كَانَ يَأْمُرُنَا إِذَا كُنَّا سَفَرًا أَوْ مُسَافِرِيِنَ أَنْ لاَ نَنْزِعَ خِفَافَنَا ثَلاَثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ إِلاَّ مِنْ جَنَابَةٍ، لَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ. فَقُلْتُ هَلْ سَمِعْتَهُ يَذْكُرُ فِي الْهَوَى شَيْئًا قَالَ: نَعَمْ كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَبَيْنَا نَحْنُ عِنْدَهُ إِذْ نَادَاهُ أَعْرَابِيٌّ بِصَوْتٍ لَهُ جَهْوَرِيٍّ يَا مُحَمَّدُ. فَأَجَابَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى نَحْوٍ مِنْ صَوْتِهِ هَاؤُمُ، وَقُلْنَا لَهُ: وَيْحَكَ اغْضُضْ مِنْ صَوْتِكَ، فَإِنَّكَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ نُهِيتَ عَنْ هَذَا. فَقَالَ: وَاللَّهِ لاَ أَغْضُضُ. قَالَ الأَعْرَابِيُّ: الْمَرْءُ يُحِبُّ الْقَوْمَ وَلَمَّا يَلْحَقْ بِهِمْ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمَرْءُ مَعَ مَنْ أَحَبَّ يَوْمَ الْقِيَامَةِ. فَمَازَالَ يُحَدِّثُنَا حَتَّى ذَكَرَ بَابًا مِنْ قِبَلِ الْمَغْرِبِ مَسِيرَةُ عَرْضِهِ أَوْ يَسِيرُ الرَّاكِبُ فِي عَرْضِهِ أَرْبَعِينَ أَوْ سَبْعِينَ عَامًا.","قَالَ سُفْيَانُ: قِبَلَ الشَّامِ خَلَقَهُ اللَّهُ يَوْمَ خَلَقَ السَّمَوَاتِ وَالأَرْضَ مَفْتُوحًا -يَعْنِي لِلتَّوْبَةِ- لاَ يُغْلَقُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْهُ."],"takhrij":"حسن: رواه الترمذي (3535)، وأحمد (18095)، وصحّحه ابن حبان (1321) كلهم من حديث سفيان بن عيينة، عن عاصم بن أبي النجود، عن زر بن حبيش فذكره.وإسناده حسن من أجل عاصم بن أبي النجود.","grade":"حسن","chapter_ar":"باب أن اللّٰه يقبل توبة العبد ما لم يغرغر أو تطلع الشمس من مغربها","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by al-Tirmidhī (3535) and Aḥmad (18095), and authenticated by Ibn Ḥibbān (1321).","chapter_en":"Allah Accepts the Servant’s Repentance So Long as His Soul Has Not Reached His Throat and the Sun Has Not Risen from the West","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Zirr ibn Ḥubaysh narrated: I came to Ṣafwān ibn ʿAssāl al-Murādī to ask him about wiping over leather socks. He asked: “What has brought you here, Zirr?” I replied: “The pursuit of knowledge.” He said: “The angels lower their wings for the seeker of knowledge, pleased with what he seeks.” I said: “The matter of wiping over leather socks after defecation and urination has troubled my mind. You were a Companion of the Prophet ﷺ, so I have come to ask whether you heard him mention anything concerning it.” He replied: “Yes. When we were traveling, he used to command us not to remove our leather socks for three days and nights, except because of major ritual impurity, but not because of defecation, urination, or sleep.” I asked: “Did you hear him mention anything concerning love?” He replied: “Yes. We were with the Prophet ﷺ on a journey when a Bedouin called out to him in a loud voice, ‘O Muḥammad!’” The Messenger of Allah ﷺ answered him in a similarly raised voice: “Here I am!” We said to the Bedouin: “Woe to you! Lower your voice, for you are in the presence of the Prophet ﷺ, and you have been forbidden from doing this.” He replied: “By Allah, I will not lower it.” The Bedouin then said: “A man loves a people but has not yet attained their level.” The Prophet ﷺ replied: “A person will be with those whom he loves on the Day of Resurrection.” Ṣafwān continued narrating to us until he mentioned a gate situated toward the west whose width was the distance of a seventy-year journey—or a rider could travel across its width for forty or seventy years. Sufyān said: “It is in the direction of Syria. Allah created it on the day He created the heavens and the earth, and it remains open for repentance. It will not be closed until the sun rises from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3535)، وأحمد (18095)، وصححه ابن حبان (1321)."},{"num":11455,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصدّيق قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ رَجُلٍ يُذْنِبُ ذَنْبًا فَيَتَوَضَّأُ، فَيُحْسِنُ الْوُضُوءَ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ، وَيَسْتَغْفِرُ اللَّهَ إِلاَّ غَفَرَ اللَّهُ لَهُ."],"takhrij":"حسن: رواه أبو داود (1521)، والترمذي في تفسير سورة آل عمران وحسنه، وابن ماجه (1395)، وصحّحه ابن حبان (623) كلهم من طرق عن عثمان بن المغيرة الثقفي، عن علي بن ربيعة الوالبي، عن أسماء بن الحكم الفزاري، عن علي بن أبي طالب، عن أبي بكر الصديق فذكره.","grade":"حسن","chapter_ar":"باب من آداب التوبة أن يتوضأ ويصلي ركعتين ثم يستغفر اللّٰه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by Abū Dāwūd (1521), al-Tirmidhī in his commentary on Sūrat Āl ʿImrān, who graded it ḥasan, and Ibn Mājah (1395).","chapter_en":"Among the Manners of Repentance Is to Perform Ablution, Pray Two Rakʿahs, and Then Seek Allah’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abū Bakr narrated that the Messenger of Allah ﷺ said: “There is no man who commits a sin, then performs ablution and perfects his ablution, prays two rakʿahs, and seeks Allah’s forgiveness, except that Allah forgives him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1521)، والترمذي في تفسير سورة آل عمران وحسنه، وابن ماجه (1395)."},{"num":11456,"demo":false,"sanad":"","matn":["عن يوسف بن عَبْدِ اللَّهِ بن سلام قَالَ: أَتَيْتُ أَبَا الدَّرْدَاءِ فِي مَرَضِهِ الَّذِي قُبِضَ فِيهِ فَقَالَ لِي: يَا ابْنَ أَخِي مَا أَعْمَدَكَ فِي هَذَا الْبَلَدِ - أَوْ مَا جَاءَ بِكَ؟ -؟ قَالَ: قُلْتُ: لَا إِلَّا صِلَةُ مَا كَانَ بَيْنَكَ وَبَيْنَ وَالِدِي عَبْدِ اللَّهِ بْنِ سَلَامٍ فَقَالَ: أَبُو الدَّرْدَاءِ: بِئْسَ سَاعَةُ الْكَذِبِ هَذِهِ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ، أَوْ أَرْبَعًا - شَكَّ سَهْلٌ - يُحْسِنُ فِيهِمَا الذِّكْرَ، وَالْخُشُوعَ، ثُمَّ اسْتَغْفَرَ اللَّهَ عَزَّ وَجَلَّ غَفَرَ لَهُ."],"takhrij":"حسن: رواه أحمد (27546) عن أحمد بن عبد الملك، حدثني صدقة بن أبي سهل قال: حدثني كثير أبو الفضل الطفاوي، حدثني يوسف بن عبد الله بن سلام فذكره.","grade":"حسن","chapter_ar":"باب من آداب التوبة أن يتوضأ ويصلي ركعتين ثم يستغفر اللّٰه","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ḥasan (Good).\nNarrated by Aḥmad (27546).","chapter_en":"Among the Manners of Repentance Is to Perform Ablution, Pray Two Rakʿahs, and Then Seek Allah’s Forgiveness","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Yūsuf ibn ʿAbdullāh ibn Salām narrated: I visited Abū al-Dardāʾ during the illness from which he died. He asked me: “My nephew, what has caused you to come to this land, or what brought you here?” I replied: “Nothing except maintaining the bond that existed between you and my father, ʿAbdullāh ibn Salām.” Abū al-Dardāʾ said: “This is a terrible time in which to lie.” He then said: I heard the Messenger of Allah ﷺ say: “Whoever performs ablution and perfects it, then stands and prays two or four rakʿahs—Sahl was uncertain—performing the remembrance and humility within them well, and then seeks forgiveness from Allah, Mighty and Majestic, will be forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27546)."},{"num":11457,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنِّي لَأَعْلَمُ آخِرَ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ، وَآخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْهَا: رَجُلٌ يُؤْتَى بِهِ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: اعْرِضُوا عَلَيْهِ صِغَارَ ذُنُوبِهِ، وَارْفَعُوا عَنْهُ كِبَارَهَا، فَتُعْرَضُ عَلَيْهِ صِغَارُ ذُنُوبِهِ، فَيُقَالُ: عَمِلْتَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا، وَعَمِلْتَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا، فَيَقُولُ: نَعَمْ، لَا يَسْتَطِيعُ أَنْ يُنْكِرَ، وَهُوَ مُشْفِقٌ مِنْ كِبَارِ ذُنُوبِهِ أَنْ تُعْرَضَ عَلَيْهِ، فَيُقَالُ لَهُ: فَإِنَّ لَكَ مَكَانَ كُلِّ سَيِّئَةٍ حَسَنَةً، فَيَقُولُ: رَبِّ، قَدْ عَمِلْتُ أَشْيَاءَ لَا أَرَاهَا هَا هُنَا، فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (190) عن محمد بن عبد الله بن نمير، حدثنا أبي، حدثنا الأعمش، عن المعرور بن سويد، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب من أسلم يبدل اللّٰه سيئاته حسنات يوم القيامة","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by Muslim (190).","chapter_en":"Allah Will Replace the Evil Deeds of the One Who Embraces Islam with Good Deeds on the Day of Resurrection","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said: “I know the last person among the people of Paradise to enter Paradise and the last person among the people of the Fire to leave it. A man will be brought on the Day of Resurrection, and it will be said, ‘Present his minor sins to him and withhold his major sins from him.’ His minor sins will then be presented to him, and he will be told, ‘On such-and-such a day, you did such-and-such, and on such-and-such a day, you did such-and-such.’ He will say, ‘Yes.’ He will be unable to deny them, while fearing that his major sins will also be presented to him. Then it will be said to him, ‘In place of every evil deed, you will receive a good deed.’ He will say, ‘My Lord, I committed other deeds which I do not see here.’” Abū Dharr said: “I saw the Messenger of Allah ﷺ laugh until his back teeth became visible.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللّٰهِ إِلَهًا آخَرَ، وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللّٰهُ إِلَّا بِالْحَقِّ، وَلَا يَزْنُونَ، وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ، وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا، فَأُولَئِكَ يُبَدِّلُ اللّٰهُ سَيِّئَاتِهِمْ حَسَنَاتٍ، وَكَانَ اللّٰهُ غَفُورًا رَحِيمًا﴾ [الفرقان: ٦٨-٧٠]."],"en":["Allah, the Exalted, said:","“Those who do not invoke another deity alongside Allah, do not take a life which Allah has made sacred except with legal right, and do not commit unlawful sexual intercourse—and whoever does that will face the penalty of sin. His punishment will be multiplied on the Day of Resurrection, and he will remain in it humiliated, except for those who repent, believe, and perform righteous deeds. For them, Allah will replace their evil deeds with good deeds. Allah is Most Forgiving, Most Merciful.”","[Sūrat al-Furqān 25:68–70]"]}},"tuhfa":{},"full":1,"rep":[12920,16414],"tks":"صحيح: رواه مسلم (190)."},{"num":11458,"demo":false,"sanad":"","matn":["عن أَبِي طويل شطب الممدود: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَرَأَيْتَ مَنْ عَمِلَ الذُّنُوبَ كُلَّهَا فَلَمْ يَتْرُكْ مِنْهَا شَيْئًا وَهُوَ فِي ذَلِكَ لَمْ يَتْرُكْ حَاجَةً وَلَا دَاجَةً إِلَّا أَتَاهَا فَهَلْ لِذَلِكَ مِنْ تَوْبَةٍ؟ قَالَ: فَهَلْ أَسْلَمْتَ؟ قَالَ: أَمَّا أَنَا فَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ [وَحْدَهُ لَا شَرِيكَ لَهُ] وَأَنَّكَ رَسُولُ اللَّهِ. قَالَ: [نَعَمْ] تَفْعَلُ الْخَيْرَاتِ وَتَتْرُكُ السَّيِّئَاتِ فَيَجْعَلُهُنَّ اللَّهُ لَكَ خَيْرَاتٍ كُلَّهُنَّ، قَالَ: وَغَدَرَاتِي وِفَجَرَاتِي؟ قَالَ: نَعَمْ. قَالَ: اللَّهُ أَكْبَرُ. فَمَا زَالَ يُكَبِّرُ حَتَّى تَوَارَى."],"takhrij":"صحيح: رواه البزار (كشف الأستار 3244)، والطبراني في الكبير (7235)، وابن أبي عاصم في الآحاد والمثاني (2718) كلهم من طرق عن أبي المغيرة، عن صفوان بن عمرو، عن عبد الرحمن بن جبير، عن أبي طويل شطب الممدود فذكره.","grade":"صحيح","chapter_ar":"باب من أسلم يبدل اللّٰه سيئاته حسنات يوم القيامة","chapter_ur":"","part_ar":"كتاب التوبة والاستغفار","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by al-Bazzār in Kashf al-Astār (3244), al-Ṭabarānī in al-Muʿjam al-Kabīr (7/375–376), and Ibn Abī ʿĀṣim in al-Āḥād wa-l-Mathānī (2718).","chapter_en":"Allah Will Replace the Evil Deeds of the One Who Embraces Islam with Good Deeds on the Day of Resurrection","part_en":"Repentance and Seeking Forgiveness","group_ar":"","group_en":"","part_no":55,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Abū Ṭawīl Shaṭab al-Mamdūd narrated that he came to the Messenger of Allah ﷺ and said: “What do you say about a man who committed every kind of sin and left none of them undone? In doing so, he left neither a minor nor a major sin without committing it. Is there any repentance for him?” The Prophet ﷺ asked: “Have you embraced Islam?” He replied: “As for me, I testify that there is no deity worthy of worship except Allah alone, without partner, and that you are the Messenger of Allah.” The Prophet ﷺ said: “Yes. Perform good deeds and abandon evil deeds, and Allah will transform all of them into good deeds for you.” The man asked: “Even my acts of betrayal and immorality?” He replied: “Yes.” The man exclaimed: “Allah is the Greatest!” He continued proclaiming Allah’s greatness until he disappeared from sight."]},"buhuth":{"en":["The expression “neither a ḥājah nor a dājah” means neither a minor nor a major sin."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12921],"tks":"صحيح: رواه البزار في كشف الأستار (3244)، والطبراني في الكبير (7200)، وابن أبي عاصم في الآحاد والمثاني (2718)."},{"num":11459,"demo":false,"sanad":"","matn":["عَنْ عَامِرٍ، عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لاَ رُقْيَةَ إِلاَّ مِنْ عَيْنٍ أَوْ حُمَةٍ. فَذَكَرْتُهُ لِسَعِيدِ بْنِ جُبَيْرٍ، فَقَالَ: حَدَّثَنَا ابْنُ عَبَّاسٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عُرِضَتْ عَلَىَّ الأُمَمُ، فَجَعَلَ النَّبِيُّ وَالنَّبِيَّانِ يَمُرُّونَ مَعَهُمُ الرَّهْطُ، وَالنَّبِيُّ لَيْسَ مَعَهُ أَحَدٌ، حَتَّى رُفِعَ لِي سَوَادٌ عَظِيمٌ، قُلْتُ: مَا هَذَا؟ أُمَّتِي هَذِهِ؟ قِيلَ: هَذَا مُوسَى وَقَوْمُهُ. قِيلَ: انْظُرْ إِلَى الأُفُقِ. فَإِذَا سَوَادٌ يَمْلأُ الأُفُقَ، ثُمَّ قِيلَ لِي: انْظُرْ هَا هُنَا، وَهَا هُنَا فِي آفَاقِ السَّمَاءِ، فَإِذَا سَوَادٌ قَدْ مَلأَ الأُفُقَ، قِيلَ: هَذِهِ أُمَّتُكَ، وَيَدْخُلُ الْجَنَّةَ مِنْ هَؤُلاَءِ سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ، ثُمَّ دَخَلَ وَلَمْ يُبَيِّنْ لَهُمْ فَأَفَاضَ الْقَوْمُ وَقَالُوا نَحْنُ الَّذِينَ آمَنَّا بِاللَّهِ، وَاتَّبَعْنَا رَسُولَهُ، فَنَحْنُ هُمْ أَوْ أَوْلاَدُنَا الَّذِينَ وُلِدُوا فِي الإِسْلاَمِ فَإِنَّا وُلِدْنَا فِي الْجَاهِلِيَّةِ. فَبَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَرَجَ فَقَالَ هُمُ الَّذِينَ لاَ يَسْتَرْقُونَ، وَلاَ يَتَطَيَّرُونَ، وَلاَ يَكْتَوُونَ وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ. فَقَالَ عُكَّاشَةُ بْنُ مِحْصَنٍ أَمِنْهُمْ أَنَا يَا رَسُولَ اللَّهِ قَالَ نَعَمْ. فَقَامَ آخَرُ فَقَالَ أَمِنْهُمْ أَنَا قَالَ سَبَقَكَ عُكَّاشَةُ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5705)، ومسلم في الإيمان (220: 374) كلاهما من طريق حصين بن عبدالرحمن، عن عامر (هو الشعبي) فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل من لا يسترقون","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Grading: Agreed upon (Muttafaqun ʿAlayh).\nNarrated by al-Bukhārī (5705) and Muslim (220/374). The wording cited here is that of al-Bukhārī.","chapter_en":"The Virtue of Those Who Do Not Ask Others to Perform Ruqyah for Them","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿĀmir narrated from ʿImrān ibn Ḥuṣayn, who said: “There is no ruqyah except for the evil eye or a venomous sting.” I mentioned this to Saʿīd ibn Jubayr, and he said: Ibn ʿAbbās narrated to us that the Messenger of Allah ﷺ said: “The nations were presented before me. A prophet or two prophets would pass with a small group, while another prophet would pass with no one accompanying him. Then an enormous multitude was raised before me. I asked, ‘What is this? Is this my nation?’ It was said, ‘Rather, this is Moses and his people.’ Then it was said to me, ‘Look toward the horizon.’ There was a great multitude filling the horizon. Then it was said, ‘Look here and there across the horizons of the sky.’ There was a multitude filling the horizon. It was said, ‘This is your nation, and among them are seventy thousand who will enter Paradise without reckoning.’” The Prophet ﷺ then entered without explaining who they were. The people began discussing it and said: “We are those who believed in Allah and followed His Messenger, so perhaps we are they—or perhaps they are our children who were born in Islam, whereas we were born during the time of ignorance.” When this reached the Prophet ﷺ, he came out and said: “They are those who do not ask others to perform ruqyah for them, do not believe in evil omens, do not cauterize themselves, and place their trust entirely in their Lord.” ʿUkāshah ibn Miḥṣan asked: “Am I among them, O Messenger of Allah?” He replied: “Yes.” Another man stood and asked: “Am I among them?” He replied: “ʿUkāshah has preceded you in asking for it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5705)، ومسلم (220: 374)، والسياق للبخاري."},{"num":11460,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ، قَالُوا: مَنْ هُمْ يَا رَسُولَ اللَّهِ؟ قَالَ: هُمُ الَّذِينَ لَا يَسْتَرْقُونَ، وَلَا يَتَطَيَّرُونَ، وَلَا يَكْتَوُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (218: 372) عن زهير بن حرب، حدثنا عبد الصمد بن عبد الوارث، حدثنا حاجب بن عمر أبو خشينة الثقفي، حدثنا الحكم بن الأعرج، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب فضل من لا يسترقون","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Grading: Ṣaḥīḥ (Authentic).\nNarrated by Muslim (218/372).","chapter_en":"The Virtue of Those Who Do Not Ask Others to Perform Ruqyah for Them","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated that the Messenger of Allah ﷺ said: “Seventy thousand from my nation will enter Paradise without reckoning.” They asked: “Who are they, O Messenger of Allah?” He replied: “They are those who do not ask others to perform ruqyah for them, do not believe in evil omens, do not cauterize themselves, and place their trust entirely in their Lord.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (218: 372)."},{"num":11461,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُرِيَ الْأُمَمَ بِالْمَوْسِمِ، فَرَاثَتْ عَلَيْهِ أُمَّتُهُ، قَالَ: فَأُرِيتُ أُمَّتِي، فَأَعْجَبَنِي كَثْرَتُهُمْ، قَدْ مَلَئُوا السَّهْلَ وَالْجَبَلَ، فَقِيلَ لِي: إِنَّ مَعَ هَؤُلَاءِ سَبْعونَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ، هُمُ الَّذِينَ لَا يَكْتَوُونَ، وَلَا يَسْتَرْقُونَ، وَلَا يَتَطَيَّرُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ. فَقَالَ عُكَّاشَةُ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ. فَدَعَا لَهُ، ثُمَّ قَامَ - يَعْنِي آخَرُ - فَقَالَ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مَنَهُمْ. قَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"حسن: رواه أحمد (3819)، والبزار –كشف الأستار (3939)، وصحّحه ابن حبان (6084) كلهم من حيث حماد بن سلمة، عن عاصم، عن زر، عن ابن مسعود فذكره.","grade":"حسن","chapter_ar":"باب فضل من لا يسترقون","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (3819), al-Bazzār in Kashf al-Astār (3939), and authenticated by Ibn Ḥibbān (6084).","chapter_en":"The Virtue of Those Who Do Not Ask Others to Perform Ruqyah for Them","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd narrated: The nations were shown to the Messenger of Allah ﷺ during the pilgrimage season, and his nation was delayed from appearing before him. He said: “Then my nation was shown to me, and their great number pleased me. They filled the plains and the mountains. It was said to me, ‘Along with these are seventy thousand who will enter Paradise without reckoning. They are those who do not cauterize themselves, do not ask others to perform ruqyah for them, do not believe in evil omens, and place their trust entirely in their Lord.’” ʿUkāshah said: “O Messenger of Allah, supplicate to Allah to make me one of them.” So he supplicated for him. Another man then stood and said: “O Messenger of Allah, supplicate to Allah to make me one of them.” He replied: “ʿUkāshah has preceded you in asking for it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16382],"tks":"حسن: رواه أحمد (3819)، والبزار في كشف الأستار (3939)، وصححه ابن حبان (6084)."},{"num":11462,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنَّهُ قَالَ: تَحَدَّثْنَا لَيْلَةً عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَكْرَيْنَا الْحَدِيثَ، ثُمَّ رَجَعْنَا إِلَى أَهْلِنَا، فَلَمَّا أَصْبَحْنَا، غَدَوْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: عُرِضَتْ عَلَيَّ الْأَنْبِيَاءُ بِأُمَمِهَا، وَأَتْبَاعُهَا مِنْ أُمَمِهَا، فَجَعَلَ النَّبِيُّ يَمُرُّ، وَمَعَهُ الثَّلَاثَةُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَعَهُ الْعِصَابَةُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَعَهُ النَّفَرُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَعَهُ الرَّجُلُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَا مَعَهُ أَحَدٌ مِنْ أُمَّتِهِ حَتَّى مَرَّ عَلَيَّ مُوسَى بْنُ عِمْرَانَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كَبْكَبَةٍ مِنْ بَنِي إِسْرَائِيلَ، فَلَمَّا رَأَيْتُهُمْ أَعْجَبُونِي، قُلْتُ: يَا رَبِّ مَنْ هَؤُلَاءِ؟ فَقَالَ: هَذَا أَخُوكَ مُوسَى بْنُ عِمْرَانَ وَمَنْ مَعَهُ مِنْ بَنِي إِسْرَائِيلَ، قُلْتُ: يَا رَبِّ، فَأَيْنَ أُمَّتِي؟ قَالَ: انْظُرْ عَنْ يَمِينِكَ، فَإِذَا الظِّرَابُ ظِرَابُ مَكَّةَ، قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ، قُلْتُ: مَنْ هَؤُلَاءِ يَا رَبِّ، قَالَ: أُمَّتُكَ، قُلْتُ: رَضِيتُ رَبِّ، قَالَ: أَرَضِيتَ؟ قُلْتُ: نَعَمْ، قَالَ: انْظُرْ عَنْ يَسَارِكَ، قَالَ: فَنَظَرْتُ، فَإِذَا الْأُفُقُ قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ، فَقَالَ: رَضِيتَ؟ قُلْتُ: رَضِيتُ، قِيلَ: فَإِنَّ مَعَ هَؤُلَاءِ سَبْعِينَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ، لَا حِسَابَ لَهُمْ، فَأَنْشَأَ عُكَّاشَةُ بْنُ مِحْصَنٍ، أَحَدُ بَنِي أَسَدِ بْنِ خُزَيْمَةَ، فَقَالَ: يَا نَبِيَّ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: اللهُمَّ اجْعَلْهُ مِنْهُمْ، ثُمَّ أَنْشَأُ رَجُلٌ آخَرُ مِنْهُمْ، فَقَالَ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"صحيح: رواه أحمد (3989) عن محمد بن بكر قال: أخبرنا سعيد، عن قتادة، عن الحسن والعلاء بن زياد، عن عمران بن حصسن، عن عبد الله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب فضل من لا يسترقون","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (3989).","chapter_en":"The Virtue of Those Who Do Not Ask Others to Perform Ruqyah for Them","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: One night, we remained in conversation with the Messenger of Allah ﷺ until we had spoken at length. We then returned to our families. The following morning, we went early to the Messenger of Allah ﷺ, and he said: “The prophets with their nations, and their followers from their nations, were presented before me. A prophet would pass with three members of his nation; another prophet with a small group from his nation; another with several people from his nation; another with only one man from his nation; and another prophet with no one from his nation. Then Moses ibn ʿImrān passed before me with a great gathering from the Children of Israel. When I saw them, their number impressed me. I asked, ‘My Lord, who are these?’ He replied, ‘This is your brother Moses ibn ʿImrān and those with him from the Children of Israel.’ I asked, ‘My Lord, where is my nation?’ He said, ‘Look to your right.’ I looked, and the hills of Makkah were covered by the faces of men. I asked, ‘My Lord, who are these?’ He replied, ‘Your nation.’ I said, ‘I am pleased, my Lord.’ He asked, ‘Are you pleased?’ I replied, ‘Yes.’ He said, ‘Look to your left.’ I looked and saw the entire horizon covered by the faces of men. He asked, ‘Are you pleased?’ I replied, ‘I am pleased.’ It was then said, ‘Among these are seventy thousand who will enter Paradise without reckoning.’” ʿUkāshah ibn Miḥṣan, from Banū Asad ibn Khuzaymah, stood and said: “O Prophet of Allah, supplicate to Allah to make me one of them.” The Prophet ﷺ said: “O Allah, make him one of them.” Another man then stood and said: “O Messenger of Allah, supplicate to Allah to make me one of them.” He replied: “ʿUkāshah has preceded you in asking for it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16383],"tks":"صحيح: رواه أحمد (3989)."},{"num":11463,"demo":false,"sanad":"","matn":["عن الْمُغِيرَةِ بن شُعْبَةَ عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ اكْتَوَى أَوِ اسْتَرْقَى فَقَدْ بَرِئَ مِنَ التَّوَكُّلِ."],"takhrij":"حسن: رواه الترمذي (2055)، وابن ماجه (3489)، وأحمد (18180)، وصحّحه ابن حبان (6087)، والحاكم (4/415) كلهم من طريق مجاهد، عن عقار بن المغيرة بن شعبة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب فضل من لا يسترقون","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2055), Ibn Mājah (3489), and Aḥmad (18180), and authenticated by Ibn Ḥibbān (6087) and al-Ḥākim (4/415).","chapter_en":"The Virtue of Those Who Do Not Ask Others to Perform Ruqyah for Them","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah narrated that the Messenger of Allah ﷺ said: “Whoever cauterizes himself or asks another to perform ruqyah for him has withdrawn from complete reliance upon Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2055)، وابن ماجه (3489)، وأحمد (18180)، وصححه ابن حبان (6087)، والحاكم (4/415)."},{"num":11464,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ نَاسًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَوْا عَلَى حَىٍّ مِنْ أَحْيَاءِ الْعَرَبِ فَلَمْ يَقْرُوهُمْ، فَبَيْنَمَا هُمْ كَذَلِكَ، إِذْ لُدِغَ سَيِّدُ أُولَئِكَ، فَقَالُوا: هَلْ مَعَكُمْ مِنْ دَوَاءٍ أَوْ رَاقٍ؟ فَقَالُوا: إِنَّكُمْ لَمْ تَقْرُونَا، وَلاَ نَفْعَلُ حَتَّى تَجْعَلُوا لَنَا جُعْلاً. فَجَعَلُوا لَهُمْ قَطِيعًا مِنَ الشَّاءِ، فَجَعَلَ يَقْرَأُ بِأُمِّ الْقُرْآنِ، وَيَجْمَعُ بُزَاقَهُ، وَيَتْفِلُ، فَبَرَأَ، فَأَتَوْا بِالشَّاءِ، فَقَالُوا: لاَ نَأْخُذُهُ حَتَّى نَسْأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلُوهُ فَضَحِكَ وَقَالَ: وَمَا أَدْرَاكَ أَنَّهَا رُقْيَةٌ، خُذُوهَا، وَاضْرِبُوا لِي بِسَهْمٍ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5736)، ومسلم في السلام (2201: 65) كلاهما عن محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن أبي بشر، عن أبي المتوكل، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب الرقية بفاتحة الكتاب","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5736) and Muslim (2201/65).","chapter_en":"Performing Ruqyah with the Opening Chapter of the Qur’an","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: A group of the Companions of the Prophet ﷺ passed by an Arab tribe, but the people refused to host them. While they were there, the chief of that tribe was bitten by a venomous creature. The people asked: “Do you have any medicine or someone who can perform ruqyah?” The Companions replied: “You refused to host us, so we will not do anything unless you assign us payment.” They agreed to give them a flock of sheep. One of the Companions began reciting the Opening Chapter of the Qur’an, collecting saliva in his mouth and blowing lightly upon the chief. The man recovered. The people brought them the sheep, but the Companions said: “We will not take them until we ask the Prophet ﷺ.” They asked him, and he laughed and said: “How did you know that it is a ruqyah? Take the sheep and assign me a share with you.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ، وَلَا يَزِيدُ الظَّالِمِينَ إِلَّا خَسَارًا﴾ [الإسراء: ٨٢]."],"en":["Allah, the Exalted, said:","“We send down from the Qur’an that which is a healing and mercy for the believers, but it only increases the wrongdoers in loss.”","[Sūrat al-Isrāʾ 17:82]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5736)، ومسلم (2201: 65)."},{"num":11465,"demo":false,"sanad":"","matn":["عَنْ خَارِجَةَ بْنِ الصَّلْتِ، عَنْ عَمِّهِ، أَنَّهُ مَرَّ بِقَوْمٍ، فَأَتَوْهُ، فَقَالُوا: إِنَّكَ جِئْتَ مِنْ عِنْدِ هَذَا الرَّجُلِ بِخَيْرٍ، فَارْقِ لَنَا هَذَا الرَّجُلَ. فَأَتَوْهُ بِرَجُلٍ مَعْتُوهٍ فِي الْقُيُودِ، فَرَقَاهُ بِأُمِّ الْقُرْآنِ ثَلاَثَةَ أَيَّامٍ غُدْوَةً وَعَشِيَّةً، كُلَّمَا خَتَمَهَا جَمَعَ بُزَاقَهُ، ثُمَّ تَفَلَ فَكَأَنَّمَا أُنْشِطَ مِنْ عِقَالٍ، فَأَعْطُوهُ شَيْئًا، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَهُ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلْ، فَلَعَمْرِي لَمَنْ أَكَلَ بِرُقْيَةٍ بَاطِلٍ لَقَدْ أَكَلْتَ بِرُقْيَةٍ حَقٍّ.","وفي رواية: فأعطوه مائة شاة."],"takhrij":"حسن: رواه أبو داود (3420، 3896، 3897، 3901)، وابن ماجه (6111)، وأحمد (21835)، وصحّحه ابن حبان (6110)، والحاكم (1/559-560) كلهم من طرق عن عامر الشعبي، عن خارجة بن الصلت، عن عمه فذكره.","grade":"حسن","chapter_ar":"باب الرقية بفاتحة الكتاب","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3420, 3896, 3897, 3901), Aḥmad (21835), Ibn Ḥibbān (6110, 6111), and al-Ḥākim (1/559–560).","chapter_en":"Performing Ruqyah with the Opening Chapter of the Qur’an","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Khārijah ibn al-Ṣalt narrated from his uncle: He passed by a group of people who came to him and said: “You have come from this man with something good, so perform ruqyah for this man of ours.” They brought him a mentally afflicted man who was bound in chains. He recited the Opening Chapter of the Qur’an over him for three days, morning and evening. Each time he completed it, he gathered saliva in his mouth and blew lightly upon him. The man then became as though he had been released from his bonds. They gave him something in payment. He went to the Prophet ﷺ and informed him of what had happened. The Prophet ﷺ said: “Eat it. By my life, some people earn by means of false ruqyah, but you have earned by means of a true ruqyah.” Another narration states that they gave him one hundred sheep."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5520],"tks":"حسن: رواه أبو داود (3420، 3896، 3897، 3901)، وأحمد (21835)، وابن حبان (6110، 6111)، والحاكم (1/559-560)."},{"num":11466,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اشْتَكَى يَقْرَأُ عَلَى نَفْسِهِ بِالْمُعَوِّذَاتِ وَيَنْفُثُ، فَلَمَّا اشْتَدَّ وَجَعُهُ كُنْتُ أَقْرَأُ عَلَيْهِ وَأَمْسَحُ بِيَدِهِ رَجَاءَ بَرَكَتِهَا."],"takhrij":"متفق عليه: رواه مالك في العين (10) عن ابن شهاب، عن عروة بن الزبير، عن عائشة فذكرته.ورواه البخاري في فضائل القرآن (5016)، ومسلم في السلام (2192: 51) من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب يرقي الإنسان نفسه وغيره بالمعوذات وغيرها","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (10), al-Bukhārī (5016), and Muslim (2192/51).","chapter_en":"A Person May Perform Ruqyah for Himself and Others with the Protective Chapters and Other Supplications","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah narrated: When the Messenger of Allah ﷺ became ill, he would recite the protective chapters over himself and blow lightly. She said: “When his illness became severe, I would recite them over him and wipe him with his own right hand, hoping for its blessing.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13814],"tks":"متفق عليه: رواه مالك (10)، والبخاري (5016)، ومسلم (2192: 51)."},{"num":11467,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ مِنَ الْجَانِّ، وَعَيْنِ الإِنْسَانِ حَتَّى نَزَلَتِ الْمُعَوِّذَتَانِ، فَلَمَّا نَزَلَتَا أَخَذَ بِهِمَا، وَتَرَكَ مَا سِوَاهُمَا."],"takhrij":"صحيح: رواه الترمذي (2058) من طريق القاسم بن مالك المزني-، والنسائي (5494)، وابن ماجه (3511)، والبيهقي في الدعوات (364) من طريق عباد بن العوام- كلاهما عن الجريري، عن أبي نضرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب يرقي الإنسان نفسه وغيره بالمعوذات وغيرها","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2058), al-Nasā’ī (5494), Ibn Mājah (3511), and al-Bayhaqī in al-Daʿawāt (364).","chapter_en":"A Person May Perform Ruqyah for Himself and Others with the Protective Chapters and Other Supplications","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abū Saʿīd narrated: The Messenger of Allah ﷺ used to seek refuge from the evil eye of the jinn and the evil eye of human beings until the two protective chapters were revealed. When they were revealed, he adopted them and left aside the other formulas he had previously used."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2058)، والنسائي (5494)، وابن ماجه (3511)، والبيهقي في الدعوات (364)."},{"num":11468,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَوِّذُ الْحَسَنَ وَالْحُسَيْنَ وَيَقُولُ: إِنَّ أَبَاكُمَا كَانَ يُعَوِّذُ بِهَا إِسْمَاعِيلَ وَإِسْحَاقَ، أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ."],"takhrij":"صحيح: رواه البخاري في الأنبياء (3371) عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن المنهال (هو ابن عمرو)، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب يرقي الإنسان نفسه وغيره بالمعوذات وغيرها","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3371).","chapter_en":"A Person May Perform Ruqyah for Himself and Others with the Protective Chapters and Other Supplications","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ used to seek protection for al-Ḥasan and al-Ḥusayn, saying: “Your forefather used to seek protection for Ishmael and Isaac with these words: ‘I seek refuge in the perfect words of Allah from every devil, every venomous creature, and every harmful evil eye.’”"]},"buhuth":{"en":["The word hāmmah refers to every venomous creature whose poison may kill. The word lāmmah refers to something that afflicts a person with harm, such as mental disturbance, madness, or a similar illness—meaning every evil eye that causes harm."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8393],"tks":"صحيح: رواه البخاري (3371)."},{"num":11469,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ:  كُنَّا نَرْقِي فِي الْجَاهِلِيَّةِ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، كَيْفَ تَرَى فِي ذَلِكَ؟ فَقَالَ: اعْرِضُوا عَلَيَّ رُقَاكُمْ، لَا بَأْسَ بِالرُّقَى مَا لَمْ يَكُنْ فِيهِ شِرْكٌ."],"takhrij":"صحيح: رواه مسلم في السلام (2200) عن أبي الطاهر (هو أحمد بن عمرو بن عبدالله بن عمرو بن سرح) أخبرنا ابن وهب، أخبرني معاوية بن صالح، عن عبد الرحمن بن جبير، عن أبيه، عن عوف بن مالك الأشجعي فذكره.","grade":"صحيح","chapter_ar":"باب جواز الرقية بالكتاب والأدعية المأثورة وغير المأثورة ما لم يكن فيها شرك","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2200).","chapter_en":"The Permissibility of Ruqyah with the Qur’an and Both Reported and Unreported Supplications, Provided They Contain No Polytheism","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī narrated: We used to perform ruqyah during the time of ignorance, so we asked: “O Messenger of Allah, what do you think about that?” He replied: “Present your ruqyah formulas to me. There is no harm in ruqyah so long as it contains no polytheism.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2200)."},{"num":11470,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الرُّقَى، فَجَاءَ آلُ عَمْرِو بْنِ حَزْمٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّهُ كَانَتْ عِنْدَنَا رُقْيَةٌ نَرْقِي بِهَا مِنَ الْعَقْرَبِ، وَإِنَّكَ نَهَيْتَ عَنِ الرُّقَى! قَالَ: فَعَرَضُوهَا عَلَيْهِ، فَقَالَ: مَا أَرَى بَأْسًا، مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ فَلْيَنْفَعْهُ."],"takhrij":"صحيح: رواه مسلم في السلام (2199: 63) عن أبي كريب (هو محمد بن العلاء) حدثنا أبو معاوية، حدثنا الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب جواز الرقية بالكتاب والأدعية المأثورة وغير المأثورة ما لم يكن فيها شرك","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2199/63).","chapter_en":"The Permissibility of Ruqyah with the Qur’an and Both Reported and Unreported Supplications, Provided They Contain No Polytheism","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ prohibited ruqyah. The family of ʿAmr ibn Ḥazm then came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, we possessed a ruqyah with which we treated scorpion stings, but you have prohibited ruqyah.” They presented it to him, and he said: “I see no harm in it. Whoever among you is able to benefit his brother should do so.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2199: 63)."},{"num":11471,"demo":false,"sanad":"","matn":["عَنْ كُرَيْبٍ الْكِنْدِيِّ، قَالَ: أَخَذَ بِيَدِي عَلِيُّ بْنُ الْحُسَيْنِ، فَانْطَلَقْنَا إِلَى شَيْخٍ مِنْ قُرَيْشٍ يُقَالُ لَهُ ابْنُ أَبِي حَثْمَةَ، يُصَلِّي إِلَى أُسْطُوَانَةٍ، فَجَلَسْنَا إِلَيْهِ، فَلَمَّا رَأَى عَلِيًّا انْصَرَفَ إِلَيْهِ، فَقَالَ لَهُ عَلِيٌّ: حَدِّثْنَا حَدِيثَ أُمِّكَ فِي الرُّقْيَةِ، فَقَالَ: حَدَّثَتْنِي أُمِّي أَنَّهَا كَانَتْ تَرْقِي فِي الْجَاهِلِيَّةِ، فَلَمَّا جَاءَ الإِسْلَامُ قَالَتْ: لَا أَرْقِي حَتَّى أَسْتَأْذِنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَتْهُ فَاسْتَأْذَنَتْهُ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْقِي، مَا لَمْ يَكُنْ فِيهَا شِرْكٌ."],"takhrij":"حسن: رواه ابن حبان (6092)، والحاكم (6889) كلاهما من طريق إسحاق بن سليمان، عن الجراح بن الضحاك الكندي، عن كريب بن سليمان الكندي فذكره.","grade":"حسن","chapter_ar":"باب جواز الرقية بالكتاب والأدعية المأثورة وغير المأثورة ما لم يكن فيها شرك","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (6092) and al-Ḥākim (6889).","chapter_en":"The Permissibility of Ruqyah with the Qur’an and Both Reported and Unreported Supplications, Provided They Contain No Polytheism","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Kurayb al-Kindī narrated: ʿAlī ibn al-Ḥusayn took me by the hand, and we went to an elderly man from Quraysh called Ibn Abī Ḥathmah, who was praying beside a pillar. We sat near him. When he saw ʿAlī, he turned toward him. ʿAlī said: “Relate to us the report of your mother concerning ruqyah.” He replied: My mother narrated to me that she used to perform ruqyah during the time of ignorance. When Islam came, she said: “I will not perform ruqyah until I seek the permission of the Messenger of Allah ﷺ.” She went to him and asked his permission. The Messenger of Allah ﷺ said to her: “Perform ruqyah, provided it contains no polytheism.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (6092)، والحاكم (6889)."},{"num":11472,"demo":false,"sanad":"","matn":["عَنْ عُمَيْرٍ، مَوْلَى آبِي اللَّحْمِ قَالَ: شَهِدْتُ خَيْبَرَ مَعَ سَادَتِي فَكَلَّمُوا فِيَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَعْلَمُوهُ أَنِّي مَمْلُوكٌ. قَالَ: فَأَمَرَ بِي فَقُلِّدْتُ السَّيْفَ، فَإِذَا أَنَا أَجُرُّهُ، فَأَمَرَ لِي بِشَيْءٍ مِنْ خُرْثِيِّ الْمَتَاعِ، وَعَرَضْتُ عَلَيْهِ رُقْيَةً كُنْتُ أَرْقِي بِهَا الْمَجَانِينَ، فَأَمَرَنِي بِطَرْحِ بَعْضِهَا، وَحَبْسِ بَعْضِهَا.","وفي رواية: وَعَرَضْتُ عَلَيْهِ رُقَيَّةُ كُنْتُ أَرْقِى بِهَا الْمَجَانِينَ فِى الْجَاهِلِيَّةِ قَالَ: اطْرَحْ مِنْهَا كَذَا وَكَذَا، وَارْقِ بِمَا بَقِىَ.","قَالَ مُحَمَّدُ بْنُ زَيْدٍ: وَأَدْرَكْتُهُ وَهُوَ يَرْقِي بِهَا الْمَجَانِينَ."],"takhrij":"صحيح: رواه الترمذي (1557)، والنسائي في الكبرى (7493)، والحاكم (1224) كلهم من طريق قتيبة، حدثنا بشر بن المفضل، عن محمد بن زيد (هو ابن المهاجر بن قنفذ)، عن عمير مولى آبي اللحم فذكره.","grade":"صحيح","chapter_ar":"باب جواز الرقية بالكتاب والأدعية المأثورة وغير المأثورة ما لم يكن فيها شرك","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1557), al-Nasā’ī in al-Sunan al-Kubrā (7493), and al-Ḥākim (1224).","chapter_en":"The Permissibility of Ruqyah with the Qur’an and Both Reported and Unreported Supplications, Provided They Contain No Polytheism","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUmayr, the freed slave of Abū al-Laḥm, narrated: I attended Khaybar with my masters. They spoke to the Messenger of Allah ﷺ concerning me and informed him that I was a slave. He ordered that I be given a sword, so it was hung upon me, though I was so short that I dragged it. He also ordered that I be given some of the lesser household goods. I presented to him a ruqyah with which I used to treat the mentally afflicted. He instructed me to discard part of it and retain part of it. Another narration states: I presented to him a ruqyah with which I had treated the mentally afflicted during the time of ignorance. He said: “Remove such-and-such parts from it, and perform ruqyah with what remains.” Muḥammad ibn Zayd said: “I later saw him performing ruqyah for the mentally afflicted with it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1557)، والنسائي في الكبرى (7493)، والحاكم (1224)."},{"num":11473,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ قَالَ: كُنْتُ أَرْقِي مِنْ حُمَةِ الْعَيْنِ فِي الْجَاهِلِيَّةِ، فَلَمَّا أَسْلَمْتُ ذَكَرْتُهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: (اعْرِضْهَا عَلَيَّ)، فَعَرَضْتُهَا عَلَيْهِ، فَقَالَ: (ارْقِ بِهَا فَلَا بَأْسَ بِهَا)","قَالَ عُبَادَةُ: وَلَوْلَا ذَلِكَ مَا رَقَيْتُ بِهَا إِنْسَانًا أَبَدًا."],"takhrij":"حسن: رواه أبو يعلى –المطالب العالية (2483)، والضياء في المختارة (434) كلاهما من طرق عن محمد بن إسحاق قال: حدثني عبادة بن الوليد بن عبادة بن الصامت، عن أبيه الوليد، عن جده عبادة بن الصامت فذكره.","grade":"حسن","chapter_ar":"باب جواز الرقية بالكتاب والأدعية المأثورة وغير المأثورة ما لم يكن فيها شرك","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā, as cited in al-Maṭālib al-ʿĀliyah (2483), and al-Ḍiyāʾ in al-Mukhtārah (8/354–355).","chapter_en":"The Permissibility of Ruqyah with the Qur’an and Both Reported and Unreported Supplications, Provided They Contain No Polytheism","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated: I used to perform ruqyah during the time of ignorance for afflictions caused by the evil eye. After I embraced Islam, I mentioned it to the Messenger of Allah ﷺ. He said: “Present it to me.” I presented it to him, and he said: “Perform ruqyah with it, for there is no harm in it.” ʿUbādah said: “Had it not been for that, I would never have performed ruqyah with it for anyone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى، كما في المطالب العالية (2483)، والضياء في المختارة (434)."},{"num":11474,"demo":false,"sanad":"","matn":["عَنِ الْجُعَيْدِ، قَالَ سَمِعْتُ السَّائِبَ، يَقُولُ: ذَهَبَتْ بِي خَالَتِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنَّ ابْنَ أُخْتِي وَجِعٌ، فَمَسَحَ رَأْسِي وَدَعَا لِي بِالْبَرَكَةِ."],"takhrij":"متفق عليه: رواه البخاري في المرضى (5670)، ومسلم في الفضائل (2345) كلاهما من حديث حاتم بن إسماعيل، عن الجعد بن عبدالرحمن، قال: سمعت السائب بن يزيد يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5670) and Muslim (2345).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Al-Sā’ib ibn Yazīd narrated: My maternal aunt took me to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my sister’s son is ill.” He wiped my head and supplicated for blessing for me."]}},"tuhfa":{},"full":1,"rep":[3476],"tks":"متفق عليه: رواه البخاري (5670)، ومسلم (2345)."},{"num":11475,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن رسول الله صلى الله عليه وسلم قال: إذا اشتكى أحدكم فليضع يده حيث يشتكي، ثم يقول: بسم الله، أعوذ بعزة الله وقدرته من شر ما أجد من وَجَعي هذا، ثم يرفع يده ثم يُعيد ذلك وتراً."],"takhrij":"حسن: رواه الترمذي (3588)، وصحّحه الحاكم (7515) من حديث عبد الوارث بن عبد الصمد، حدثني أبي، حدثنا محمد بن سالم، حدثنا ثابت البناني، عن أنس بن مالك فذكر الحديث.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3588) and authenticated by al-Ḥākim (7515).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “When one of you experiences pain, let him place his hand upon the place that hurts and say: ‘In the name of Allah. I seek refuge in Allah’s might and power from the evil of this pain that I feel.’ He should then lift his hand and repeat that an odd number of times.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3479],"tks":"حسن: رواه الترمذي (3588)، وصححه الحاكم (7515)."},{"num":11476,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَرْقِي يَقُولُ: امْسَحِ الْبَاسَ رَبَّ النَّاسِ، بِيَدِكَ الشِّفَاءُ، لاَ كَاشِفَ لَهُ إِلاَّ أَنْتَ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5744)، ومسلم في السلام (2191: 49) كلاهما من حديث هشام بن عروة، عن أبيه، عن عائشة فذكرته. واللفظ للبخاري، ولفظ مسلم نحوه وليس فيه: \"امسح البأس\" وإنما فيه: \"اذهب البأس\".","grade":"متفق عليه","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5744) and Muslim (2191/49). The wording cited here is that of al-Bukhārī.","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ used to perform ruqyah, saying: “Remove the affliction, Lord of mankind. Healing is in Your hand; no one can remove it except You.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5744)، ومسلم (2191: 49)، واللفظ للبخاري."},{"num":11477,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اشْتَكَى مِنَّا إِنْسَانٌ مَسَحَهُ بِيَمِينِهِ، ثُمَّ قَالَ: أَذْهِبِ الْبَاسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا. فَلَمَّا مَرِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَثَقُلَ، أَخَذْتُ بِيَدِهِ لِأَصْنَعَ بِهِ نَحْوَ مَا كَانَ يَصْنَعُ، فَانْتَزَعَ يَدَهُ مِنْ يَدِي ثُمَّ قَالَ: اللَّهُمَّ اغْفِرْ لِي وَاجْعَلْنِي مَعَ الرَّفِيقِ الْأَعْلَى.","قَالَتْ: فَذَهَبْتُ أَنْظُرُ فَإِذَا هُوَ قَدْ قَضَى."],"takhrij":"متفق عليه: رواه مسلم في السلام (2191: 46) من طرق عن جرير، عن الأعمش، عن أبي الضحى، عن مسروق، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2191/46) and al-Bukhārī (5743).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated: Whenever one of us became ill, the Messenger of Allah ﷺ would wipe him with his right hand and say: “Remove the affliction, Lord of mankind, and heal, for You are the Healer. There is no healing except Your healing—a healing that leaves no illness behind.” When the Messenger of Allah ﷺ became ill and his condition grew severe, I took his hand intending to do with it as he used to do. He withdrew his hand from mine and said: “O Allah, forgive me and place me with the Highest Companion.” She said: “I then looked at him and found that he had passed away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2191: 46)، والبخاري (5743)."},{"num":11478,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْعَزِيزِ، قَالَ: دَخَلْتُ أَنَا وَثَابِتٌ، عَلَى أَنَسِ بْنِ مَالِكٍ فَقَالَ ثَابِتٌ: يَا أَبَا حَمْزَةَ! اشْتَكَيْتُ. فَقَالَ أَنَسٌ: أَلاَ أَرْقِيكَ بِرُقْيَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: بَلَى. قَالَ اللَّهُمَّ رَبَّ النَّاسِ، مُذْهِبَ الْبَاسِ، اشْفِ أَنْتَ الشَّافِي، لاَ شَافِيَ إِلاَّ أَنْتَ، شِفَاءً لاَ يُغَادِرُ سَقَمًا."],"takhrij":"صحيح: رواه البخاري في الطب (5742) عن مسدد، حدثنا","grade":"صحيح","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5742).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbd al-ʿAzīz ibn Ṣuhayb narrated: Thābit and I entered upon Anas ibn Mālik. Thābit said: “Abū Ḥamzah, I am ill.” Anas replied: “Shall I perform ruqyah for you with the ruqyah of the Messenger of Allah ﷺ?” He replied: “Yes.” Anas then said: “O Allah, Lord of mankind, Remover of affliction, heal, for You are the Healer. There is no healer except You—a healing that leaves no illness behind.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3469],"tks":"صحيح: رواه البخاري (5742)."},{"num":11479,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ السَّائِبِ، ابْنِ أَخِي مَيْمُونَةَ الْهِلَالِيَّةِ، أَنَّهُ حَدَّثَهُ أَنَّ مَيْمُونَةَ، قَالَتْ لَهُ: يَا ابْنَ أَخِي، أَلَا أَرْقِيكَ بِرُقْيَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قُلْتُ: بَلَى، قَالَتْ: بِسْمِ اللَّهِ أَرْقِيكَ، وَاللهُ يَشْفِيكَ، مِنْ كُلِّ دَاءٍ فِيكَ، أَذْهِبِ الْبَاسَ، رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لَا شَافِيَ إِلَّا أَنْتَ."],"takhrij":"حسن: رواه أحمد (26821)، والطبراني في الكبير (23/438)، وصحّحه ابن حبان (6095) كلهم من حديث معاوية بن صالح، عن أزهر بن سعيد، عن عبد الرحمن بن السائب فذكره.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26821), al-Ṭabarānī in al-Muʿjam al-Kabīr (23/438), and authenticated by Ibn Ḥibbān (6095).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn al-Sā’ib, the nephew of Maymūnah al-Hilāliyyah, narrated that Maymūnah said to him: “My nephew, shall I perform ruqyah for you with the ruqyah of the Messenger of Allah ﷺ?” I replied: “Yes.” She said: “In the name of Allah, I perform ruqyah for you, and Allah will heal you from every illness within you. Remove the affliction, Lord of mankind, and heal, for You are the Healer. There is no healer except You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26821)، والطبراني في الكبير (23/438)، وصححه ابن حبان (6095)."},{"num":11480,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ  أَنَّ جِبْرِيلَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ، اشْتَكَيْتَ؟ فَقَالَ: نَعَمْ، قَالَ: بِاسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللهُ يَشْفِيكَ، بِاسْمِ اللَّهِ أَرْقِيكَ."],"takhrij":"صحيح: رواه مسلم في السلام (2186) عن بشر بن هلال الصواف، حدثنا عبد الوارث، حدثنا عبدالعزيز بن صُهيب، عن أبي نَضْرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2186).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd narrated: Gabriel came to the Prophet ﷺ and asked: “O Muḥammad, are you suffering from illness?” He replied: “Yes.” Gabriel said: “In the name of Allah, I perform ruqyah for you from everything that harms you, from the evil of every soul and every envious eye. May Allah heal you. In the name of Allah, I perform ruqyah for you.”"]}},"tuhfa":{},"full":1,"rep":[627,3471,13824],"tks":"صحيح: رواه مسلم (2186)."},{"num":11481,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ إِذَا اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَقَاهُ جِبْرِيلُ قَالَ: بِاسْمِ اللَّهِ يُبْرِيكَ، من كُلِّ دَاءٍ يَشْفيك، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ، وَشَرِّ كُلِّ ذِي عَيْنٍ."],"takhrij":"صحيح: رواه مسلم في السلام (2185) عن محمد بن أبي عمر المكي، حدثنا عبد العزيز الدراوردي، عن يزيد (وهو ابن عبدالله بن أسامة بن الهاد) عن محمد بن إبراهيم، عن أبي سلمة بن عبدالرحمن، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2185).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated: When the Messenger of Allah ﷺ became ill, Gabriel would perform ruqyah for him, saying: “In the name of Allah, may He cure you. May He heal you from every illness and protect you from the evil of an envier when he envies and from the evil of every possessor of the evil eye.”"]}},"tuhfa":{},"full":1,"rep":[3468],"tks":"صحيح: رواه مسلم (2185)."},{"num":11482,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ يَقُولُ: أَتَى جِبْرِيلُ عَلَيْهِ السَّلاَمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُوعَكُ فَقَالَ: بِسْمِ اللَّهِ أَرْقِيكَ، فِي كُلِّ شيء يُؤْذِيكَ، مِنْ حَسَدِ حَاسِدٍ، وَمِنْ كُلِّ عَيْنٍ، اللَّهُ يَشْفِيكَ."],"takhrij":"حسن: رواه ابن ماجه (3527) –واللفظ له- وأحمد (22760)، وصحّحه ابن حبان (953)، والحاكم (4/412) كلهم من طريق عبد الرحمن بن ثابت بن ثوبان، عن عمير بن هانئ أنه سمع جنادة بن أبي امية الكندي يقول: سمعت عبادة بن الصامت يقول: فذكره.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3527), whose wording is cited here, Aḥmad (22760), and authenticated by Ibn Ḥibbān (953) and al-Ḥākim (8268).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated: Gabriel, peace be upon him, came to the Prophet ﷺ while he was suffering from fever and said: “In the name of Allah, I perform ruqyah for you from everything that harms you, from the envy of an envier and from every evil eye. May Allah heal you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3527) واللفظ له، وأحمد (22760)، وصححه ابن حبان (953)، والحاكم (8268)."},{"num":11483,"demo":false,"sanad":"","matn":["عن عائشة بنت سعد أن أباه قال: تشكيت بمكة شكوى شديدة فجاءني النبي صلى الله عليه وسلم يعودني فوضع يَدَه على جبهتي، ثم مسح يديه على وجهي وبطني، ثم قال: اللهم اشف سعداً، وأتمم له هجرته فمازلت أجد بردَه على كبدي فيما يُخال إلى حتى الساعة."],"takhrij":"متفق عليه: رواه البخاري في المرضى (5659) عن المكي بن إبراهيم، أخبرنا الجُعيد، عن عائشة بنت سعد فذكرته.","grade":"متفق عليه","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5659) and Muslim (1628/8).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah bint Saʿd narrated that her father said: I became severely ill in Makkah, so the Prophet ﷺ came to visit me. He placed his hand upon my forehead, then wiped his hand over my face and abdomen, and said: “O Allah, heal Saʿd and complete his migration for him.” Saʿd said: “I continued to feel the coolness of his hand upon my liver, as it seemed to me, until that very hour.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3477],"tks":"متفق عليه: رواه البخاري (5659)، ومسلم (1628/8)."},{"num":11484,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ الثَّقَفِيِّ،  أَنَّهُ شَكَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعًا، يَجِدُهُ فِي جَسَدِهِ مُنْذُ أَسْلَمَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضَعْ يَدَكَ عَلَى الَّذِي تَأَلَّمَ مِنْ جَسَدِكَ، وَقُلْ: بِاسْمِ اللَّهِ - ثَلَاثًا، وَقُلْ سَبْعَ مَرَّاتٍ: أَعُوذُ بِاللهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ.","وفي لفظ عنه: أنه أتى رسول الله صلى الله عليه وسلم قال عثمان: وبي وجع قد كان يهلكني، قال: فقال رسول الله صلى الله عليه وسلم: امسحه بيمينك سبع مرات.وقل أعوذ بعزة الله وقدرته من شَرِّ ما أجد.","قال: فقلت ذلك.فأذهب الله ما كان بي.فلم أزل آمر بها.","أهلي وغيرهم."],"takhrij":"صحيح: رواه مسلم في السلام (2202) من طريق ابن وهب، أخبرني يونس، عن ابن شهاب، أخبرني نافع بن جبير بن مطعم، عن عثمان بن أبي العاس فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Muslim (2202) narrated the first wording, and Mālik (9) narrated the second.","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿUthmān ibn Abī al-ʿĀṣ al-Thaqafī narrated: He complained to the Messenger of Allah ﷺ about pain he had felt in his body since embracing Islam. The Messenger of Allah ﷺ said to him: “Place your hand upon the part of your body that hurts and say three times, ‘In the name of Allah.’ Then say seven times, ‘I seek refuge in Allah and His power from the evil of what I feel and fear.’” Another wording states that he came to the Messenger of Allah ﷺ and said: “I was suffering from pain that was nearly destroying me.” The Messenger of Allah ﷺ said: “Wipe it with your right hand seven times and say, ‘I seek refuge in Allah’s might and power from the evil of what I feel.’” ʿUthmān said: “I said it, and Allah removed what I was suffering from. Thereafter, I continued instructing my family and others to say it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2202) باللفظ الأول، ورواه مالك (9) باللفظ الثاني."},{"num":11485,"demo":false,"sanad":"","matn":["عن أَبِي التياح قَالَ: قُلْتُ: لِعَبْدِ الرَّحْمَنِ بْنِ خَنْبَشٍ التَّمِيمِيِّ، وَكَانَ كَبِيرًا، أَدْرَكْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، قَالَ: قُلْتُ: كَيْفَ صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ كَادَتْهُ الشَّيَاطِينُ، فَقَالَ: إِنَّ الشَّيَاطِينَ تَحَدَّرَتْ تِلْكَ اللَّيْلَةَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَوْدِيَةِ، وَالشِّعَابِ، وَفِيهِمْ شَيْطَانٌ، بِيَدِهِ شُعْلَةُ نَارٍ، يُرِيدُ أَنْ يُحْرِقَ بِهَا وَجْهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَهَبَطَ إِلَيْهِ جِبْرِيلُ، فَقَالَ: يَا مُحَمَّدُ قُلْ، قَالَ: مَا أَقُولُ؟ قَالَ: قُلْ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ شَرِّ مَا خَلَقَ، وَذَرَأَ، وَبَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ، يَا رَحْمَنُ، قَالَ: فَطَفِئَتْ نَارُهُمْ، وَهَزَمَهُمُ اللهُ تَبَارَكَ وَتَعَالَى."],"takhrij":"حسن: رواه أحمد (15460) عن سيار بن حاتم أبو سلمة العـنـزي، قال: حدثنا جعفر يعني ابن سليمان، قال: حدثنا أبو التياح قال: فذكره.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15460).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abū al-Tayyāḥ narrated: I asked ʿAbd al-Raḥmān ibn Khanbash al-Tamīmī, who had reached an advanced age: “Did you meet the Messenger of Allah ﷺ?” He replied: “Yes.” I asked: “What did the Messenger of Allah ﷺ do on the night when the devils plotted against him?” He replied: The devils descended upon the Messenger of Allah ﷺ that night from the valleys and mountain paths. Among them was a devil carrying a flame of fire with which he intended to burn the face of the Messenger of Allah ﷺ. Gabriel, peace be upon him, descended to him and said: “O Muḥammad, say.” He asked: “What should I say?” Gabriel replied: “Say: ‘I seek refuge in the perfect words of Allah from the evil of what He created, brought forth, and formed; from the evil of what descends from the sky and what ascends into it; from the evil trials of the night and day; and from the evil of every visitor by night, except a visitor who comes with good, O Most Merciful.’” The flames of the devils were extinguished, and Allah, Blessed and Exalted, defeated them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15460)."},{"num":11486,"demo":false,"sanad":"","matn":["عن محمد بن سالم حَدَّثَنَا ثَابِتٌ الْبُنَانِيُّ، قَالَ: قَالَ لِي يَا مُحَمَّدُ إِذَا اشْتَكَيْتَ، فَضَعْ يَدَكَ حَيْثُ تَشْتَكِي، وَقُلْ: بِسْمِ اللَّهِ أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ، مِنْ وَجَعِي هَذَا، ثُمَّ ارْفَعْ يَدَكَ، ثُمَّ أَعِدْ ذَلِكَ وِتْرًا فَإِنَّ أَنَسَ بْنَ مَالِكٍ حَدَّثَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَهُ بِذَلِكَ."],"takhrij":"حسن: رواه الترمذي (3588)، والحاكم (7515) كلاهما من حديث عبد الوارث بن عبد الصمد قال: حدثني أبي قال: حدثنا محمد بن سالم فذكره.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3588) and al-Ḥākim (7515).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Muḥammad ibn Sālim narrated: Thābit al-Bunānī said to me: “Muḥammad, when you experience pain, place your hand upon the place that hurts and say: ‘In the name of Allah. I seek refuge in Allah’s might and power from the evil of this pain that I feel.’ Then lift your hand and repeat it an odd number of times.” Anas ibn Mālik narrated to me that the Messenger of Allah ﷺ had taught him this."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3588)، والحاكم (7515)."},{"num":11487,"demo":false,"sanad":"","matn":["عن محمد بن حاطب انْصَبَّتْ عَلَى يَدِي مِنْ قِدْرٍ، فَذَهَبَتْ بِي أُمِّي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ فِي مَكَانٍ، قَالَ: فَقَالَ كَلَامًا فِيهِ: أَذْهِبِ الْبَأْسَ، رَبَّ النَّاسْ - وَأَحْسِبُهُ قَالَ: - اشْفِ أَنْتَ الشَّافِي قَالَ: وَكَانَ يَتْفُلُ."],"takhrij":"حسن: رواه أحمد (15452) عن يحيى بن سعيد، عن شعبة، عن سماك، قال: قال محمد بن حاطب فذكره.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15452).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Muḥammad ibn Ḥāṭib narrated: A cooking pot spilled upon my hand, so my mother took me to the Messenger of Allah ﷺ while he was in a certain place. He said words which included: “Remove the affliction, Lord of mankind.” I believe he also said: “Heal, for You are the Healer.” He would also blow lightly with a small amount of saliva."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3470],"tks":"حسن: رواه أحمد (15452)."},{"num":11488,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ عَادَ مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ فَقَالَ عِنْدَهُ سَبْعَ مِرَارٍ: أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ إِلاَّ عَافَاهُ اللَّهُ مِنْ ذَلِكَ الْمَرَضِ."],"takhrij":"حسن: رواه أبو داود (3106)، والترمذي (2083)، وأحمد (2137)، والحاكم (1268) كلهم من طريق شعبة، عن يزيد أبي خالد، عن المنهال بن عمرو، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب رقية النبي ﷺ ووضع اليد على الوجع","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3106), al-Tirmidhī (2083), Aḥmad (2137), and al-Ḥākim (1268).","chapter_en":"The Prophet’s Ruqyah and Placing the Hand upon the Place of Pain","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “Whoever visits a sick person whose appointed time of death has not yet arrived and says beside him seven times, ‘I ask Allah the Magnificent, Lord of the Magnificent Throne, to heal you,’ Allah will grant him recovery from that illness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3106)، والترمذي (2083)، وأحمد (2137)، والحاكم (1268)."},{"num":11489,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ إِذَا اشْتَكَى الْإِنْسَانُ الشَّيْءَ مِنْهُ، أَوْ كَانَتْ بِهِ قَرْحَةٌ أَوْ جَُرْحٌ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِصْبَعِهِ هَكَذَا - وَوَضَعَ سُفْيَانُ سَبَّابَتَهُ بِالْأَرْضِ ثُمَّ رَفَعَهَا: بِاسْمِ اللَّهِ، تُرْبَةُ أَرْضِنَا، بِرِيقَةِ بَعْضِنَا، لِيُشْفَى بِهِ سَقِيمُنَا بِإِذْنِ رَبِّنَا."],"takhrij":"متفق عليه: رواه البخاري في الطب (5745)، ومسلم في السلام (2194: 54) من طريق سفيان (هو ابن عيينة)، ثني عبدُربه بن سعيد، عن عمرة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب أخذ التربة عند الرقية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5745) and Muslim (2194/54). The sequence cited here is that of Muslim.","chapter_en":"Using Soil When Performing Ruqyah","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah narrated: When a person suffered from an illness, ulcer, or wound, the Messenger of Allah ﷺ would do this with his finger—Sufyān placed his index finger upon the ground and then raised it—and say: “In the name of Allah. The soil of our land, mixed with the saliva of one of us, is a means by which our sick person may be healed, by the permission of our Lord.”"]},"buhuth":{"en":["Regarding the words “the soil of our land,” the majority of scholars said that they refer to the earth generally. Therefore, each person may do this using the soil of the land in which he resides.","Al-Nawawī explained the meaning of the hadith:","“A person places some of his saliva upon his index finger, then places it upon the soil so that some soil adheres to it. He then wipes it over the wounded or painful area while reciting these words.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5745)، ومسلم (2194: 54)، والسياق لمسلم."},{"num":11490,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْعَيْنُ حَقٌّ. وَنَهَى عَنِ الْوَشْمِ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5740)، ومسلم في السلام (2187) كلاهما من طريق عبد الرزاق، ثنا معمر، عن همام بن منبه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب أن العين حق","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5740) and Muslim (2187).","chapter_en":"The Evil Eye Is Real","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The evil eye is real.” He also prohibited tattooing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5740)، ومسلم (2187)."},{"num":11491,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  الْعَيْنُ حَقٌّ، وَلَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ سَبَقَتْهُ الْعَيْنُ، وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا."],"takhrij":"صحيح: رواه مسلم في السلام (2188) من طرق عن مسلم بن إبراهيم، ثنا وهيب، عن ابن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب أن العين حق","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2188).","chapter_en":"The Evil Eye Is Real","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “The evil eye is real. If anything could precede the divine decree, the evil eye would precede it. When you are asked to wash for someone affected by your evil eye, then wash.”"]}},"tuhfa":{},"full":1,"rep":[990,11499],"tks":"صحيح: رواه مسلم (2188)."},{"num":11492,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  رَخَّصَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِآلِ حَزْمٍ فِي رُقْيَةِ الْحَيَّةِ، وَقَالَ لِأَسْمَاءَ بِنْتِ عُمَيْسٍ: مَا لِي أَرَى أَجْسَامَ بَنِي أَخِي ضَارِعَةً تُصِيبُهُمُ الْحَاجَةُ! قَالَتْ: لَا، وَلَكِنِ الْعَيْنُ تُسْرِعُ إِلَيْهِمْ. قَالَ: ارْقِيهِمْ. قَالَتْ: فَعَرَضْتُ عَلَيْهِ، فَقَالَ: ارْقِيهِمْ."],"takhrij":"صحيح: رواه مسلم في السلام (2198) عن عقبة بن مكرم العمي، حدثنا أبو عاصم، عن ابن جريج قال: وأخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب أن العين حق","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2198).","chapter_en":"The Evil Eye Is Real","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Prophet ﷺ granted the family of Ḥazm permission to perform ruqyah for snakebites. He said to Asmāʾ bint ʿUmays: “Why do I see the bodies of my brother’s children appearing thin? Are they suffering from poverty?” She replied: “No, but they are quickly affected by the evil eye.” He said: “Perform ruqyah for them.” She presented the ruqyah formula to him, and he said: “Perform ruqyah for them.”"]},"buhuth":{"en":["The word ḍāriʿah means thin. The expression “my brother’s children” refers to the children of Jaʿfar ibn Abī Ṭālib, since Asmāʾ bint ʿUmays was Jaʿfar’s wife. The word ḥājah means poverty or need, as orphanhood is often associated with poverty."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11496],"tks":"صحيح: رواه مسلم (2198)."},{"num":11493,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ عُمَيْسٍ قَالَتْ: يَا رَسُولَ اللَّهِ إِنَّ وَلَدَ جَعْفَرٍ تُسْرِعُ إِلَيْهِمُ الْعَيْنُ، أَفَأَسْتَرْقِي لَهُمْ؟ فَقَالَ: نَعَمْ، فَإِنَّهُ لَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ لَسَبَقَتْهُ الْعَيْنُ."],"takhrij":"حسن: رواه الترمذي (2059)، وابن ماجه (3510)، وأحمد (27470) كلهم من طريق سفيان، عن عمرو بن دينار، عن عروة بن عامر، عن عبيد بن رفاعة الزرقي، قال: قالت أسماء بنت عميس فذكرته.","grade":"حسن","chapter_ar":"باب أن العين حق","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2059), Ibn Mājah (3510), and Aḥmad (27470).","chapter_en":"The Evil Eye Is Real","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Asmāʾ bint ʿUmays said: “O Messenger of Allah, the children of Jaʿfar are quickly affected by the evil eye. May I have ruqyah performed for them?” He replied: “Yes. If anything could precede the divine decree, the evil eye would precede it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2059)، وابن ماجه (3510)، وأحمد (27470)."},{"num":11494,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ: جُلُّ مَنْ يَمُوتُ مِنْ أُمَّتِي، بَعْدَ قَضَاءِ اللَّهِ وَكِتَابِهِ وَقَدَرِهِ، بِالْأَنْفُسِ يَعْنِي بِالْعَيْنِ."],"takhrij":"حسن: رواه أبو داود الطيالسي (1868) عن طالب بن حبيب بن عمرو بن سهل ضجيع حمزة قال: سمعت عبد الرحمن بن جابر بن عبد الله الأنصاري، عن أبيه فذكره.ومن طريقه رواه ابن أبي عاصم في السنة (311)، والبزار (كشف الأستار-3052).","grade":"حسن","chapter_ar":"باب أن العين حق","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd al-Ṭayālisī (1868), Ibn Abī ʿĀṣim in al-Sunnah (311), and al-Bazzār in Kashf al-Astār (3050).","chapter_en":"The Evil Eye Is Real","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “Most of those who die from my nation, after Allah’s decree, His written judgment, and His predestination, die because of the evil eye.” The expression “because of souls” means because of the evil eye."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود الطيالسي (1868)، وابن أبي عاصم في السنة (311)، والبزار في كشف الأستار (كشف الأستار-3052)."},{"num":11495,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنِي أَنْ أَسْتَرْقِيَ مِنَ الْعَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5738)، ومسلم في السلام (2195) كلاهما من طريق سفيان (هو الثوري)، حدثني معبد بن خالد، قال: سمعت عبد الله بن شداد، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرقية من العين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5738) and Muslim (2195).","chapter_en":"What Has Been Reported Concerning Ruqyah for the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Messenger of Allah ﷺ used to instruct me to have ruqyah performed for the evil eye.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5738)، ومسلم (2195)."},{"num":11496,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  رَخَّصَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِآلِ حَزْمٍ فِي رُقْيَةِ الْحَيَّةِ، وَقَالَ لِأَسْمَاءَ بِنْتِ عُمَيْسٍ: مَا لِي أَرَى أَجْسَامَ بَنِي أَخِي ضَارِعَةً تُصِيبُهُمُ الْحَاجَةُ! قَالَتْ: لَا، وَلَكِنِ الْعَيْنُ تُسْرِعُ إِلَيْهِمْ. قَالَ: ارْقِيهِمْ. قَالَتْ: فَعَرَضْتُ عَلَيْهِ، فَقَالَ: ارْقِيهِمْ."],"takhrij":"صحيح: رواه مسلم في السلام (2198) عن عقبة بن مكرم العمي، حدثنا أبو عاصم، عن ابن جريج قال: وأخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرقية من العين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2198).","chapter_en":"What Has Been Reported Concerning Ruqyah for the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Prophet ﷺ granted the family of Ḥazm permission to perform ruqyah for snakebites. He said to Asmāʾ bint ʿUmays: “Why do I see the bodies of my brother’s children appearing thin? Are they suffering from poverty?” She replied: “No, but they are quickly affected by the evil eye.” He said: “Perform ruqyah for them.” She presented the ruqyah formula to him, and he said: “Perform ruqyah for them.”"]},"buhuth":{"en":["The word ḍāriʿah means thin. The expression “my brother’s children” refers to Jaʿfar ibn Abī Ṭālib and his three sons: ʿAbdullāh, ʿAwn, and Muḥammad. Jaʿfar’s surviving line continued through ʿAbdullāh, as mentioned in Tanbīh al-Muʿallim (911). The word ḥājah means poverty or need, as orphanhood is often associated with poverty."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11492],"tks":"صحيح: رواه مسلم (2198)."},{"num":11497,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِجَارِيَةٍ فِي بَيْتِ أُمِّ سَلَمَةَ رَأَى بِوَجْهِهَا سَفْعَةً فَقَالَ: بِهَا نَظْرَةٌ، فَاسْتَرْقُوا لَهَا يَعْنِي بِوَجْهِهَا صُفْرَةً."],"takhrij":"متفق عليه: رواه البخاري في الطب (5739)، ومسلم في السلام (2197) كلاهما من طريق محمد بن حرب، ثني محمد بن الوليد الزبيدي، أخبرنا الزهري، عن عروة بن الزبير، عن زينب بنت أبي سلمة، عن أم سلمة فذكرته","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرقية من العين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5739) and Muslim (2197).","chapter_en":"What Has Been Reported Concerning Ruqyah for the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated: The Messenger of Allah ﷺ saw a young girl in Umm Salamah’s house whose face had a discoloration. He said: “She has been affected by an evil eye, so have ruqyah performed for her.” The discoloration meant that her face had a yellowish appearance."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5739)، ومسلم (2197)."},{"num":11498,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ يُؤْمَرُ الْعَائِنُ فَيَتَوَضَّأُ، ثُمَّ يَغْتَسِلُ مِنْهُ الْمَعِينُ."],"takhrij":"صحيح: رواه أبو داود (3880)، وابن أبي شيبة (24062)، والطحاوي في شرح المشكل (2893) كلهم من طرق عن الأعمش، عن إبراهيم (هو ابن يزيد النخعي) عن الاسود (هو ابن يزيد النخعي)، عن عائشة فذكرته.واللفظ لأبي داود.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب علاج من أصيب بالعين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3880), Ibn Abī Shaybah (24062), and al-Ṭaḥāwī in Sharḥ Mushkil al-Āthār (2893). The wording cited here is that of Abū Dāwūd.","chapter_en":"Treating the Person Who Has Been Afflicted by the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The person who had cast the evil eye would be ordered to perform ablution, and the person afflicted by the evil eye would then wash with that water.”"]},"buhuth":{"en":["The word al-ʿāʾin refers to the person who afflicted another through the evil eye. The word al-maʿīn refers to the person who was afflicted by another’s evil eye."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3880)، وابن أبي شيبة (24062)، والطحاوي في شرح مشكل الآثار (2893)، واللفظ لأبي داود."},{"num":11499,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  الْعَيْنُ حَقٌّ، وَلَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ سَبَقَتْهُ الْعَيْنُ، وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا."],"takhrij":"صحيح: رواه مسلم في السلام (2188) من طرق عن مسلم بن إبراهيم، ثنا وهيب، عن ابن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب علاج من أصيب بالعين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2188).","chapter_en":"Treating the Person Who Has Been Afflicted by the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “The evil eye is real. If anything could precede the divine decree, the evil eye would precede it. When you are asked to wash for someone afflicted by your evil eye, then wash.”"]}},"tuhfa":{},"full":1,"rep":[990,11491],"tks":"صحيح: رواه مسلم (2188)."},{"num":11500,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سهل بْنِ حُنَيْفٍ، يَقُولُ: اغْتَسَلَ أَبِي سَهْلُ بْنُ حُنَيْفٍ بِالْخَرَّارِ، فَنَزَعَ جُبَّةً كَانَتْ عَلَيْهِ، وَعَامِرُ بْنُ رَبِيعَةَ يَنْظُرُ، قَالَ: وَكَانَ سَهْلٌ رَجُلًا أَبْيَضَ، حَسَنَ الْجِلْدِ، قَالَ: فَقَالَ لَهُ عَامِرُ بْنُ رَبِيعَةَ: مَا رَأَيْتُ كَالْيَوْمِ، وَلَا جِلْدَ عَذْرَاءَ، قَالَ: فَوُعِكَ مَكَانَهُ، واشتد وَعَكُهُ، فأتي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فأخبر أَنَّ سَهْلًا وُعِكَ، وَأَنَّهُ غَيْرُ رَائِحٍ مَعَكَ يَا رَسُولَ اللَّهِ، فَأَتَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَأَخْبَرَهُ سَهْلٌ بالَّذِي كَانَ مِنْ شَأْنِ عَامِرِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلَامَ يَقْتُلُ أَحَدُكُمْ أَخَاهُ، أَلَا بَرَّكْتَ، إِنَّ الْعَيْنَ حَقٌّ، تَوَضَّأْ لَهُ، فَتَوَضَّأَ لَهُ عَامِرُ بْنُ رَبِيعَةَ، فَرَاحَ سَهْلٌ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، لَيْسَ بِهِ بَأْسٌ."],"takhrij":"صحيح: رواه مالك في العين (1) عن محمد بن ابي أمامة بن سهل بن حنيف، عن أبيه فذكره.ومن طريق مالك رواه النسائي في الكبرى (7570)، وابن حبان في صحيحه (6105).","grade":"صحيح","chapter_ar":"باب علاج من أصيب بالعين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (1), al-Nasā’ī in al-Sunan al-Kubrā (7570), and Ibn Ḥibbān (6105).","chapter_en":"Treating the Person Who Has Been Afflicted by the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf narrated: My father, Sahl ibn Ḥunayf, bathed at al-Kharrār and removed a cloak he was wearing while ʿĀmir ibn Rabīʿah was watching him. Sahl was a fair-skinned man with beautiful skin. ʿĀmir ibn Rabīʿah said: “I have never seen anything like what I see today—not even the skin of a sheltered virgin.” Sahl immediately became ill, and his illness became severe. The Messenger of Allah ﷺ was informed: “Sahl has become ill and cannot travel with you, O Messenger of Allah.” The Messenger of Allah ﷺ went to him, and Sahl informed him about what had happened with ʿĀmir. The Messenger of Allah ﷺ said: “Why would one of you kill his brother? Why did you not invoke blessing for him? The evil eye is real. Perform ablution for him.” ʿĀmir ibn Rabīʿah performed ablution for him, and Sahl then traveled with the Messenger of Allah ﷺ with no illness remaining."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (1)، والنسائي في الكبرى (7570)، وابن حبان (6105)."},{"num":11501,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سهل بْنِ حُنَيْفٍ، أنه قَالَ: رَأَى عَامِرُ بْنُ رَبِيعَةَ سَهْلَ بْنَ حُنَيْفٍ يَغْتَسِلُ، فَقَالَ: مَا رَأَيْتُ كَالْيَوْمِ، وَلَا جِلْدَ مُخَبَّأَةٍ، فَلُبِطَ سَهْلٌ مَكَانَهُ، فأتي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقِيلَ: يَا رَسُولَ اللَّهِ، هَلْ لَكَ فِي سَهْلِ بْنِ حُنَيْفٍ؟ وَاللهِ مَا يَرْفَعُ رَأْسَهُ، فَقَالَ: هَلْ تَتَّهِمُونَ لَهُ أَحَدًا؟ قَالُوا: نَتَّهِمُ عَامِرَ بْنَ رَبِيعَةَ، قَالَ: فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامِرًا، فَتَغَيَّظَ عَلَيْهِ، وَقَالَ: عَلَامَ يَقْتُلُ أَحَدُكُمْ أَخَاهُ، أَلَا بَرَّكْتَ، اغتسل لَهُ، فَغَسَلَ عَامِرٌ وَجْهَهُ وَيَدَيْهِ، وَمِرْفَقَيْهِ وَرُكْبَتَيْهِ، وَأَطْرَافَ رِجْلَيْهِ، وَدَاخِلَةَ إِزَارِهِ فِي قَدَحٍ، ثُمَّ صَبَّ عَلَيْهِ، فَرَاحَ سَهْلٌ مَعَ النَّاسِ لَيْسَ بِهِ بَأْسٌ."],"takhrij":"صحيح: رواه مالك في العين (2) عن ابن شهاب، عن أبي أمامة بن سهل بن حنيف فذكره.ورواه النسائي في الكبرى (7571-7572)، وابن ماجه (3509)، و ابن حبان (6106)، والحاكم (3/410-411) كلهم من طرق عن الزهري، عن أبي أمامة به مرسلا.","grade":"صحيح","chapter_ar":"باب علاج من أصيب بالعين","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (2), al-Nasā’ī in al-Sunan al-Kubrā (7571, 7572), Ibn Mājah (3509), and authenticated by Ibn Ḥibbān (6106).","chapter_en":"Treating the Person Who Has Been Afflicted by the Evil Eye","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf narrated: ʿĀmir ibn Rabīʿah saw Sahl ibn Ḥunayf bathing and said: “I have never seen anything like what I see today—not even the skin of a secluded woman.” Sahl immediately collapsed where he stood. The Messenger of Allah ﷺ was approached and told: “O Messenger of Allah, can you do something for Sahl ibn Ḥunayf? By Allah, he cannot even raise his head.” He asked: “Do you suspect anyone of having affected him?” They replied: “We suspect ʿĀmir ibn Rabīʿah.” The Messenger of Allah ﷺ summoned ʿĀmir, became angry with him, and said: “Why would one of you kill his brother? Why did you not invoke blessing for him? Wash for him.” ʿĀmir washed his face, hands, elbows, knees, the ends of his feet, and the inner part of his lower garment in a vessel. The water was then poured over Sahl, after which he went with the people in good health."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (2)، والنسائي في الكبرى (7571، 7572)، وابن ماجه (3509)، وصححه ابن حبان (6106)."},{"num":11502,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: رخّص النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرُّقْيَةَ مِنْ كُلِّ ذِي حُمَةٍ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5741)، ومسلم في السلام (2193: 52) كلاهما من طريق سليمان الشيباني، ثنا عبد الرحمن بن الأسود، عن أبيه قال: سألت عائشة عن الرقية من الحمة فذكرته.","grade":"متفق عليه","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5741) and Muslim (2193/52).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Prophet ﷺ permitted ruqyah for every venomous creature.”"]},"buhuth":{"en":["The word ḥumah means venom. It is also used for the stinger of a scorpion because the venom emerges from it. Al-Khaṭṭābī said that it refers to every venomous creature, such as a snake or scorpion."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5741)، ومسلم (2193: 52)."},{"num":11503,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: رَخَّصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الرُّقْيَةِ مِنَ الْحَيَّةِ وَالْعَقْرَبِ."],"takhrij":"صحيح: رواه ابن ماجه (3517)، وصحّحه ابن حبان (6101) كلاهما من حديث أبي الأحوص، عن مغيرة، عن إبراهيم، عن الاسود، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3517) and authenticated by Ibn Ḥibbān (6101).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Messenger of Allah ﷺ permitted ruqyah for snakebites and scorpion stings.”"]},"buhuth":{"en":["Muslim narrated through another route:","“The Messenger of Allah ﷺ permitted a household from among the Anṣār to perform ruqyah for venomous stings.”","Narrated by Muslim (2193/53)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3517)، وصححه ابن حبان (6101)."},{"num":11504,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  أَرْخَصَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رُقْيَةِ الْحَيَّةِ لِبَنِي عَمْرٍو، قَالَ أَبُو الزُّبَيْرِ: وَسَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ يَقُولُ: لَدَغَتْ رَجُلًا مِنَّا عَقْرَبٌ، وَنَحْنُ جُلُوسٌ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَرْقِي؟ قَالَ: مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ فَلْيَفْعَلْ."],"takhrij":"صحيح: رواه مسلم في السلام (2199: 61) عن محمد بن حاتم، ثنا روح بن عبادة، ثنا ابن جريج، أخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2199/61).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Prophet ﷺ granted Banū ʿAmr permission to perform ruqyah for snakebites. Abū al-Zubayr said: I also heard Jābir ibn ʿAbdullāh say: A man from among us was stung by a scorpion while we were sitting with the Messenger of Allah ﷺ. A man asked: “O Messenger of Allah, may I perform ruqyah for him?” He replied: “Whoever among you is able to benefit his brother should do so.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2199: 61)."},{"num":11505,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ كَانَ لِي خَالٌ يَرْقِي مِنَ الْعَقْرَبِ فَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  عَنِ الرُّقَى - قَالَ: - فَأَتَاهُ فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّكَ نَهَيْتَ عَنِ الرُّقَى وَأَنَا أَرْقِي مِنَ الْعَقْرَبِ. فَقَالَ: مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ فَلْيَفْعَلْ."],"takhrij":"صحيح: رواه مسلم في السلام (2199: 62) من طرق عن وكيع، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in Kitāb al-Salām (2199/62).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Jābir narrated: I had a maternal uncle who used to perform ruqyah for scorpion stings. The Messenger of Allah ﷺ prohibited ruqyah, so my uncle came to him and said: “O Messenger of Allah, you have prohibited ruqyah, but I perform ruqyah for scorpion stings.” He replied: “Whoever among you is able to benefit his brother should do so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2199: 62)."},{"num":11506,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ رُقْيَةَ إِلاَّ مِنْ عَيْنٍ أَوْ حُمَةٍ."],"takhrij":"صحيح: رواه أبو داود (3884)، وأحمد (19908) كلاهما من طريق مالك بن مغول-، والترمذي (2057) من طريق سفيان (هو ابن عيينة)- كلاهما من طريق حصين (هو ابن عبد الرحمن السلمي)، عن الشعبي، عن عمران بن حصين فذكره مرفوعا.","grade":"صحيح","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3884) and Aḥmad (19908).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated that the Prophet ﷺ said: “There is no ruqyah more appropriate than ruqyah for the evil eye or a venomous sting.”"]},"buhuth":{"en":["The words “There is no ruqyah except for the evil eye or a venomous sting” do not mean that ruqyah for other afflictions is impermissible. Rather, the meaning is that no ruqyah is more appropriate or beneficial than ruqyah for these two, just as it is said: “There is no young champion like ʿAlī.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3884)، وأحمد (19908)."},{"num":11507,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الْحُصَيْبِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ رُقْيَةَ إِلاَّ مِنْ عَيْنٍ أَوْ حُمَةٍ."],"takhrij":"صحيح: رواه ابن ماجه (3513) عن محمد بن عبد الله بن نمير قال: حدثنا إسحاق بن سليمان، عن أبي جعفر الرازي، عن حصين، عن الشعبي، عن بريدة فذكره مرفوعا.","grade":"صحيح","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3513).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb narrated that the Messenger of Allah ﷺ said: “There is no ruqyah more appropriate than ruqyah for the evil eye or a venomous sting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3513)."},{"num":11508,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  رَخَّصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الرُّقْيَةِ مِنَ الْعَيْنِ، وَالْحُمَةِ، وَالنَّمْلَةِ."],"takhrij":"صحيح: رواه مسلم في السلام (2196: 98) من طرق عن عاصم الأحول، عن يوسف بن عبد الله، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2196/98).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas narrated: “The Messenger of Allah ﷺ permitted ruqyah for the evil eye, venomous stings, and al-namlah.”"]},"buhuth":{"en":["Al-namlah refers to sores that appear upon a person’s side."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2196: 98)."},{"num":11509,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ طَلْقٍ، عَنْ أَبِيهِ، قَالَ: لَدَغَتْنِي عَقْرَبٌ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَقَانِي، وَمَسَحَهَا."],"takhrij":"حسن: رواه ابن حبان (6093)، والطبراني في الكبير (8/399-400)، والحاكم (8281) كلهم من حديث ملازم بن عمرو قال: حدثني عبد الله بن بدر، عن قيس فذكره.","grade":"حسن","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (6093), al-Ṭabarānī in al-Muʿjam al-Kabīr (8/399–400), and al-Ḥākim (8281).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Qays ibn Ṭalq narrated from his father: “A scorpion stung me while I was with the Prophet ﷺ, so he performed ruqyah for me and wiped the affected place.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (6093)، والطبراني في الكبير (8/399-400)، والحاكم (8281)."},{"num":11510,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: بَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ يُصَلِّي فَوَضَعَ يَدَهُ عَلَى الْأَرْضِ فَلَدَغَتْهُ عَقْرَبٌ، فَتَنَاوَلَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنَعْلِهِ فَقَتَلَهَا، فَلَمَّا انْصَرَفَ قَالَ: لَعَنَ اللَّهُ الْعَقْرَبَ، لَا تَدَعُ مُصَلِّيًا، وَلَا غَيْرَهُ، أَوْ نَبِيًّا، وَلَا غَيْرَهُ، إِلَّا لَدَغَتْهُمْ، ثُمَّ دَعَا بِمِلْحٍ وَمَاءٍ فَجَعَلَهُ فِي إِنَاءٍ، ثُمَّ جَعَلَ يَصُبُّهُ عَلَى إِصْبَعِهِ حَيْثُ لَدَغَتْهُ، وَيَمْسَحُهَا وَيُعَوِّذُهَا بِالْمُعَوِّذَتَيْنِ.","وَفِي رِوَايَةِ: ثُمَّ دَعَا بِمَاءٍ وملح، وَجَعَلَ يمسح عَلَيْهَا، وَيَقْرَأُ قُلْ هُوَ اللَّهُ أَحَدٌ وَ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ وَ قُلْ أَعُوذُ بِرَبِّ النَّاسِ."],"takhrij":"حسن: رواه ابن أبي شيبة (24019) –ومن طريقه البيهقي في الشعب (2340)- عن عبد الرحيم بن سليمان، عن مطرف (هو ابن طريف الكوفي)، عن المنهال بن عمرو، عن محمد بن علي ابن الحنفية، عن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب الرقية من الحمة، وهي السم، ويقال أيضًا للدغة العقرب والحية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Shaybah (24019), and through his route by al-Bayhaqī in Shuʿab al-Īmān (2340).","chapter_en":"Ruqyah for Venom, Including the Sting of a Scorpion and the Bite of a Snake","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAlī narrated: One night, while the Messenger of Allah ﷺ was praying, he placed his hand upon the ground and a scorpion stung him. The Messenger of Allah ﷺ took it with his sandal and killed it. When he finished praying, he said: “May Allah curse the scorpion. It spares neither a person praying nor anyone else—or neither a prophet nor anyone else.” He then called for salt and water, placed them in a vessel, and poured the mixture upon the finger where he had been stung. He wiped it and sought protection for it by reciting the two protective chapters. Another narration states: He called for water and salt, wiped the affected place with them, and recited: “Say: He is Allah, the One.” [Sūrat al-Ikhlāṣ 112:1] “Say: I seek refuge in the Lord of daybreak.” [Sūrat al-Falaq 113:1] “Say: I seek refuge in the Lord of mankind.” [Sūrat al-Nās 114:1]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة (24019)، ومن طريقه البيهقي في شعب الإيمان (2340)."},{"num":11511,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَكَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَذَا وَكَذَا يُخَيَّلُ إِلَيْهِ أَنَّهُ يَأْتِي أَهْلَهُ وَلاَ يَأْتِي، قَالَتْ عَائِشَةُ: فَقَالَ لِي ذَاتَ يَوْمٍ: يَا عَائِشَةُ إِنَّ اللَّهَ أَفْتَانِي فِي أَمْرٍ اسْتَفْتَيْتُهُ، فِيهِ، أَتَانِي رَجُلاَنِ، فَجَلَسَ أَحَدُهُمَا عِنْدَ رِجْلَىَّ، وَالآخَرُ عِنْدَ رَأْسِي، فَقَالَ الَّذِي عِنْدَ رِجْلَىَّ لِلَّذِي عِنْدَ رَأْسِي: مَا بَالُ الرَّجُلِ؟ قَالَ: مَطْبُوبٌ. يَعْنِي مَسْحُورًا. قَالَ: وَمَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ أَعْصَمَ. قَالَ: وَفِيمَ؟ قَالَ: فِي جُفِّ طَلْعَةٍ ذَكَرٍ فِي مُشْطٍ وَمُشَاقَةٍ، تَحْتَ رَعُوفَةٍ فِي بِئْرِ ذَرْوَانَ. فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ هَذِهِ الْبِئْرُ الَّتِي أُرِيتُهَا كَأَنَّ رُءُوسَ نَخْلِهَا رُءُوسُ الشَّيَاطِينِ، وَكَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ. فَأَمَرَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُخْرِجَ. قَالَتْ عَائِشَةُ فَقُلْتُ يَا رَسُولَ اللَّهِ فَهَلاَّ ـ تَعْنِي ـ تَنَشَّرْتَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا اللَّهُ فَقَدْ شَفَانِي، وَأَمَّا أَنَا فَأَكْرَهُ أَنْ أُثِيرَ عَلَى النَّاسِ شَرًّا.","قَالَتْ: وَلَبِيدُ بْنُ أَعْصَمَ رَجُلٌ مِنْ بَنِي زُرَيْقٍ حَلِيفٌ لِيَهُودَ."],"takhrij":"صحيح: رواه البخاري في الأدب (6063) عن الحميدي، حدثنا سفيان (هو: ابن عيينة) حدثنا هشام بن عروة عن أبيه عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6063).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Prophet ﷺ remained for a period of time imagining that he had relations with his wives when he had not done so. ʿĀ’ishah said: One day he said to me: “O ʿĀ’ishah, Allah has given me an answer concerning the matter about which I sought His judgment. Two men came to me. One sat near my feet and the other near my head. The one near my feet asked the one near my head, ‘What is wrong with this man?’ He replied, ‘He has been bewitched.’ He asked, ‘Who bewitched him?’ He replied, ‘Labīd ibn al-Aʿṣam.’ He asked, ‘In what was it placed?’ He replied, ‘In the sheath of a male date-palm blossom, together with a comb and hair caught in the comb, beneath a stone at the bottom of the well of Dharwān.’” The Prophet ﷺ went there and said: “This is the well that was shown to me. The tops of its palm trees resemble the heads of devils, and its water resembles water in which henna has been soaked.” The Prophet ﷺ ordered that the object be removed. ʿĀ’ishah said: I asked: “O Messenger of Allah, why did you not openly undo and expose the sorcery?” The Prophet ﷺ replied: “Allah has already healed me, and I dislike stirring up evil among the people.” ʿĀ’ishah said: “Labīd ibn al-Aʿṣam was a man from Banū Zurayq and an ally of the Jews.”"]},"buhuth":{"en":["The expression “Allah gave me an answer” means that Allah answered him concerning that for which he had supplicated. Some narrations identify the two men as Gabriel and Michael, while another mentions Gabriel alone. The soundest wording is that they were two men without naming them."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ، وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا، يُعَلِّمُونَ النَّاسَ السِّحْرَ، وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ، وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ، فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ، وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللّٰهِ، وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ، وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ، وَلَبِئْسَ مَا شَرَوْا بِهِ أَنْفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ﴾ [البقرة: ١٠٢].","وقال تعالى: ﴿قَالَ أَلْقُوا، فَلَمَّا أَلْقَوْا سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ﴾ [الأعراف: ١١٦].","وقال تعالى: ﴿فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ، إِنَّ اللّٰهَ سَيُبْطِلُهُ، إِنَّ اللّٰهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ﴾ [يونس: ٨١].","والآيات الأخرى كثيرة في ثبوت السحر. ولذا ذهب جمهور علماء أهل السنة إلى إثبات السحر، وأن له حقيقة كحقيقة غيره من الأشياء، ورتب على ذلك حكم تعلم السحر بأنه حرام، وهو من الكبائر بالإجماع، والحكم على الساحر بأنه يقتل كفرًا أو تعزيرًا، والمسألة مبسوطة في موضعها."],"en":["Allah, the Exalted, said:","“They followed what the devils recited during the reign of Solomon. Solomon did not disbelieve, but the devils disbelieved, teaching people sorcery and what had been sent down to the two angels in Babylon, Hārūt and Mārūt. Yet the two angels taught no one until they had said, ‘We are only a trial, so do not disbelieve.’ People learned from them that by which they caused separation between a man and his wife, although they could not harm anyone through it except by Allah’s permission. They learned what harmed them and did not benefit them. They certainly knew that whoever purchased it would have no share in the Hereafter. Miserable indeed was that for which they sold themselves, if only they knew.”","[Sūrat al-Baqarah 2:102]","He also said:","“He said, ‘Throw.’ When they threw, they bewitched the people’s eyes, terrified them, and produced a tremendous display of sorcery.”","[Sūrat al-Aʿrāf 7:116]","He also said:","“When they threw, Moses said, ‘What you have produced is sorcery. Allah will certainly nullify it. Indeed, Allah does not set right the work of corrupters.’”","[Sūrat Yūnus 10:81]","There are many other verses establishing the existence of sorcery. Accordingly, the majority of the scholars of Ahl al-Sunnah affirmed that sorcery exists and possesses a reality like that of other created things.","On this basis, they ruled that learning sorcery is prohibited and is unanimously regarded as a major sin. They also ruled that a sorcerer may be executed because of disbelief or as a discretionary punishment. The detailed discussion of this matter belongs elsewhere."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6063)."},{"num":11512,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُحِرَ حَتَّى كَانَ يَرَى أَنَّهُ يَأْتِي النِّسَاءَ وَلاَ يَأْتِيهِنَّ. قَالَ سُفْيَانُ: وَهَذَا أَشَدُّ مَا يَكُونُ مِنَ السِّحْرِ، إِذَا كَانَ كَذَا. فَقَالَ: يَا عَائِشَةُ أَعَلِمْتِ أَنَّ اللَّهَ قَدْ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ، أَتَانِي رَجُلاَنِ فَقَعَدَ أَحَدُهُمَا عِنْدَ رَأْسِي، وَالآخَرُ عِنْدَ رِجْلَىَّ، فَقَالَ الَّذِي عِنْدَ رَأْسِي لِلآخَرِ: مَا بَالُ الرَّجُلِ؟ قَالَ: مَطْبُوبٌ. قَالَ وَمَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ أَعْصَمَ، رَجُلٌ مِنْ بَنِي زُرَيْقٍ حَلِيفٌ لِيَهُودَ، كَانَ مُنَافِقًا. قَالَ: وَفِيمَ؟ قَالَ: فِي مُشْطٍ وَمُشَاقَةٍ. قَالَ: وَأَيْنَ؟ قَالَ: فِي جُفِّ طَلْعَةٍ ذَكَرٍ، تَحْتَ رَعُوفَةٍ، فِي بِئْرِ ذَرْوَانَ.","قَالَتْ: فَأَتَى النَّبِيُّ صلى الله عليه وسلم الْبِئْرَ حَتَّى اسْتَخْرَجَهُ فَقَالَ: هَذِهِ الْبِئْرُ الَّتِي أُرِيتُهَا وَكَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ وَكَأَنَّ نَخْلَهَا رؤوس الشَّيَاطِينِ قَالَ: فَاسْتُخْرِجَ قَالَتْ: فَقُلْتُ أَفَلاَ؟ -أَىْ تَنَشَّرْتَ- فَقَالَ: أَمَا وَاللَّهِ فَقَدْ شَفَانِي الله، وَأَكْرَهُ أَنْ أُثِيرَ عَلَى أَحَدٍ مِنَ النَّاسِ شَرًّا."],"takhrij":"صحيح: رواه البخاري في الطب (5765) عن عبد الله بن محمد قال: سمعت ابن عيينة يقول: أول من حدثنا به ابن جريج، يقول: حدثني آل عروة، عن عروة فسألت هشاما عنه، فحدثنا عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5765).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ was bewitched to the extent that he imagined he had relations with his wives when he had not. Sufyān said: “This is among the most severe forms of sorcery.” The Prophet ﷺ said: “O ʿĀ’ishah, do you know that Allah has answered me concerning the matter about which I sought His judgment? Two men came to me. One sat near my head and the other near my feet. The one near my head asked the other, ‘What is wrong with this man?’ He replied, ‘He has been bewitched.’ He asked, ‘Who bewitched him?’ He replied, ‘Labīd ibn al-Aʿṣam, a man from Banū Zurayq, an ally of the Jews, who was a hypocrite.’ He asked, ‘In what was it placed?’ He replied, ‘In a comb and hair caught in the comb.’ He asked, ‘Where is it?’ He replied, ‘In the sheath of a male date-palm blossom beneath a stone at the bottom of the well of Dharwān.’” The Prophet ﷺ went to the well and had it removed. He said: “This is the well that was shown to me. Its water resembles water in which henna has been soaked, and its palm trees resemble the heads of devils.”","ʿĀ’ishah asked: “Why did you not publicly undo and expose it?” He replied: “By Allah, Allah has healed me, and I dislike stirring up evil against anyone among the people.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5765)."},{"num":11513,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَحَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مِنْ بَنِي زُرَيْقٍ يُقَالُ لَهُ لَبِيدُ بْنُ الأَعْصَمِ، حَتَّى كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَفْعَلُ الشَّىْءَ وَمَا فَعَلَهُ، حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ أَوْ ذَاتَ لَيْلَةٍ وَهْوَ عِنْدِي، لَكِنَّهُ دَعَا وَدَعَا ثُمَّ قَالَ: يَا عَائِشَةُ، أَشَعَرْتِ أَنَّ اللَّهَ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ، أَتَانِي رَجُلاَنِ فَقَعَدَ أَحَدُهُمَا عِنْدَ رَأْسِي، وَالآخَرُ عِنْدَ رِجْلَىَّ، فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ: مَا وَجَعُ الرَّجُلِ؟ فَقَالَ: مَطْبُوبٌ. قَالَ: مَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ الأَعْصَمِ. قَالَ: فِي أَىِّ شَىْءٍ؟ قَالَ: فِي مُشْطٍ وَمُشَاطَةٍ، وَجُفِّ طَلْعِ نَخْلَةٍ ذَكَرٍ. قَالَ: وَأَيْنَ هُوَ؟ قَالَ: فِي بِئْرِ ذَرْوَانَ. فَأَتَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَاسٍ مِنْ أَصْحَابِهِ فَجَاءَ فَقَالَ يَا عَائِشَةُ كَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ، أَوْ كَأَنَّ رُءُوسَ نَخْلِهَا رُءُوسُ الشَّيَاطِينِ. قُلْتُ يَا رَسُولَ اللَّهِ أَفَلاَ أَسْتَخْرِجُهُ قَالَ قَدْ عَافَانِي اللَّهُ، فَكَرِهْتُ أَنْ أُثَوِّرَ عَلَى النَّاسِ فِيهِ شَرًّا. فَأَمَرَ بِهَا فَدُفِنَتْ."],"takhrij":"صحيح: رواه البخاري في الطب (5763) عن إبراهيم بن موسى، أخبرنا عيسى بن يونس، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5763).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: A man from Banū Zurayq named Labīd ibn al-Aʿṣam bewitched the Messenger of Allah ﷺ until he imagined that he had done things which he had not actually done. One day—or one night—while he was with me, he supplicated repeatedly. He then said: “O ʿĀ’ishah, do you know that Allah has answered me concerning the matter about which I sought His judgment? Two men came to me. One sat near my head and the other near my feet. One asked the other, ‘What is wrong with this man?’ He replied, ‘He has been bewitched.’ He asked, ‘Who bewitched him?’ He replied, ‘Labīd ibn al-Aʿṣam.’ He asked, ‘In what was it placed?’ He replied, ‘In a comb, hair caught in the comb, and the sheath of a male date-palm blossom.’ He asked, ‘Where is it?’ He replied, ‘In the well of Dharwān.’” The Messenger of Allah ﷺ went there with some of his Companions. When he returned, he said: “O ʿĀ’ishah, its water resembled water in which henna had been soaked, and the tops of its palm trees resembled the heads of devils.” I asked: “O Messenger of Allah, did you not remove it?” He replied: “Allah has granted me recovery, and I disliked stirring up evil among the people because of it.” He then ordered that the well be buried."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5763)."},{"num":11514,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: سُحِرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِنَّهُ لَيُخَيَّلُ إِلَيْهِ أَنَّهُ يَفْعَلُ الشَّىْءَ وَمَا فَعَلَهُ، حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ وَهْوَ عِنْدِي، دَعَا اللَّهَ وَدَعَاهُ، ثُمَّ قَالَ: أَشَعَرْتِ يَا عَائِشَةُ أَنَّ اللَّهَ قَدْ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ. قُلْتُ: وَمَا ذَاكَ يَا رَسُولَ اللَّهِ؟ قَالَ: جَاءَنِي رَجُلاَنِ، فَجَلَسَ أَحَدُهُمَا عِنْدَ رَأْسِي، وَالآخَرُ عِنْدَ رِجْلَىَّ، ثُمَّ قَالَ أَحَدُهُمَا لِصَاحِبِهِ: مَا وَجَعُ الرَّجُلِ؟ قَالَ: مَطْبُوبٌ. قَالَ: وَمَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ الأَعْصَمِ، الْيَهُودِيُّ مِنْ بَنِي زُرَيْقٍ. قَالَ: فِيمَا ذَا؟ قَالَ: فِي مُشْطٍ وَمُشَاطَةٍ، وَجُفِّ طَلْعَةٍ ذَكَرٍ. قَالَ: فَأَيْنَ هُوَ؟ قَالَ: فِي بِئْرِ ذِي أَرْوَانَ.","قَالَ: فَذَهَبَ النَّبِيُّ صلى الله عليه وسلم فِي أُنَاسٍ مِنْ أَصْحَابِهِ إِلَى الْبِئْرِ، فَنَظَرَ إِلَيْهَا وَعَلَيْهَا نَخْلٌ، ثُمَّ رَجَعَ إِلَى عَائِشَةَ فَقَالَ: وَاللَّهِ لَكَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ، وَلَكَأَنَّ نَخْلَهَا رؤوس الشَّيَاطِينِ قُلْتُ: يَا رَسُولَ اللَّهِ أَفَأَخْرَجْتَهُ؟ قَالَ: لاَ، أَمَّا أَنَا فَقَدْ عَافَانِي اللَّهُ وَشَفَانِي، وَخَشِيتُ أَنْ أُثَوِّرَ عَلَى النَّاسِ مِنْهُ شَرًّا وَأَمَرَ بِهَا فَدُفِنَتْ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5766) عن عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5766) and Muslim (2189).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Prophet ﷺ was bewitched to the extent that he imagined he had done something when he had not done it. One day, while he was with me, he repeatedly supplicated to Allah. He then said: “O ʿĀ’ishah, do you know that Allah has answered me concerning the matter about which I sought His judgment?” I asked: “What is that, O Messenger of Allah?” He replied: “Two men came to me. One sat near my head and the other near my feet. One asked his companion, ‘What is wrong with this man?’ He replied, ‘He has been bewitched.’ He asked, ‘Who bewitched him?’ He replied, ‘Labīd ibn al-Aʿṣam, the Jew from Banū Zurayq.’ He asked, ‘In what was it placed?’ He replied, ‘In a comb, hair caught in the comb, and the sheath of a male date-palm blossom.’ He asked, ‘Where is it?’ He replied, ‘In the well of Dhū Arwān.’” The Prophet ﷺ went to the well with some of his Companions. He examined it, and there were palm trees around it. He then returned to ʿĀ’ishah and said: “By Allah, its water resembled water in which henna had been soaked, and its palm trees resembled the heads of devils.”","I asked: “O Messenger of Allah, did you remove it?” He replied: “No. Allah has granted me well-being and healed me, and I feared that I might stir up evil among the people because of it.” He ordered that it be buried."]},"buhuth":{"en":["Regarding the description “Labīd ibn al-Aʿṣam, the Jew from Banū Zurayq,” the correct wording, as found in Sufyān’s narration and others, is that Labīd ibn al-Aʿṣam was a man from Banū Zurayq and an ally of the Jews. Banū Zurayq were a well-known branch of al-Khazraj. He was therefore called “the Jew” because of his alliance with them, not because he followed the Jewish religion."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5766)، ومسلم (2189)."},{"num":11515,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  سَحَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَهُودِيٌّ مِنْ يَهُودِ بَنِي زُرَيْقٍ يُقَالُ لَهُ: لَبِيدُ بْنُ الْأَعْصَمِ، قَالَتْ: حَتَّى كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَفْعَلُ الشَّيْءَ وَمَا يَفْعَلُهُ، حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ أَوْ ذَاتَ لَيْلَةٍ دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ دَعَا، ثُمَّ دَعَا، ثُمَّ قَالَ: يَا عَائِشَةُ، أَشَعَرْتِ أَنَّ اللَّهَ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ؟ جَاءَنِي رَجُلَانِ فَقَعَدَ أَحَدُهُمَا عِنْدَ رَأْسِي، وَالْآخَرُ عِنْدَ رِجْلَيَّ، فَقَالَ الَّذِي عِنْدَ رَأْسِي لِلَّذِي عِنْدَ رِجْلَيَّ - أَوِ الَّذِي عِنْدَ رِجْلَيَّ لِلَّذِي عِنْدَ رَأْسِي: مَا وَجَعُ الرَّجُلِ؟ قَالَ: مَطْبُوبٌ، قَالَ: مَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ الْأَعْصَمِ، قَالَ: فِي أَيِّ شَيْءٍ؟ قَالَ: فِي مُشْطٍ وَمُشَاطَةٍ، قَالَ: وَجُفِّ طَلْعَةٍ ذَكَرٍ، قَالَ: فَأَيْنَ هُوَ؟ قَالَ: فِي بِئْرِ ذِي أَرْوَانَ.","قَالَتْ: فَأَتَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم فِي أُنَاسٍ مِنْ أَصْحَابِهِ ثُمَّ قَالَ: يَا عَائِشَةُ وَاللَّهِ لَكَأَنَّ ماءها نقاعة الحناء، ولكأن نخلها رؤوس الشياطين.قالت: فَقُلْتُ: يَا رَسُولَ اللَّهِ أَفَلَا أَحْرَقْتَهُ؟ قَالَ: لَا أَمَّا أَنَا فَقَدْ عَافَانِي اللَّهُ، وَكَرِهْتُ أَنْ أُثِيرَ عَلَى النَّاسِ شَرًّا فأمرت بها فدفنت."],"takhrij":"صحيح: رواه مسلم في السلام (2189: 43) عن أبي كريب، حدثنا ابن نمير، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2189/43).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: A Jew from among the Jews of Banū Zurayq, named Labīd ibn al-Aʿṣam, bewitched the Messenger of Allah ﷺ. The Messenger of Allah ﷺ then imagined that he had done things which he had not done. One day—or one night—the Messenger of Allah ﷺ supplicated, then supplicated again, and then supplicated a third time. He said: “O ʿĀ’ishah, do you know that Allah has answered me concerning the matter about which I sought His judgment? Two men came to me. One sat near my head and the other near my feet. The one near my head asked the one near my feet—or the one near my feet asked the one near my head—‘What is wrong with this man?’ He replied, ‘He has been bewitched.’ He asked, ‘Who bewitched him?’ He replied, ‘Labīd ibn al-Aʿṣam.’ He asked, ‘In what was it placed?’ He replied, ‘In a comb, hair caught in the comb, and the sheath of a male date-palm blossom.’ He asked, ‘Where is it?’ He replied, ‘In the well of Dhū Arwān.’” The Messenger of Allah ﷺ went to the well with some of his Companions. He then said: “O ʿĀ’ishah, by Allah, its water resembled water in which henna had been soaked, and its palm trees resembled the heads of devils.”","I asked: “O Messenger of Allah, why did you not burn it?” He replied: “No. Allah has granted me well-being, and I disliked stirring up evil among the people.” He ordered that it be buried."]},"buhuth":{"en":["The well of Dhū Arwān, also called Dharwān, was located in an orchard belonging to Banū Zurayq in Madinah.","The word maṭbūb means bewitched. The expression ṭubba al-rajul means that a man was subjected to sorcery.","The word juff, and in another narration jubb, refers to the casing or sheath surrounding the date-palm blossom. It may refer to either a male or female blossom, which is why the hadith specifies a male blossom. The expression naqāʿat al-ḥinnāʾ means water in which henna has been soaked."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2189: 43)."},{"num":11516,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ قَالَ: سَحَرَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مِنَ الْيَهُودِ فَاشْتَكَى لِذَلِكَ أَيَّامًا فَأَتَاهُ جِبْرِيلُ عَلَيْهِ السلام فَقَالَ: إِنَّ رَجُلًا مِنَ الْيَهُودِ سَحَرَكَ، عَقَدَ لَكَ عُقَدًا فِي بِئْرِ كَذَا وَكَذَا، فَأَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فاستخرجوها فَجِيءَ بِهَا، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَأَنَّمَا نُشِطَ مِنْ عِقَالٍ فَمَا ذَكَرَ ذَلِكَ لِذَلِكَ الْيَهُودِيِّ، وَلَا رَآهُ فِي وَجْهِهِ قَطُّ."],"takhrij":"صحيح: رواه النسائي (4080)، وأحمد (19267) كلاهما من حديث أبي معاوية، حدثنا الأعمش، عن يزيد بن حيان، عن زيد بن أرقم فذكره.","grade":"صحيح","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (4080) and Aḥmad (19267).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Zayd ibn Arqam narrated: A man associated with the Jews bewitched the Prophet ﷺ, causing him to suffer for several days. Gabriel, peace be upon him, came to him and said: “A man associated with the Jews has bewitched you. He tied knots for you and placed them in such-and-such a well.” The Messenger of Allah ﷺ sent people to retrieve them. They were brought to him, and the Messenger of Allah ﷺ stood as though he had been released from bonds. He never mentioned the matter to that man, nor did he ever display any sign of anger toward him."]},"buhuth":{"en":["The words “a man associated with the Jews” mean one of their allies, as explicitly stated in Ṣaḥīḥ al-Bukhārī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4080)، وأحمد (19267)."},{"num":11517,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا هُنَّ قَالَ: الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2766)، ومسلم في الإيمان (89) كلاهما من حديث سليمان بن بلال، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2766) and Muslim (89).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Avoid the seven destructive sins.” They asked: “O Messenger of Allah, what are they?” He replied: “Associating partners with Allah, sorcery, unlawfully taking a life which Allah has made sacred, consuming usury, consuming the wealth of an orphan, fleeing on the day when the armies meet, and falsely accusing chaste, believing, unsuspecting women of unlawful sexual intercourse.”"]}},"tuhfa":{},"full":1,"rep":[230,5690,6809,7001,7897,12142,12362,12859],"tks":"متفق عليه: رواه البخاري (2766)، ومسلم (89)."},{"num":11518,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا اقْتَبَسَ رَجُلٌ عِلْمًا مِنَ النُّجُومِ، إِلا اقْتَبَسَ بِهَا شُعْبَةً مِنَ السِّحْرِ، مَا زَادَ زَادَ."],"takhrij":"صحيح: رواه أبو داود (3905)، وابن ماجه (3726)، وأحمد (2000) كلهم من حديث يحيى بن سعيد، عن عبيد الله بن الأخنس، عن الوليد بن عبد الله، عن يوسف بن ماهك، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب إن للسحر حقيقة","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3905), Ibn Mājah (3726), and Aḥmad (2000).","chapter_en":"Sorcery Has a Real Existence","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “Whoever acquires a branch of astrology has acquired a branch of sorcery. The more he increases in astrology, the more he increases in sorcery.”"]},"buhuth":{"en":["These hadiths stating that the Prophet ﷺ was affected by sorcery do not contradict the Qur’anic verses:","“When the wrongdoers say, ‘You are only following a man who has been bewitched.’”","[Sūrat al-Isrāʾ 17:47]","And:","“The wrongdoers say, ‘You are only following a man who has been bewitched.’”","[Sūrat al-Furqān 25:8]","Allah, the Exalted, protected the Prophet ﷺ in receiving and conveying revelation. Quraysh accused him of being a sorcerer, bewitched, insane, a liar, and a poet. All of these accusations were false. Allah therefore refuted them by saying:","“See how they strike comparisons for you, but they have gone astray and cannot find a way.”","[Sūrat al-Furqān 25:9]","As for the sorcery that affected the Prophet ﷺ, its effects were limited to worldly and personal matters. For example, he imagined that he had eaten when he had not eaten, or that he had approached his wife when he had not done so. This occurred within the limits of his human nature and did not affect the reception or transmission of revelation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3905)، وابن ماجه (3726)، وأحمد (2000)."},{"num":11519,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النُّشْرَةِ فَقَالَ: هُوَ مِنْ عَمَلِ الشَّيْطَانِ."],"takhrij":"حسن: رواه أبو داود (3868) عن أحمد بن حنبل –وهو في مسنده (14135)- قال: حدثنا عبد الرزاق، أخبرنا عقيل بن معقل، سمعت وهب بن منبه، يحدث عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب التحذير من فك السحر بالنشرة الجاهلية","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3868) and Aḥmad ibn Ḥanbal (14135).","chapter_en":"Warning against Undoing Sorcery through the Pre-Islamic Nushrah","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Prophet ﷺ was asked about al-nushrah, and he replied: “It is among the works of Satan.”"]},"buhuth":{"en":["Al-Nushrah was a form of pre-Islamic ruqyah containing polytheistic words. It was used to treat a person afflicted by sorcery. The Messenger of Allah ﷺ was asked about this pre-Islamic form of treatment and said:","“It is among the works of Satan.”","Islam replaced this polytheistic ruqyah with lawful ruqyah consisting of the remembrance of Allah, His names and attributes, turning to Him, and seeking refuge in Him on different occasions. There is no disagreement concerning the permissibility of this.","As for undoing sorcery through sorcery, employing jinn or devils, or going to soothsayers and charlatans, all of these are forbidden.","Al-Ḥāfiẓ Ibn al-Qayyim said:","“Undoing sorcery by means of similar sorcery is among the works of Satan.”","There are several lawful ways of undoing sorcery from an afflicted person.","Among them is supplicating to Allah, Glorified and Exalted, to reveal the location of the sorcery, which the person may then see in a dream.","Another method is to recite ruqyah over the afflicted person, whereupon the jinn may speak through the patient and disclose the location where the sorcery was placed.","His Eminence Shaykh Ibn Bāz, may Allah have mercy upon him, mentioned several ways of discovering the location of sorcery. He said:","“As for treating sorcery after it has occurred, one of its most beneficial treatments is to exert every effort to discover where the sorcery was placed, whether in the earth, a mountain, or elsewhere. Once it is found, removed, and destroyed, the sorcery is nullified, as stated in the hadith of ʿĀ’ishah.","Another treatment is to repel it through Qur’anic verses, remembrances, and supplications. These are among the greatest weapons for removing sorcery after it has taken effect, together with frequently humbling oneself before Allah and asking Him, Glorified and Exalted, to remove the harm and affliction.","Another treatment for sorcery after it has occurred—which is beneficial for a man who has been prevented from having relations with his wife—is to take seven green leaves from the lote tree, crush them with a stone or something similar, place them in a vessel, and pour over them enough water for bathing.","The following should then be recited over the water: Āyat al-Kursī; ‘Say: O disbelievers’; ‘Say: He is Allah, the One’; ‘Say: I seek refuge in the Lord of daybreak’; and ‘Say: I seek refuge in the Lord of mankind.’”","The verses concerning sorcery in Sūrat al-Aʿrāf should also be recited. Allah, Glorified, said:","“We inspired Moses, ‘Throw down your staff,’ and suddenly it swallowed what they had falsely produced. Thus the truth prevailed, and what they had been doing was nullified. They were defeated then and there and returned utterly humiliated.”","[Sūrat al-Aʿrāf 7:117–119]","The verses in Sūrat Yūnus should also be recited. Allah, Glorified, said:","“Pharaoh said, ‘Bring me every skilled sorcerer.’ When the sorcerers came, Moses said to them, ‘Throw whatever you intend to throw.’ When they threw, Moses said, ‘What you have produced is sorcery. Allah will certainly nullify it. Indeed, Allah does not set right the work of the corrupters. Allah establishes the truth by His words, even though the criminals dislike it.’”","[Sūrat Yūnus 10:79–82]","The verses in Sūrat Ṭā Hā should also be recited:","“They said, ‘O Moses, either you throw or we will be the first to throw.’ He said, ‘Rather, you throw.’ Suddenly, through their sorcery, their ropes and staffs appeared to him as though they were moving rapidly. Moses sensed fear within himself. We said, ‘Do not be afraid. You will certainly prevail. Throw what is in your right hand; it will swallow what they have produced. What they have produced is only the trick of a sorcerer, and the sorcerer will never succeed wherever he goes.’”","[Sūrat Ṭā Hā 20:65–69]","After reciting the preceding passages over the water, the afflicted person should drink three mouthfuls from it and bathe with the remainder. Through this, the illness will disappear, Allah willing.","Should it be necessary to use this treatment twice or more, there is no harm in doing so until the illness disappears.","As for treating sorcery through the practices of sorcerers, which involve seeking nearness to the jinn by slaughtering or offering other acts of devotion to them, this is impermissible. It is among the works of Satan and is, in fact, major polytheism. It is therefore obligatory to avoid it.","It is likewise impermissible to seek treatment by questioning soothsayers, fortune-tellers, or charlatans, or by acting upon what they say. They have no true faith and are wicked liars who claim knowledge of the unseen and deceive people. The Messenger ﷺ warned against going to them, questioning them, and believing them.","Ways of Protecting Oneself from Sorcery","The first means of protection is to recite Āyat al-Kursī after each obligatory prayer, following the prescribed remembrances after the salutation, and also before sleeping.","Āyat al-Kursī is the greatest verse in the Noble Qur’an. Allah, Glorified, said:","“Allah—there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who could intercede with Him except by His permission? He knows what is before them and what is behind them, and they encompass nothing of His knowledge except what He wills. His Footstool extends over the heavens and the earth, and preserving them does not tire Him. He is the Most High, the Magnificent.”","[Sūrat al-Baqarah 2:255]","Another means of protection is to recite:","“Say: He is Allah, the One.”","[Sūrat al-Ikhlāṣ 112:1]","“Say: I seek refuge in the Lord of daybreak.”","[Sūrat al-Falaq 113:1]","“Say: I seek refuge in the Lord of mankind.”","[Sūrat al-Nās 114:1]","These should be recited after every obligatory prayer. The three chapters should also be recited three times at the beginning of the day after the dawn prayer, at the beginning of the night after the sunset prayer, and before sleeping.","Another means of protection is to recite the final two verses of Sūrat al-Baqarah at the beginning of the night:","“The Messenger believes in what was revealed to him from his Lord, as do the believers. All believe in Allah, His angels, His Books, and His messengers. They say, ‘We make no distinction between any of His messengers.’ They say, ‘We hear and obey. We seek Your forgiveness, our Lord, and to You is the final return.’","Allah does not burden any soul beyond its capacity. It will receive the good it has earned and bear the evil it has committed. ‘Our Lord, do not punish us if we forget or make a mistake. Our Lord, do not place upon us a burden like that which You placed upon those before us. Our Lord, do not burden us with what we cannot bear. Pardon us, forgive us, and have mercy upon us. You are our Guardian, so grant us victory over the disbelieving people.’”","[Sūrat al-Baqarah 2:285–286]","It is authentically reported that the Messenger of Allah ﷺ said:","“Whoever recites Āyat al-Kursī during the night will continue to have a guardian from Allah, and no devil will approach him until morning.”","It is also authentically reported that he ﷺ said:","“Whoever recites the final two verses of Sūrat al-Baqarah during the night, they will suffice him.”","The meaning—and Allah knows best—is that they will suffice him against every evil.","Another means of protection is to frequently seek refuge in Allah’s perfect words from the evil of what He created, during the night and day and whenever one stops at any place, whether in a building, the desert, the air, or the sea.","The Prophet ﷺ said:","“Whoever stops at a place and says, ‘I seek refuge in the perfect words of Allah from the evil of what He created,’ nothing will harm him until he leaves that place.”","Another means of protection is for the Muslim to say three times at the beginning of the day and the beginning of the night:","“In the name of Allah, with whose name nothing on earth or in heaven can cause harm. He is the All-Hearing, the All-Knowing.”","The encouragement to recite this is authentically reported from the Messenger of Allah ﷺ, and it is a means of protection from every evil.","These remembrances and formulas of seeking refuge are among the greatest means of protection from sorcery and other evils for the person who observes them with sincerity, faith, trust in Allah, reliance upon Him, and an open heart toward what they signify.","See: The Ruling on Sorcery and Soothsaying by the eminent scholar ʿAbd al-ʿAzīz ibn Bāz."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3868)، وأحمد بن حنبل (14135)."},{"num":11520,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ:  قُلْتُ: يَا رَسُولَ اللَّهِ، أُمُورًا كُنَّا نَصْنَعُهَا فِي الْجَاهِلِيَّةِ؛ كُنَّا نَأْتِي الْكُهَّانَ! قَالَ: فَلَا تَأْتُوا الْكُهَّانَ. قَالَ: قُلْتُ: كُنَّا نَتَطَيَّرُ! قَالَ: ذَاكَ شَيْءٌ يَجِدُهُ أَحَدُكُمْ فِي نَفْسِهِ، فَلَا يَصُدَّنَّكُمْ."],"takhrij":"صحيح: رواه مسلم في السلام (537: 121) من طرق عن ابن وهب، أخبرني يونس، عن ابن شهاب، عن أبي سلمة بن عبد الرحمن بن عوف، عن معاوية بن الحكم السلمي قال: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (537/121).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Muʿāwiyah ibn al-Ḥakam al-Sulamī narrated: I said: “O Messenger of Allah, there were things we used to do during the time of ignorance. We used to go to soothsayers.” He replied: “Do not go to soothsayers.” I said: “We used to take evil omens.” He replied: “That is something one of you may feel within himself, but it must not prevent you from proceeding.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (537: 121)."},{"num":11521,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ الْكُهَّانَ كَانُوا يُحَدِّثُونَنَا بِالشَّيْءِ، فَنَجِدُهُ حَقًّا! قَالَ: تِلْكَ الْكَلِمَةُ الْحَقُّ يَخْطَفُهَا الْجِنِّيُّ، فَيَقْذِفُهَا فِي أُذُنِ وَلِيِّهِ، وَيَزِيدُ فِيهَا مِائَةَ كَذْبَةٍ."],"takhrij":"متفق عليه: رواه مسلم في السلام (2228) عن عبد بن حميد أخبرنا عبدالرزاق أخبرنا معمر عن الزهري عن يحيى بن عروة بن الزبير عن أبيه عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2228) and al-Bukhārī (5762).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿĀ’ishah narrated: I said: “O Messenger of Allah, the soothsayers sometimes tell us something, and we find it to be true.” He replied: “That is a word of truth which a jinn snatches and casts into the ear of his ally, but he mixes with it one hundred lies.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2228)، والبخاري (5762)."},{"num":11522,"demo":false,"sanad":"","matn":["عَنْ صَفِيَّةَ، عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَنْ أَتَى عَرَّافًا فَسَأَلَهُ عَنْ شَيْءٍ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً."],"takhrij":"صحيح: رواه مسلم في السلام (2230) عن محمد عن المثنى العنزي، حدثنا يحيى (يعني ابن سعيد)، عن عبيدالله، عن نافع، عن صفية فذكرته.","grade":"صحيح","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2230).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ṣafiyyah narrated from one of the wives of the Prophet ﷺ that the Prophet ﷺ said: “Whoever goes to a fortune-teller and asks him about anything will have no prayer accepted from him for forty nights.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2230)."},{"num":11523,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَتَى عَرَّافًا أَوْ كَاهِنًا فَصَدَّقَهُ فِيمَا يَقُولُ، فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه الحاكم (15) –وعنه البيهقي (16496)- من طريقين عن عوف بن أبي جميلة، عن خلاس ومحمد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ḥākim (15), and through his route by al-Bayhaqī (8/135).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever goes to a fortune-teller or soothsayer and believes what he says has disbelieved in what was revealed to Muḥammad ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (15)، ومن طريقه البيهقي (16496)."},{"num":11524,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَتَى كَاهِنًا فَصَدَّقَهُ بِمَا يَقُولُ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه البزار – كشف الأستار (3045) عن عقبة بن سنان، حدثنا غسان بن مضر، حدثنا سعيد بن يزيد (هو ابن مسلمة الأزدي)، عن أبي نضرة، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (3045).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Prophet ﷺ said: “Whoever goes to a soothsayer and believes what he says has disbelieved in what was revealed to Muḥammad ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3045)."},{"num":11525,"demo":false,"sanad":"","matn":["عَبْدَ اللَّهِ بْنَ عَبَّاسٍ قَالَ:  أَخْبَرَنِي رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَنْصَارِ أَنَّهُمْ بَيْنَمَا هُمْ جُلُوسٌ لَيْلَةً مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رُمِيَ بِنَجْمٍ فَاسْتَنَارَ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَاذَا كُنْتُمْ تَقُولُونَ فِي الْجَاهِلِيَّةِ إِذَا رُمِيَ بِمِثْلِ هَذَا؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، كُنَّا نَقُولُ: وُلِدَ اللَّيْلَةَ رَجُلٌ عَظِيمٌ، وَمَاتَ رَجُلٌ عَظِيمٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنَّهَا لَا يُرْمَى بِهَا لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، وَلَكِنْ رَبُّنَا تَبَارَكَ وَتَعَالَى اسْمُهُ إِذَا قَضَى أَمْرًا سَبَّحَ حَمَلَةُ الْعَرْشِ، ثُمَّ سَبَّحَ أَهْلُ السَّمَاءِ الَّذِينَ يَلُونَهُمْ، حَتَّى يَبْلُغَ التَّسْبِيحُ أَهْلَ هَذِهِ السَّمَاءِ الدُّنْيَا، ثُمَّ قَالَ الَّذِينَ يَلُونَ حَمَلَةَ الْعَرْشِ لِحَمَلَةِ الْعَرْشِ: مَاذَا قَالَ رَبُّكُمْ؟ فَيُخْبِرُونَهُمْ مَاذَا قَالَ. قَالَ: فَيَسْتَخْبِرُ بَعْضُ أَهْلِ السَّمَاوَاتِ بَعْضًا حَتَّى يَبْلُغَ الْخَبَرُ هَذِهِ السَّمَاءَ الدُّنْيَا، فَتَخْطَفُ الْجِنُّ السَّمْعَ، فَيَقْذِفُونَ إِلَى أَوْلِيَائِهِمْ، وَيُرْمَوْنَ بِهِ، فَمَا جَاءُوا بِهِ عَلَى وَجْهِهِ فَهُوَ حَقٌّ، وَلَكِنَّهُمْ يَقْرِفُونَ فِيهِ وَيَزِيدُونَ."],"takhrij":"صحيح: رواه مسلم في السلام 2229) من طرق عن يعقوب بن إبراهيم بن سعد، حدثنا أبي، عن صالح، عن ابن شهاب، حدثني علي بن حسين، عن عبدالله بن عباس قال:فذكره.","grade":"صحيح","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2229).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: A man from among the Anṣār who was one of the Companions of the Prophet ﷺ informed me that, while they were sitting with the Messenger of Allah ﷺ one night, a shooting star was cast and illuminated the sky. The Messenger of Allah ﷺ asked them: “What did you used to say during the time of ignorance when something like this was cast?” They replied: “Allah and His Messenger know best. We used to say, ‘A great man was born tonight,’ or, ‘A great man died tonight.’” The Messenger of Allah ﷺ said: “They are not cast because of anyone’s death or birth. Rather, when our Lord—Blessed and Exalted is His name—decrees a matter, the bearers of the Throne glorify Him. Then the inhabitants of the heaven nearest to them glorify Him, until the glorification reaches the inhabitants of this lowest heaven. Those nearest to the bearers of the Throne then ask them, ‘What did your Lord say?’ They inform them of what He said. The inhabitants of each heaven then ask one another until the news reaches the lowest heaven. The jinn then snatch what they hear and convey it to their allies, while shooting stars are cast at them. Whatever they convey exactly as they heard it is true, but they mix falsehood with it and add to it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13116],"tks":"صحيح: رواه مسلم (2229)."},{"num":11526,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَنْ يَلِجَ الدَّرَجَاتِ الْعُلَى مَنْ تَكَهَّنَ، أَوْ اسْتَقْسَمَ، أَوْ رَدَّهُ مِنْ سَفَرٍ تَطَيُّرٌ."],"takhrij":"حسن: رواه الطبراني في مسند الشاميين (2104) عن محمد بن عبدالله الحضرمي، ثنا يحيى بن داود الواسطي، حدثنا إبراهيم بن يزيد بن مرادنبه، عن رقبة بن مصقلة، عن عبدالملك بن عمير، عن رجاء بن حيوة، عن أم الدرداء، عن أبي الدرداء قال: فذكره.","grade":"حسن","chapter_ar":"باب تحريم إتيان الكهان","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in Musnad al-Shāmiyyīn (2104).","chapter_en":"The Prohibition of Going to Soothsayers","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū al-Dardāʾ narrated that the Messenger of Allah ﷺ said: “The one who practices soothsaying, seeks decisions through divining arrows, or allows an evil omen to turn him back from a journey will not enter the highest ranks.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في مسند الشاميين (2104)."},{"num":11527,"demo":false,"sanad":"","matn":["عن معاوية بن الحكم السلمي قال: قلت: يا رسول الله أموراً كنا نصنعها في الجاهلية فذكر منها: ومنا رجال يخطون قال: كان نبي من الأنبياء يخط فمن وافق خطه فذاك."],"takhrij":"صحيح: رواه مسلم في السلام (537:...) من طرق عن يحيى بن أبي كثير، عن هلال بن أبي ميمونة، عن عطاء بن يسار، عن معاوية بن الحكم السلمي فذكره.","grade":"صحيح","chapter_ar":"باب الخط في الرمل","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (537).","chapter_en":"Drawing Lines in the Sand","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Muʿāwiyah ibn al-Ḥakam al-Sulamī narrated: I said: “O Messenger of Allah, there were practices we used to follow during the time of ignorance.” Among the practices he mentioned was: “Some men among us used to draw lines in the sand.” The Prophet ﷺ said: “One of the prophets used to draw lines. Whoever’s drawing agrees with his drawing has attained the correct result.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (537)."},{"num":11528,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ نَبِيٌّ مِنَ الْأَنْبِيَاءِ يَخُطُّ، فَمَنْ وَافَقَ عِلْمَهُ، فَهُوَ عِلْمُهُ."],"takhrij":"صحيح: رواه أحمد (9117) عن أبي أحمد (وهو الزبيري)، حدثنا سفيان (وهو الثوري)، عن عبد الله بن أبي لبيد (وهو أبو المغيرة المدني)، عن أبي سلمة، عن أبي هريرة فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الخط في الرمل","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (9117).","chapter_en":"Drawing Lines in the Sand","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “One of the prophets used to draw lines. Whoever’s knowledge agrees with his knowledge has reached the correct result.”"]},"buhuth":{"en":["The statement “One of Allah’s prophets used to draw lines” refers to something based upon revelation and inspiration from Allah, the Exalted. This is not available to anyone other than prophets.","The Prophet ﷺ said:","“Whoever’s line agrees with his line has attained the correct result.”","This made agreement with that prophet’s line a condition for permissibility. Since this condition cannot now be verified, no one is permitted to practice it.","Al-Nawawī said:","“The Prophet ﷺ preserved the sanctity of that prophet while clarifying the ruling that applies to us. The meaning is that the practice was not prohibited for that prophet, and it would likewise not be prohibited if you knew that your drawing agreed with his. However, you possess no such knowledge.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (9117)."},{"num":11529,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: إِنَّ الرُّقَى، وَالتَّمَائِمَ، وَالتِّوَلَةَ شِرْكٌ.","قالت (أي زينب امرأة عبد الله): قلت: لِمَ تقول هذا؟ والله لقد كانت عيني تقذف وكنت أختلف إلى فلان اليهودي يرقيني، فإذا رقاني سكنت، فقال عبد الله: إنما ذاك عمل الشيطان كان ينخسها بيده، فإذا رقاها كف عنها، إنما كان يكفيك أن تقولي كما كان رسول الله صلى الله عليه وسلم يقول: أذهب البأس رب الناس، اشف أنت الشافي، لا شفاء إلا شفاؤك شفاء لا يغادر سقما."],"takhrij":"حسن: رواه ابو داود (3883) –واللفظ له-، وابن ماجه (3530)، وأحمد (3615) كلهم من طريق الأعمش، عن عمرو بن مرة، عن يحيى بن الجزار، عن ابن أخي زينب امرأة عبد الله بن مسعود، عن عبد الله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تعليق التمائم","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3883), whose wording is cited here, Ibn Mājah (3530), and Aḥmad (3615).","chapter_en":"Warning against Hanging Amulets","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: I heard the Messenger of Allah ﷺ say: “Indeed, unlawful ruqyah, amulets, and love-charms are polytheism.” Zaynab, the wife of ʿAbdullāh, said: I asked: “Why do you say this? By Allah, my eye used to discharge, and I would repeatedly visit a certain Jewish man who performed ruqyah for me. Whenever he performed ruqyah, the condition subsided.” ʿAbdullāh replied: “That was only the work of Satan. He would prick it with his hand, and when the man performed ruqyah, he would stop. It would have been sufficient for you to say what the Messenger of Allah ﷺ used to say: ‘Remove the affliction, Lord of mankind. Heal, for You are the Healer. There is no healing except Your healing—a healing that leaves no illness behind.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3883) واللفظ له، وابن ماجه (3530)، وأحمد (3615)."},{"num":11530,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْبَلَ إِلَيْهِ رَهْطٌ، فَبَايَعَ تِسْعَةً وَأَمْسَكَ عَنْ وَاحِدٍ، فَقَالُوا: يَا رَسُولَ اللَّهِ، بَايَعْتَ تِسْعَةً وَتَرَكْتَ هَذَا؟ قَالَ: إِنَّ عَلَيْهِ تَمِيمَةً فَأَدْخَلَ يَدَهُ فَقَطَعَهَا، فَبَايَعَهُ، وَقَالَ: مَنْ عَلَّقَ تَمِيمَةً فَقَدْ أَشْرَكَ."],"takhrij":"حسن: رواه أحمد (17422)، والطبراني في الكبير (17/319-320)، وصحّحه الحاكم (4/219) كلهم من حديث يزيد بن أبي منصور، عن دخين الحجري، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تعليق التمائم","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17422), al-Ṭabarānī in al-Muʿjam al-Kabīr (17/319–320), and authenticated by al-Ḥākim (4/219).","chapter_en":"Warning against Hanging Amulets","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī narrated: A group came to the Messenger of Allah ﷺ. He accepted the pledge of allegiance from nine of them but withheld it from one. They asked: “O Messenger of Allah, you accepted the pledge from nine and left this man?” He replied: “He is wearing an amulet.” The man inserted his hand and cut it off. The Prophet ﷺ then accepted his pledge and said: “Whoever hangs an amulet has committed polytheism.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17422)، والطبراني في الكبير (17/319-320)، وصححه الحاكم (4/219)."},{"num":11531,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ تَعَلَّقَ تَمِيمَةً، فَلَا أَتَمَّ اللهُ لَهُ، وَمَنْ تَعَلَّقَ وَدَعَةً، فَلَا وَدَعَ اللهُ لَهُ."],"takhrij":"حسن: رواه أحمد (17404)، وأبو يعلى (1759)، والطبراني في الكبير (17/297)، وصحّحه ابن حبان (6086)، والحاكم (7501) كلهم من حديث حيوة بن شريح، أخبرنا خالد بن عبد الله المعافري قال: سمعت مشرح بن عاهان يقول: سمعت عقبة بن عامر يقول: فذكره.","grade":"حسن","chapter_ar":"باب التحذير من تعليق التمائم","chapter_ur":"","part_ar":"كتاب الرقية","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17404), Abū Yaʿlā (1759), and al-Ṭabarānī in al-Muʿjam al-Kabīr (17/297), and authenticated by Ibn Ḥibbān (6086).","chapter_en":"Warning against Hanging Amulets","part_en":"Ruqyah","group_ar":"","group_en":"","part_no":56,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: I heard the Messenger of Allah ﷺ say: “Whoever hangs an amulet, may Allah never complete his affairs for him. Whoever hangs a seashell, may Allah never grant him peace and security.”"]},"buhuth":{"en":["The word wadaʿah is the singular of wadaʿ. It refers to white shells taken from the sea, shaped with a split resembling the opening of a date stone. People used to hang them as protection against the evil eye."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17404)، وأبو يعلى (1759)، والطبراني في الكبير (17/297)، وصححه ابن حبان (6086)."},{"num":11532,"demo":false,"sanad":"","matn":["عَنْ أَبِي رِمْثَةَ قَالَ: قَالَ أَبِي لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرِنِي هَذَا الَّذِي بِظَهْرِكَ، فَإِنِّي رَجُلٌ طَبِيبٌ قَالَ: اللَّهُ عزوجل الطَّبِيبُ، بَلْ أَنْتَ رَجُلٌ رَفِيقٌ، طَبِيبُهَا الَّذِي خَلَقَهَا."],"takhrij":"صحيح: رواه أبو داود (4207)، وعبد الله بن أحمد في زوائد المسند (7110)، وأبو نعيم في الطب النبوي (41-42) كلهم من حديث ابن أبجر، عن إياد بن لقيط، عن أبي رمثة فذكره.واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب أن الشافي هو اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4207), ʿAbdullāh ibn Aḥmad in Zawāʾid al-Musnad (7110), and Abū Nuʿaym in al-Ṭibb al-Nabawī (41–42).","chapter_en":"Allah the Exalted Is the One Who Heals","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Rimthah narrated: My father said to the Prophet ﷺ: “Show me this mark upon your back, for I am a physician.” He replied: “Allah, Mighty and Majestic, is the true Physician. Rather, you are a gentle practitioner. Its true Physician is the One who created it.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَإِنْ يَمْسَسْكَ اللّٰهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ، وَإِنْ يُرِدْكَ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ، يُصِيبُ بِهِ مَنْ يَشَاءُ مِنْ عِبَادِهِ، وَهُوَ الْغَفُورُ الرَّحِيمُ﴾ [يونس: ١٠٧].","وقال اللّٰه تعالى حاكيًا عن إبراهيم: ﴿وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ﴾ [الشعراء: ٨٠]."],"en":["Allah, the Exalted, said:","“If Allah touches you with harm, none can remove it except Him. If He intends good for you, none can repel His bounty. He grants it to whomever He wills among His servants. He is the Most Forgiving, the Most Merciful.”","[Sūrat Yūnus 10:107]","Allah, the Exalted, also related the words of Abraham:","“When I become ill, He is the One who heals me.”","[Sūrat al-Shuʿarāʾ 26:80]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4207)، وعبد الله بن أحمد في زوائد المسند (7110)، وأبو نعيم في الطب النبوي (41-42)."},{"num":11533,"demo":false,"sanad":"","matn":["عَنْ ابْنِ أَبِي مُلَيْكَةَ، قَالَتْ: عَائِشَةُ: مَرِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَوَضَعْتُ يَدِي عَلَى صَدْرِهِ، فَقُلْتُ: أَذْهِبِ الْبَأَسَ رَبَّ النَّاسِ، أَنْتَ الطَّبِيبُ، وَأَنْتَ الشَّافِي، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: أَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى."],"takhrij":"صحيح: رواه أحمد (24774)، والنسائي في عمل اليوم والليلة (1015)، والبيهقي في الأسماء والصفات (151) كلهم من حديث نافع بن عمر الجمحي، عن ابن أبي مليكة، عن عائشة فذكرته.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أن الشافي هو اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (24774), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (1015), and al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (151).","chapter_en":"Allah the Exalted Is the One Who Heals","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah narrated: When the Messenger of Allah ﷺ became ill, I placed my hand upon his chest and said: “Remove the affliction, Lord of mankind. You are the Physician, and You are the Healer.” The Messenger of Allah ﷺ was saying: “Join me with the Highest Companion. Join me with the Highest Companion.”"]},"buhuth":{"en":["The words “Its Physician is the One who created it” and ʿĀ’ishah’s statement “You are the Physician” refer to the true Physician who fully knows the reality of the illness and its cure and alone possesses the power to grant health and healing. This is exclusive to Allah.","There is, however, no harm in calling a human being a physician because he treats the sick, whether the patient recovers through his treatment or does not recover. The following hadith contains the words:","“Call the physician of such-and-such a clan for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (24774)، والنسائي في عمل اليوم والليلة (1015)، والبيهقي في الأسماء والصفات (151)."},{"num":11534,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنَ الْأَنْصَارِ قَالَ: عَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا بِهِ جُرْحٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ادْعُوا لَهُ طَبِيبَ بَنِي فُلَانٍ، قَالَ: فَدَعَوْهُ فَجَاءَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، وَيُغْنِي الدَّوَاءُ شَيْئًا؟ فَقَالَ: سُبْحَانَ اللَّهِ، وَهَلْ أَنْزَلَ اللَّهُ مِنْ دَاءٍ فِي الْأَرْضِ، إِلَّا جَعَلَ لَهُ شِفَاءً."],"takhrij":"صحيح: رواه أحمد (23156) عن إسحاق بن يوسف، حدثنا سفيان (هو الثوري)، عن منصور (هو ابن المعتمر)، عن هلال بن يساف، عن ذكوان، عن رجل من الأنصار فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أن الشافي هو اللّٰه تعالى","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23156).","chapter_en":"Allah the Exalted Is the One Who Heals","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["A man from among the Anṣār narrated: The Messenger of Allah ﷺ visited a man who had a wound and said: “Call the physician of such-and-such a clan for him.” They called him, and he came. The physician asked: “O Messenger of Allah, does medicine truly benefit?” The Prophet ﷺ replied: “Glory be to Allah! Has Allah sent down any illness upon the earth without also providing a cure for it?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23156)."},{"num":11535,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ، الصِّحَّةُ وَالْفَرَاغُ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6412) عن المكي بن إبراهيم، أخبرنا عبد الله بن سعيد، -وهو ابن أبي هند- عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نعمة الصحة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6412).","chapter_en":"What Has Been Reported Concerning the Blessing of Health","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that the Prophet ﷺ said: “There are two blessings concerning which many people suffer loss: health and free time.”"]}},"tuhfa":{},"full":1,"rep":[15147],"tks":"صحيح: رواه البخاري (6412)."},{"num":11536,"demo":false,"sanad":"","matn":["عَنْ أَبِي خُزَامَةَ أَحَدَ بَنِي الْحَارِثِ بْنِ سَعْدِ بْنِ هَزِيمٍ حَدَّثَهُ، أَنَّ أَبَاهُ حَدَّثَهُ أَنَّهُ، قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ دَوَاءً نَتَدَاوَى بِهِ، وَرُقًى نَسْتَرْقِيهَا، وَتُقًى نَتَّقِيهَا، هَلْ تَرُدُّ ذَلِكَ مِنْ قَدَرِ اللَّهِ مِنْ شَيْءٍ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهُ مِنْ قَدَرِ اللَّهِ."],"takhrij":"حسن: رواه عبدالله بن وهب في \"الجامع\" (699) قال: أخبرني يونس بن يزيد وعمرو بن الحارث وابن سمعان، أنّ ابن شهاب أخبرهم أنّ أبا خُزامة، فذكره.","grade":"حسن","chapter_ar":"باب أن التداوي والاسترقاء من قدر اللّٰه","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbdullāh ibn Wahb in al-Jāmiʿ (699).","chapter_en":"Medical Treatment and Seeking Ruqyah Are Part of Allah’s Decree","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abū Khuzāmah, a member of Banū al-Ḥārith ibn Saʿd ibn Hudhaym, narrated from his father that he asked the Messenger of Allah ﷺ: “O Messenger of Allah, what do you say about medicine with which we treat ourselves, ruqyah which we seek, and precautions which we take? Do any of these repel anything from Allah’s decree?” The Messenger of Allah ﷺ replied: “They themselves are part of Allah’s decree.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1027],"tks":"حسن: رواه عبد الله بن وهب في الجامع (699)."},{"num":11537,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَنْزَلَ اللَّهُ دَاءً إِلاَّ أَنْزَلَ لَهُ شِفَاءً."],"takhrij":"صحيح: رواه البخاري في الطب (5678) عن محمد بن المثنى، ثنا أبو أحمد الزبيري، ثنا عمر بن سعيد بن أبي حسين، ثنا عطاء بن أبي رباح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما أنزل اللّٰه داء إلا أنزل له دواء، فتداووا يا عباد اللّٰه","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5678).","chapter_en":"Allah Has Not Sent Down an Illness without Sending Down Its Cure, So Seek Treatment, O Servants of Allah","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah has not sent down an illness without also sending down its cure.”"]},"buhuth":{"en":["The words “Allah has not sent down an illness” mean that Allah has not created an illness. Since creation comes from Allah, the Exalted, who is above the heavens, the expression “sent down” is used, as Allah said:","“He directs every matter from the heaven to the earth.”","[Sūrat al-Sajdah 32:5]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5678)."},{"num":11538,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  لِكُلِّ دَاءٍ دَوَاءٌ، فَإِذَا أُصِيبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه مسلم في السلام (2204) من طرق عن ابن وهب، أخبرني عمرو بن الحارث، عن عبد ربه بن سعيد، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما أنزل اللّٰه داء إلا أنزل له دواء، فتداووا يا عباد اللّٰه","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2204).","chapter_en":"Allah Has Not Sent Down an Illness without Sending Down Its Cure, So Seek Treatment, O Servants of Allah","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “Every illness has a cure. When the correct cure is applied to the illness, the person recovers by the permission of Allah, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2204)."},{"num":11539,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  - قَالَ: إِنَّ اللَّهَ - عز وجل - حَيْثُ خَلَقَ الدَّاءَ خَلَقَ الدَّوَاءَ، فَتَدَاوُوا."],"takhrij":"حسن: رواه أحمد (12596)، وابن أبي شيبة (23881)، وأبو نعيم في الطب النبوي (49) كلهم من حديث يونس بن محمد (هو المؤدب)، عن حرب بن ميمون قال: سمعت عمران العمي قال: سمعت أنسا يقول فذكره.","grade":"حسن","chapter_ar":"باب ما أنزل اللّٰه داء إلا أنزل له دواء، فتداووا يا عباد اللّٰه","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12596), Ibn Abī Shaybah (23881), and Abū Nuʿaym in al-Ṭibb al-Nabawī (49).","chapter_en":"Allah Has Not Sent Down an Illness without Sending Down Its Cure, So Seek Treatment, O Servants of Allah","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “When Allah created illness, He also created its cure, so seek treatment.”"]},"buhuth":{"en":["This hadith explains the words of the Prophet ﷺ:","“Allah has not sent down an illness without sending down its cure.”","That is, Allah has not created an illness without also creating a treatment for it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12596)، وابن أبي شيبة (23881)، وأبو نعيم في الطب النبوي (49)."},{"num":11540,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ شَرِيكٍ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ كَأَنَّمَا عَلَى رؤوسهم الطَّيْرُ، فَسَلَّمْتُ ثُمَّ قَعَدْتُ، فَجَاءَ الأَعْرَابُ مِنْ هَاهُنَا وهاهنا فَقَالُوا: يَا رَسُولَ اللَّهِ أَنَتَدَاوَى؟ فَقَالَ: تَدَاوَوْا؛ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يَضَعْ دَاءً إِلاَّ وَضَعَ لَهُ دَوَاءً غَيْرَ دَاءٍ وَاحِدٍ الْهَرَمُ."],"takhrij":"صحيح: رواه أبوداود (3855)، والترمذي (2038)، وابن ماجه (3436)، وأحمد (18454)، والبخاري في الأدب المفرد (291)، وصحّحه ابن حبان (6064)، والحاكم (4/399-400) كلهم من طرق عن زياد بن علاقة، عن أسامة بن شريك به.واللفظ لأبي داود.وفي بعض الروايات زيادة \"السام\" وهو الموت.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما أنزل اللّٰه داء إلا أنزل له دواء، فتداووا يا عباد اللّٰه","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3855), al-Tirmidhī (2038), Ibn Mājah (3436), and Aḥmad (18454).","chapter_en":"Allah Has Not Sent Down an Illness without Sending Down Its Cure, So Seek Treatment, O Servants of Allah","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Usāmah ibn Sharīk narrated: I came to the Prophet ﷺ while his Companions were sitting so still that it was as though birds were perched upon their heads. I greeted them and sat down. Bedouins then came from various directions and asked: “O Messenger of Allah, should we seek medical treatment?” He replied: “Seek treatment, for Allah, Mighty and Majestic, has not created an illness without also creating its cure, except for one illness: old age.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3855)، والترمذي (2038)، وابن ماجه (3436)، وأحمد (18454)."},{"num":11541,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَنْزَلَ اللَّهُ دَاءً، إِلَّا قَدْ أَنْزَلَ لَهُ شِفَاءً، عَلِمَهُ مَنْ عَلِمَهُ، وَجَهِلَهُ مَنْ جَهِلَهُ."],"takhrij":"صحيح: رواه ابن ماجه (3438)، وأحمد (3578)، والحاكم (8205) كلهم من طريق سفيان الثوري، عن عطاء بن السائب، عن أبي عبد الرحمن السلمي قال: أخبرنا ابن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب ما أنزل اللّٰه داء إلا أنزل له دواء، فتداووا يا عباد اللّٰه","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3438), Aḥmad (3578), and al-Ḥākim (8205).","chapter_en":"Allah Has Not Sent Down an Illness without Sending Down Its Cure, So Seek Treatment, O Servants of Allah","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Allah has not sent down an illness without also sending down its cure. Whoever knows it knows it, and whoever remains ignorant of it remains ignorant of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3438)، وأحمد (3578)، والحاكم (8205)."},{"num":11542,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدَّوَاءِ الْخَبِيثِ."],"takhrij":"حسن: رواه أبو داود (3870)، والترمذي (2045)، وابن ماجه (3459)، وأحمد (9756)، وصحّحه الحاكم (8260) كلهم من طرق عن يونس بن أبي إسحاق، عن مجاهد، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3870), al-Tirmidhī (2045), Ibn Mājah (3459), and Aḥmad (9756).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated: “The Messenger of Allah ﷺ prohibited impure and harmful medicine.”"]},"buhuth":{"en":["The expression “impure and harmful medicine” is explained in the narrations of al-Tirmidhī, Ibn Mājah, and Aḥmad as referring to poison.","A severe warning concerning the consumption of poison appears in the following hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3870)، والترمذي (2045)، وابن ماجه (3459)، وأحمد (9756)."},{"num":11543,"demo":false,"sanad":"","matn":["عَنِ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ تَحَسَّى سُمًّا فَقَتَلَ نَفْسَهُ، فَهُوَ يَتَحَسَّاهُ فِي نَارِ جَهَنَّمَ، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا."],"takhrij":"متفق عليه: رواه البخاري في الطب (5778)، ومسلم في الإيمان (109: 175) كلاهما من طريق خالد بن الحارث، حدثنا شعبة، عن سليمان قال: سمعت ذكوان يحدث عن أبي هريرة فذكره في أثناء حديث.","grade":"متفق عليه","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5778) and Muslim (109/175).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever drinks poison and thereby kills himself will have that poison in his hand, continually drinking it in the Fire of Hell, remaining therein forever.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5778)، ومسلم (109: 175)."},{"num":11544,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ اشْتَكَتِ ابْنَةٌ لِي، فَنَبَذْتُ لَهَا فِي كُوزٍ، فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَغْلِي، فَقَالَ: مَا هَذَا؟ فَقُلْتُ: إِنَّ ابْنَتِي اشْتَكَتْ فَنَبَذْنَا لَهَا هَذَا، فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يَجْعَلْ شِفَاءَكُمْ فِي حَرَامٍ."],"takhrij":"حسن: رواه أبو يعلى (6966) –وعنه ابن حبان (1391)- وأحمد في الأشربة (159) كلاهما من طريق جرير (وهو ابن عبد الحميد)، عن الشيباني (وهو أبو إسحاق سليمان)، عن حسان بن مخارق، عن أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (6966), and through his route by Ibn Ḥibbān (1391), and by Aḥmad in al-Ashribah (159).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Umm Salamah narrated: A daughter of mine became ill, so I prepared a fermented drink for her in a jug. The Prophet ﷺ entered while it was bubbling and asked: “What is this?” I replied: “My daughter became ill, so we prepared this drink for her.” The Prophet ﷺ said: “Allah has not placed your healing in something unlawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (6966)، ومن طريقه ابن حبان (1391)، وأحمد في الأشربة (159)."},{"num":11545,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ أَنْزَلَ الدَّاءَ وَالدَّوَاءَ، وَجَعَلَ لِكُلِّ دَاءٍ دَوَاءً، فَتَدَاوَوْا وَلاَ تَدَاوَوْا بِحَرَامٍ."],"takhrij":"حسن: رواه أبو داود (3874) عن محمد بن عبادة الواسطى،حدثنا يزيد بن هارون، أخبرنا إسماعيل بن عياش، عن ثعلبة بن مسلم، عن أبى عمران، عن أم الدرداء، عن أبى الدرداء فذكره.","grade":"حسن","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3874).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū al-Dardāʾ narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, has sent down illness and medicine and has provided a treatment for every illness. Therefore, seek treatment, but do not seek treatment with anything unlawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3874)."},{"num":11546,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجر الحضرمي: أَنَّ طَارِقَ بْنَ سُوَيْدٍ الْجُعْفِيَّ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَمْرِ، فَنَهَاهُ أَوْ كَرِهَ أَنْ يَصْنَعَهَا فَقَالَ: إِنَّمَا أَصْنَعُهَا لِلدَّوَاءِ فَقَالَ: إِنَّهُ لَيْسَ بِدَوَاءٍ، وَلَكِنَّهُ داءٌ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1984: 12) من طرق عن محمد بن جعفر، حدثنا شعبة، عن سماك بن حرب، عن علقمة بن وائل، عن أبيه وائل الحضرمي فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1984/12).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Wā’il ibn Ḥujr al-Ḥaḍramī narrated: Ṭāriq ibn Suwayd al-Juʿfī asked the Prophet ﷺ about wine. The Prophet ﷺ prohibited him from making it, or expressed disapproval of doing so. Ṭāriq said: “I only make it as medicine.” The Prophet ﷺ replied: “It is not a medicine; rather, it is an illness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1984: 12)."},{"num":11547,"demo":false,"sanad":"","matn":["عَنْ طَارِقِ بْنِ سُوَيْدٍ الْحَضْرَمِيِّ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ بِأَرْضِنَا أَعْنَابًا نَعْتَصِرُهَا، فَنَشْرَبُ مِنْهَا؟ قَالَ: لاَ. فَرَاجَعْتُهُ، قُلْتُ: إِنَّا نَسْتَشْفِي بِهِ لِلْمَرِيضِ. قَالَ: إِنَّ ذَلِكَ لَيْسَ بِشِفَاءٍ، وَلَكِنَّهُ دَاءٌ."],"takhrij":"صحيح: رواه ابن ماجه (3500)، وأحمد (18787)، وصحّحه ابن حبان (1389) كلهم من حديث حماد بن سلمة، حدثنا سماك بن حرب، عن علقمة بن وائل، عن طارق بن سويد فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3500), Aḥmad (18787), and authenticated by Ibn Ḥibbān (1389).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ṭāriq ibn Suwayd al-Ḥaḍramī narrated: I said: “O Messenger of Allah, grapes grow in our land. We press them and drink from them.” He replied: “No.” I repeated my question and said: “We use it to treat the sick.” He replied: “It is not a cure; rather, it is an illness.”"]},"buhuth":{"en":["The words “We press them and drink from them” refer to drinking the juice after it has fermented and become wine. Grape juice itself is not forbidden.","The words “Rather, it is an illness” mean that wine causes various diseases, as is now established. Therefore, one should not be deceived by anyone who claims that it provides health and strength."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3500)، وأحمد (18787)، وصححه ابن حبان (1389)."},{"num":11548,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ، أَنَّ طَبِيبًا، سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ضِفْدَعٍ يَجْعَلُهَا فِي دَوَاءٍ، فَنَهَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا."],"takhrij":"حسن: رواه أبو داود (3871)، والنسائي (4355)، وأحمد (15757)، وصحّحه الحاكم (4/410-411) كلهم من طرق عن ابن أبي ذئب، عن سعيد بن خالد، عن سعيد بن المسيب، عن عبد الرحمن بن عثمان التيمي فذكره.","grade":"حسن","chapter_ar":"باب النهي عن التداوي بالحرام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3871), al-Nasā’ī (4355), Aḥmad (15757), and authenticated by al-Ḥākim (4/410–411).","chapter_en":"The Prohibition of Seeking Treatment with Unlawful Substances","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿUthmān narrated: A physician asked the Prophet ﷺ about using a frog in medicine, but the Prophet ﷺ prohibited him from killing it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14822],"tks":"حسن: رواه أبو داود (3871)، والنسائي (4355)، وأحمد (15757)، وصححه الحاكم (4/410-411)."},{"num":11549,"demo":false,"sanad":"","matn":["عَنْ أُمِّ الْمُنْذِرِ بِنْتِ قَيْسٍ الأَنْصَارِيَّةِ، قَالَتْ: دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ عَلِيٌّ، عَلَيْهِ السَّلاَمُ وَعَلِيٌّ نَاقِهٌ، وَلَنَا دَوَالِي مُعَلَّقَةٌ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مِنْهَا، وَقَامَ عَلِيٌّ لِيَأْكُلَ فَطَفِقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِعَلِيٍّ: مَهْ إِنَّكَ نَاقِهٌ. حَتَّى كَفَّ عَلِيٌّ عَلَيْهِ السَّلاَمُ. قَالَتْ: وَصَنَعْتُ شَعِيرًا وَسِلْقًا، فَجِئْتُ بِهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَلِيُّ أَصِبْ مِنْ هَذَا فَهُوَ أَنْفَعُ لَكَ."],"takhrij":"حسن: رواه أبو داود (3856)، والترمذي (2037م)، وابن ماجه (34429)، وأحمد (27051-27053)، والحاكم (4/204) كلهم من طرق عن فليح بن سليمان، عن أيوب بن عبد الرحمن بن صعصعة، عن يعقوب بن أبي يعقوب، عن أم المنذر بنت قيس فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في الحمية","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3856), al-Tirmidhī (2037), Ibn Mājah (3442), and Aḥmad (27051–27053).","chapter_en":"What Has Been Reported Concerning Dietary Restraint during Illness","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Umm al-Mundhir bint Qays al-Anṣāriyyah narrated: The Messenger of Allah ﷺ entered my home accompanied by ʿAlī, who was recovering from an illness. We had clusters of dates hanging there. The Messenger of Allah ﷺ began eating from them, and ʿAlī also stood to eat. The Messenger of Allah ﷺ repeatedly said to him: “Stop, for you are still recovering.” ʿAlī then stopped. She continued: I prepared barley and chard and brought them. The Messenger of Allah ﷺ said: “ʿAlī, eat from this, for it is more beneficial for you.”"]},"buhuth":{"en":["The word nāqih refers to a sick person who has recovered and regained consciousness but is still close to the period of illness and has not yet regained full health and strength."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3856)، والترمذي (2037)، وابن ماجه (34429)، وأحمد (27051-27053)."},{"num":11550,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ بْنِ النُّعْمَانِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أَحَبَّ اللَّهُ عَبْدًا حَمَاهُ الدُّنْيَا كَمَا يَظَلُّ أَحَدُكُمْ يَحْمِي سَقِيمَهُ الْمَاءَ."],"takhrij":"حسن: رواه الترمذي (2036)، وأحمد في الزهد (57)، وصحّحه ابن حبان (669)، والحاكم (7464) كلهم من طريق إسماعيل بن جعفر، عن عمارة بن غزية، عن عاصم بن عمر بن قتادة، عن محمود بن لبيد، عن قتادة بن النعمان ذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الحمية","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2036), Aḥmad in al-Zuhd (57), and authenticated by Ibn Ḥibbān (669) and al-Ḥākim (7464).","chapter_en":"What Has Been Reported Concerning Dietary Restraint during Illness","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Qatādah ibn al-Nuʿmān narrated that the Messenger of Allah ﷺ said: “When Allah loves a servant, He protects him from worldly things just as one of you continually protects his sick person from water.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2036)، وأحمد في الزهد (57)، وصححه ابن حبان (669)، والحاكم (7464)."},{"num":11551,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الشِّفَاءُ فِي ثَلاَثَةٍ: شَرْطَةِ مِحْجَمٍ، أَوْ شَرْبَةِ عَسَلٍ، أَوْ كَيَّةٍ بِنَارٍ، وَأَنْهَى أُمَّتِي عَنِ الْكَىِّ."],"takhrij":"صحيح: رواه البخاري في الطب (5681) عن محمد بن عبد الرحيم، أخبرنا سريج بن يونس أبو الحارث، ثنا مروان بن شجاع، عن سالم الأفطس، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب أن الشفاء في ثلاث: الحجامة، والعسل، والكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5681).","chapter_en":"Healing Is Found in Three Things: Cupping, Honey, and Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “Healing is found in three things: an incision made by a cupping instrument, a drink of honey, or cauterization with fire. Yet I prohibit my nation from cauterization.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5681)."},{"num":11552,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ قَالَ:  جَاءَنَا جَابِرُ بْنُ عَبْدِ اللَّهِ فِي أَهْلِنَا، وَرَجُلٌ يَشْتَكِي خُرَاجًا بِهِ أَوْ جِرَاحًا، فَقَالَ: مَا تَشْتَكِي. قَالَ: خُرَاجٌ بِي قَدْ شَقَّ عَلَيَّ! فَقَالَ: يَا غُلَامُ، ائْتِنِي بِحَجَّامٍ. فَقَالَ لَهُ: مَا تَصْنَعُ بِالْحَجَّامِ يَا أَبَا عَبْدِ اللَّهِ؟ قَالَ: أُرِيدُ أَنْ أُعَلِّقَ فِيهِ مِحْجَمًا. قَالَ: وَاللهِ إِنَّ الذُّبَابَ لَيُصِيبُنِي أَوْ يُصِيبُنِي الثَّوْبُ فَيُؤْذِينِي وَيَشُقُّ عَلَيَّ! فَلَمَّا رَأَى تَبَرُّمَهُ مِنْ ذَلِكَ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنْ كَانَ فِي شَيْءٍ مِنْ أَدْوِيَتِكُمْ خَيْرٌ، فَفِي شَرْطَةِ مَِحْجَمٍ، أَوْ شَرْبَةٍ مِنْ عَسَلٍ، أَوْ لَذْعَةٍ بِنَارٍ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَمَا أُحِبُّ أَنْ أَكْتَوِيَ. قَالَ: فَجَاءَ بِحَجَّامٍ، فَشَرَطَهُ، فَذَهَبَ عَنْهُ مَا يَجِدُ."],"takhrij":"متفق عليه: رواه مسلم في السلام (2205: 71) عن نصر بن علي الجهضمي، ثني أبي، ثنا عبد الرحمن بن سليمان، عن عاصم بن عمر قتادة فذكره.","grade":"متفق عليه","chapter_ar":"باب أن الشفاء في ثلاث: الحجامة، والعسل، والكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2205/71) and al-Bukhārī (5683).","chapter_en":"Healing Is Found in Three Things: Cupping, Honey, and Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿĀṣim ibn ʿUmar ibn Qatādah narrated: Jābir ibn ʿAbdullāh came to visit our family while a man among us was suffering from an abscess or wound. Jābir asked: “What are you suffering from?” The man replied: “I have an abscess that has caused me severe pain.” Jābir said: “Young man, bring me a cupper.” The sick man asked: “What will you do with a cupper, Abū ʿAbdullāh?” He replied: “I want him to apply a cupping instrument to it.” The man said: “By Allah, even when a fly touches it, or my clothing touches it, it causes me pain and severe discomfort.” When Jābir saw his aversion to the treatment, he said: I heard the Messenger of Allah ﷺ say: “If there is good in any of your treatments, it is in an incision made by a cupping instrument, a drink of honey, or cauterization with fire.” The Messenger of Allah ﷺ also said: “I do not like to be cauterized.” A cupper was then brought, and he made an incision upon the man, after which the pain he had been experiencing disappeared."]},"buhuth":{"en":["The man who was suffering was al-Muqannaʿ ibn Sinān, as stated in another narration."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2205: 71)، والبخاري (5683)."},{"num":11553,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ حُدَيْجٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ كَانَ فِي شَيْءٍ شِفَاءٌ فَفِي شَرْطَةِ مِحْجَمٍ، أَوْ شَرْبَةٍ مِنْ عَسَلٍ، أَوْ كَيَّةٍ بِنَارٍ تُصِيبُ أَلَمًا، وَمَا أُحِبُّ أَنْ أَكْتَوِيَ."],"takhrij":"صحيح: رواه أحمد (27256)، والطبراني في الكبير (19/430)، وفي الأوسط (9333)، والنسائي في الكبرى (7603) كلهم من حديث سعيد بن أبي أيوب قال: حدثني يزيد بن أبي حبيب، عن سويد بن قيس التجيبي من كندة، عن معاوية خديج فذكره.","grade":"صحيح","chapter_ar":"باب أن الشفاء في ثلاث: الحجامة، والعسل، والكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (27256), al-Ṭabarānī in al-Muʿjam al-Kabīr (19/430), and in al-Muʿjam al-Awsaṭ (9333).","chapter_en":"Healing Is Found in Three Things: Cupping, Honey, and Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Muʿāwiyah ibn Ḥudayj narrated that the Messenger of Allah ﷺ said: “If healing is found in anything, it is in an incision made by a cupping instrument, a drink of honey, or cauterization with fire applied to the painful area. Yet I do not like to be cauterized.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (27256)، والطبراني في الكبير (19/430)، وفي الأوسط (9333)."},{"num":11554,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثًا إِنْ كَانَ فِي شَيْءٍ شِفَاءٌ: فَفِي شَرْطَةِ مِحْجَمٍ، أَوْ شَرْبَةِ عَسَلٍ، أَوْ كَيَّةٍ تُصِيبُ أَلَمًا، وَأَنَا أَكْرَهُ الْكَيَّ وَلَا أُحِبُّهُ."],"takhrij":"حسن: رواه أحمد (17315)، وأبو يعلى في مسنده (1765)، والطبراني في الأوسط (9335)، وفي الكبير (17/288-289) كلهم من حديث عبد الله بن الوليد، عن أبي الخير، عن عقبة بن عامر الجهني قال: فذكره.","grade":"حسن","chapter_ar":"باب أن الشفاء في ثلاث: الحجامة، والعسل، والكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17315), Abū Yaʿlā in his Musnad (1765), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (9335).","chapter_en":"Healing Is Found in Three Things: Cupping, Honey, and Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī narrated that the Messenger of Allah ﷺ said: “There are three things in which healing may be found: an incision made by a cupping instrument, a drink of honey, or cauterization applied to a painful area. I dislike cauterization and do not love it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17315)، وأبو يعلى في مسنده (1765)، والطبراني في الأوسط (9335)."},{"num":11555,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدٍ قَالَ:  سُئِلَ أَنَسُ بْنُ مَالِكٍ عَنْ كَسْبِ الْحَجَّامِ؟ فَقَالَ: احْتَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَجَمَهُ أَبُو طَيْبَةَ، فَأَمَرَ لَهُ بِصَاعَيْنِ مِنْ طَعَامٍ، وَكَلَّمَ أَهْلَهُ فَوَضَعُوا عَنْهُ مِنْ خَرَاجِهِ، وَقَالَ: إِنَّ أَفْضَلَ مَا تَدَاوَيْتُمْ بِهِ الْحِجَامَةُ. أَوْ: هُوَ مِنْ أَمْثَلِ دَوَائِكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5696)، ومسلم في المساقاة والمزارعة (1577) كلاهما من طريق حميد فذكره.واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5696) and Muslim (1577). The wording cited here is that of Muslim.","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Ḥumayd narrated: Anas ibn Mālik was asked about the earnings of a cupper. He replied: The Messenger of Allah ﷺ underwent cupping, and Abū Ṭaybah performed it for him. The Prophet ﷺ ordered that he be given two sāʿs of food and spoke to his masters, who reduced the payment he was required to give them. The Prophet ﷺ said: “Cupping is among the best treatments you use,” or: “It is among the most effective of your medicines.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5696)، ومسلم (1577)، واللفظ لمسلم."},{"num":11556,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا عَادَ الْمُقَنَّعَ ثُمَّ قَالَ: لاَ أَبْرَحُ حَتَّى تَحْتَجِمَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ فِيهِ شِفَاءً."],"takhrij":"متفق عليه: رواه البخاري في الطب (5697)، ومسلم في السلام (2205) كلاهما من حديث ابن وهب قال: أخبرني عمرو وغيره أن بكيرا حدثه أن عاصم بن عمر بن قتادة حدثه أن جابر بن عبد الله عاد المقنّع فذكره.","grade":"متفق عليه","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5697) and Muslim (2205).","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh visited al-Muqannaʿ and said: “I will not leave until you undergo cupping, for I heard the Messenger of Allah ﷺ say: ‘Indeed, there is healing in it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5697)، ومسلم (2205)."},{"num":11557,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنْ كَانَ فِي شَىْءٍ مِمَّا تَدَاوَيْتُمْ بِهِ خَيْرٌ فَالْحِجَامَةُ."],"takhrij":"حسن: رواه أبو داود (3857)، وابن ماجه (3476)، وأحمد (8513)، وصحّحه ابن حبان (6078)، والحاكم (8257) كلهم من طرق عن حماد بن سلمة، حدثنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3857), Ibn Mājah (3476), Aḥmad (8513), and authenticated by Ibn Ḥibbān (6078).","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If there is good in any of the treatments you use, it is in cupping.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3857)، وابن ماجه (3476)، وأحمد (8513)، وصححه ابن حبان (6078)."},{"num":11558,"demo":false,"sanad":"","matn":["عن سلمى خادم رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: مَا كَانَ أَحَدٌ يَشْتَكِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعًا فِي رَأْسِهِ إِلاَّ قَالَ: احْتَجِمْ. وَلاَ وَجَعًا فِي رِجْلَيْهِ إِلاَّ قَالَ."],"takhrij":"حسن: رواه أبو داود (3858) عن محمد بن الوزير الدمشقي، حدثنا يحيى بن حسان، حدثنا عبد الرحمن بن أبي الموالي، حدثنا فائد مولى عبيد الله بن علي بن أبي رافع، عن مولاه عبيد الله بن علي بن أبي رافع، عن جدته سلمى خادم رسول الله صلى الله عليه وسلم فذكرته.","grade":"حسن","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3858).","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Salmā, the servant of the Messenger of Allah ﷺ, narrated: “No one ever complained to the Messenger of Allah ﷺ of pain in his head except that he said, ‘Undergo cupping,’ nor of pain in his legs except that he said, ‘Apply henna to them.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3858)."},{"num":11559,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، قَالَ: كُنْتُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَعَا حَجَّامًا، فَأَمَرَهُ أَنْ يَحْجُمَهُ، فَأَخْرَجَ مَحَاجِمَ لَهُ مِنْ قُرُونٍ، فَأَلْزَمَهُ إِيَّاهُ، فَشَرَطَهُ بِطَرَفِ شَفْرَةٍ، فَصَبَّ الدَّمَ فِي إِنَاءٍ عِنْدَهُ، فَدَخَلَ عَلَيْهِ رَجُلٌ مِنْ بَنِي فَزَارَةَ، فَقَالَ: مَا هَذَا يَا رَسُولَ اللَّهِ؟ عَلَامَ تُمَكِّنُ هَذَا مِنْ جِلْدِكَ يَقْطَعُهُ؟ قَالَ: فَسَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: هَذَا الْحَجْمُ، قَالَ: وَمَا الْحَجْمُ؟ قَالَ: هُوَ مِنْ خَيْرِ مَا تَدَاوَى بِهِ النَّاسُ."],"takhrij":"صحيح: رواه أحمد (20172)، والبزار –كشف الأستار (1216)، والطبراني في الكبير (6786)، وصحّحه الحاكم (4/208) كلهم من طريق عبدالملك بن عمير، عن حصين بن أبي الحُرّ (هو حصين بن مالك بن الخشخاش)، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (20172), al-Bazzār in Kashf al-Astār (1216), and al-Ṭabarānī in al-Muʿjam al-Kabīr (7/223).","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Samurah ibn Jundub narrated: I was with the Messenger of Allah ﷺ when he summoned a cupper and instructed him to perform cupping. The cupper brought cupping vessels made from horns, attached them to him, made an incision with the edge of a blade, and poured the blood into a vessel beside him. A man from Banū Fazārah entered and asked: “What is this, O Messenger of Allah? Why are you allowing this man to cut your skin?” The narrator said: I heard the Prophet ﷺ say: “This is cupping.” The man asked: “What is cupping?” He replied: “It is among the best treatments used by people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20172)، والبزار في كشف الأستار (1216)، والطبراني في الكبير (6786)."},{"num":11560,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ  أَنَّ أُمَّ سَلَمَةَ اسْتَأْذَنَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحِجَامَةِ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا طَيْبَةَ أَنْ يَحْجُمَهَا.","قَالَ: حَسِبْتُ أَنَّهُ قَالَ: كَانَ أَخَاهَا مِنَ الرَّضَاعَةِ أَوْ غُلَامًا لَمْ يَحْتَلِمْ."],"takhrij":"صحيح: رواه مسلم في السلام (2206) من طرق عن الليث بن سعد، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2206).","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jābir narrated: Umm Salamah sought the permission of the Messenger of Allah ﷺ to undergo cupping, so the Prophet ﷺ instructed Abū Ṭaybah to perform it for her. The narrator said: “I believe he said that Abū Ṭaybah was her foster brother, or that he was a boy who had not yet reached puberty.”"]}},"tuhfa":{},"full":1,"rep":[15560],"tks":"صحيح: رواه مسلم (2206)."},{"num":11561,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَيَّةَ الْفَزَارِيَّ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْتَجِمُ."],"takhrij":"حسن: رواه أحمد (18779) عن الفضل بن دكين، حدثنا شريك، عن أبي جعفر الفراء قال: سمعت أبا أمية الفزاري فذكره.","grade":"حسن","chapter_ar":"باب التداوي بالحجامة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (18779).","chapter_en":"Seeking Treatment through Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Umayyah al-Fazārī narrated: “I saw the Messenger of Allah ﷺ undergoing cupping.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18779)."},{"num":11562,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، احْتَجَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَأْسِهِ وَهْوَ مُحْرِمٌ مِنْ وَجَعٍ كَانَ بِهِ بِمَاءٍ يُقَالُ لَهُ: لَحْىُ جَمَلٍ.","وفي رواية: احتجم وهو محرم في رأسه من شقيقة كانت به."],"takhrij":"متفق عليه: رواه البخاري في الطب (5700) عن محمد بن بشار، ثنا ابن أبي عدي، عن هشام (هو ابن حسان)، عن عكرمة، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب الحجامة من الشقيقة والصداع","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5700) and Muslim (1202/87).","chapter_en":"Cupping for Migraine and Headache","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ underwent cupping on his head while he was in the state of iḥrām because of pain he was suffering from, at a place called Laḥy Jamal. Another narration states: “He underwent cupping on his head while in the state of iḥrām because of a migraine.”"]},"buhuth":{"en":["The word shaqīqah refers to a type of headache affecting the front of the head and extending toward one side."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5700)، ومسلم (1202/87)."},{"num":11563,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن بحينة أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ بلحي جَمَلٍ مِنْ طَرِيقِ مَكَّةَ وَهْوَ مُحْرِمٌ فِي وَسَطِ رَأْسِهِ.","وفي رواية: أنه احتجم وهو محرم في رأسه لصداع كان فيه."],"takhrij":"متفق عليه: رواه البخاري في الطب (5698)، ومسلم في الحج (1203) كلاهما من طريق سليمان بن بلال، عن علقمة بن أبي علقمة، عن عبد الرحمن الأعرج أنه سمع عبدالله بن بحينة فذكره.","grade":"متفق عليه","chapter_ar":"باب الحجامة من الشقيقة والصداع","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5698) and Muslim (1203).","chapter_en":"Cupping for Migraine and Headache","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn Buḥaynah narrated: The Messenger of Allah ﷺ underwent cupping at Laḥy Jamal, on the road to Makkah, while he was in the state of iḥrām. The cupping was performed in the middle of his head. Another narration states: “He underwent cupping on his head while in the state of iḥrām because of a headache.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5698)، ومسلم (1203)."},{"num":11564,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: إِذَا هاجَ بِأَحَدِكُمُ الدَّمُ فَلْيَحْتَجِمْ، فَإِنَّ الدَّمَ إِذَا تَبَيَّغَ بِصَاحِبِهِ يَقْتُلُهُ."],"takhrij":"حسن: رواه الطبري في تهذيب الآثار (779) عن موسى بن سهل الرملي، حدثنا محمد بن عبدالعزيز، حدثنا سليمان بن حيان، حدثنا حميد الطويل، عن أنس قال: فذكره.","grade":"حسن","chapter_ar":"باب استحباب الحجامة عند هيجان الدم","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarī in Tahdhīb al-Āthār (779).","chapter_en":"The Recommendation to Undergo Cupping When the Blood Becomes Agitated","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “When the blood becomes agitated within one of you, let him undergo cupping, for when the blood overwhelms a person, it may kill him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبري في تهذيب الآثار (779)."},{"num":11565,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْتَجِمُ فِي الأَخْدَعَيْنِ وَالْكَاهِلِ، وَكَانَ يَحْتَجِمُ لِسَبْعَ عَشْرَةَ، وَتِسْعَ عَشْرَةَ، وَإِحْدَى وَعِشْرِينَ."],"takhrij":"صحيح: رواه أبو داود (3860)، والترمذي (2051)، وابن ماجه (3483)، وأحمد (12191)، وصحّحه ابن حبان (6077)، والحاكم (7477) كلهم من طرق عن قتادة، عن أنس فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في مواضع الحجامة وأوقاتها","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3860), al-Tirmidhī (2051), Ibn Mājah (3483), and Aḥmad (12191).","chapter_en":"What Has Been Reported Concerning the Locations and Times of Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Anas narrated: “The Messenger of Allah ﷺ used to undergo cupping upon the two veins at the sides of the neck and upon the upper back between the shoulders. He would undergo cupping on the seventeenth, nineteenth, and twenty-first days of the lunar month.”"]},"buhuth":{"en":["The akhdāʿān are two veins located on either side of the neck."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3860)، والترمذي (2051)، وابن ماجه (3483)، وأحمد (12191)."},{"num":11566,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ احْتَجَمَ لِسَبْعَ عَشْرَةَ، وَتِسْعَ عَشْرَةَ، وَإِحْدَى وَعِشْرِينَ، كَانَ شِفَاءً مِنْ كُلِّ دَاءٍ."],"takhrij":"حسن: رواه أبو داود (3861)، وصحّحه الحاكم (7475) كلاهما من حديث أبي توبة الربيع بن نافع، حدثنا سعيد بن عبد الرحمن الجمحي، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.واللفظ لأبي داود واقتصر الحاكم على ذكر السابع عشر.","grade":"حسن","chapter_ar":"باب ما جاء في مواضع الحجامة وأوقاتها","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3861) and authenticated by al-Ḥākim (7475).","chapter_en":"What Has Been Reported Concerning the Locations and Times of Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever undergoes cupping on the seventeenth, nineteenth, and twenty-first days will find it a cure for every illness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3861)، وصححه الحاكم (7475)."},{"num":11567,"demo":false,"sanad":"","matn":["عَنْ أَبِي كَبْشَةَ الأَنْمَارِيِّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَحْتَجِمُ عَلَى هَامَتِهِ وَبَيْنَ كَتِفَيْهِ وَهُوَ يَقُولُ: مَنْ أَهْرَاقَ مِنْ هَذِهِ الدِّمَاءِ فَلاَ يَضُرُّهُ أَنْ لاَ يتداوي بشيء لشيء."],"takhrij":"حسن: رواه أبو داود (3859)، وابن ماجه (3484) كلاهما من طريق الوليد بن مسلم قال: حدثنا ابن ثوبان، عن أبيه، عن أبي كبشة الأنماري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في مواضع الحجامة وأوقاتها","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3859) and Ibn Mājah (3484).","chapter_en":"What Has Been Reported Concerning the Locations and Times of Cupping","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Kabshah al-Anmārī narrated: The Prophet ﷺ used to undergo cupping upon the crown of his head and between his shoulders, saying: “Whoever releases some of this blood will not be harmed if he does not use any other treatment for a particular illness.”"]},"buhuth":{"en":["Cupping is the extraction of blood from areas near the surface of the skin. In hot countries, it is among the most beneficial treatments because blood becomes more agitated there. It should be performed at the location required by the patient’s condition, and a skilled cupper knows where it should be applied. Cupping also has proper manners and rules that must be observed.","As for the timing of cupping, it is permissible to undergo it at any time. Al-Bukhārī therefore entitled a chapter:","“At What Time May a Person Undergo Cupping?”","Abū Mūsā underwent cupping at night.","Al-Ḥāfiẓ said in Fatḥ al-Bārī (10/149):","“There are narrations concerning suitable times for cupping, but none of them met al-Bukhārī’s conditions. It is as though he intended to indicate that cupping is performed when needed and is not restricted to one time rather than another.”","He also said:","“Since none of these narrations was established as authentic, Ḥanbal ibn Isḥāq said: ‘Aḥmad used to undergo cupping whenever his blood became agitated, regardless of the time.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3859)، وابن ماجه (3484)."},{"num":11568,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَأَعْطَى الْحَجَّامَ أَجْرَهُ، وَاسْتَعَطَ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5691)، ومسلم في السلام (1202: 76) كلاهما من حديث وهيب، حدثنا عبد الله بن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب دفع أجر الحجام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5691) and Muslim (1202/65).","chapter_en":"Paying the Cupper His Wages","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ underwent cupping, paid the cupper his wages, and used medicine administered through the nose."]},"buhuth":{"en":["They also narrated it through another route with the addition:","“Had he known it to be disliked, he would not have paid him.”","This is the wording of al-Bukhārī (2279). Muslim’s wording (1202/66) states:","“Had it been unlawful earnings, the Prophet ﷺ would not have paid him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5691)، ومسلم (1202/65)."},{"num":11569,"demo":false,"sanad":"","matn":["عَنْ أنس يَقُولُ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْتَجِمُ، وَلَمْ يَكُنْ يَظْلِمُ أَحَدًا أَجْرَهُ."],"takhrij":"متفق عليه: رواه البخاري في الإجارة (2280)، ومسلم في السلام (1577: 77) كلاهما من حديث مسعر، عن عمرو بن عامر الأنصاري قال: سمعت أنسا يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب دفع أجر الحجام","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2280) and Muslim (1577/77).","chapter_en":"Paying the Cupper His Wages","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Anas narrated: “The Prophet ﷺ used to undergo cupping, and he never withheld or reduced anyone’s rightful wages.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2280)، ومسلم (1577: 77)."},{"num":11570,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنْ كَانَ فِي شَىْءٍ مِنْ أَدْوِيَتِكُمْ خَيْرٌ، فَفِي شَرْبَةِ عَسَلٍ، أَوْ شَرْطَةِ مِحْجَمٍ، أَوْ لَذْعَةٍ مِنْ نَارٍ، وَمَا أُحِبُّ أَنْ أَكْتَوِيَ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5702)، ومسلم في السلام (2205: 71) كلاهما من طريق ابن الغسيل، حدثني عاصم بن عمر، عن جابر بن عبد الله فذكره.والسياق للبخاري، ولمسلم في أوله قصة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الاكتواء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5702) and Muslim (2205/71).","chapter_en":"What Has Been Reported Concerning the Dislike of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I heard the Prophet ﷺ say: “If there is good in any of your treatments, it is in a drink of honey, an incision made by a cupping instrument, or a burn with fire. Yet I do not like to be cauterized.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5702)، ومسلم (2205: 71)."},{"num":11571,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْكَىِّ، فَاكْتَوَيْنَا فَمَا أَفْلَحْنَ وَلاَ أَنْجَحْنَ."],"takhrij":"صحيح: رواه أبو داود (3865)، وأحمد (19989) كلاهما من طريق حماد (وهو ابن سلمة)، عن ثابت، عن مطرف (وهو ابن عبد الله بن الشخير)، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الاكتواء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3865) and Aḥmad (19989).","chapter_en":"What Has Been Reported Concerning the Dislike of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated: “The Prophet ﷺ prohibited cauterization. We later underwent cauterization, but it neither brought us success nor benefited us.”"]},"buhuth":{"en":["Abū Dāwūd added after this narration:","“He used to hear the angels greeting him. When he underwent cauterization, this ceased. When he abandoned it, the greeting returned.”","Its chain of transmission is authentic.","It has been said that using cauterization as treatment for a condition requiring it may succeed and may fail. When benefit is most likely, it is permissible to use it. When destruction or failure is most likely, it is disliked.","The prohibition of the Prophet ﷺ to ʿImrān was understood in this manner because he suffered from hemorrhoids, and cauterization could increase the danger of his condition. The Messenger of Allah ﷺ therefore prohibited him from undergoing it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3865)، وأحمد (19989)."},{"num":11572,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: جَاءَ نَاسٌ فَسَأَلُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَاحِبٍ لَهُمْ أَنْ يَكْوُوهُ، فَسَكَتَ، ثُمَّ سَأَلُوهُ ثَلَاثًا، فَسَكَتَ، وَكَرِهَ ذَلِكَ."],"takhrij":"صحيح: رواه ابن حبان (6082)، والطحاوي في شرحه (6998) كلاهما عن شعبة، قال: أنبأنا أبو إسحاق قال: سمعت أبا الأحوص يحدث عن عبدالله بن مسعود قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الاكتواء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (6082) and al-Ṭaḥāwī in Sharḥ Mushkil al-Āthār (6998).","chapter_en":"What Has Been Reported Concerning the Dislike of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: Some people came and asked the Messenger of Allah ﷺ whether they should cauterize a companion of theirs. He remained silent. They asked him three times, but he continued to remain silent and disliked it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (6082)، والطحاوي في شرح مشكل الآثار (6998)."},{"num":11573,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أُبَيِّ بْنِ كَعْبٍ طَبِيبًا، فَقَطَعَ مِنْهُ عِرْقًا، ثُمَّ كَوَاهُ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في السلام (2207) من طريق أبي معاوية (هو محمد بن خازم)، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2207).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ sent a physician to Ubayy ibn Kaʿb. The physician cut a vein and then cauterized the wound."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2207)."},{"num":11574,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  رُمِيَ سَعْدُ بْنُ مُعَاذٍ فِي أَكْحَلِهِ، قَالَ: فَحَسَمَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ بِمِشْقَصٍ، ثُمَّ وَرِمَتْ، فَحَسَمَهُ الثَّانِيَةَ."],"takhrij":"صحيح: رواه مسلم في السلام (2208) من طريق أبي خيثمة (زهير بن معاوية)، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2208).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Jābir narrated: Saʿd ibn Muʿādh was struck in the vein of his arm. The Prophet ﷺ cauterized it with his own hand using a broad-headed arrow. When it swelled, he cauterized it a second time."]},"buhuth":{"en":["The akḥal is a vein in the arm from which blood may be drawn. The expression “he sealed it” means that he cauterized it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8944,10213],"tks":"صحيح: رواه مسلم (2208)."},{"num":11575,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ أَبَا طَلْحَةَ وَأَنَسَ بْنَ النَّضْرِ كَوَيَاهُ، وَكَوَاهُ أَبُو طَلْحَةَ بِيَدِهِ."],"takhrij":"صحيح: رواه البخاري في الطب (5719، 5720، 5721) عن عارم، حدثنا حماد، قال: قُرِئ على أيوب من كتب أبي قلابة، منه ما حدّث به، ومنه ما ما قُرئ عليه، وكان في هذا الكتاب عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5719, 5720, 5721).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Anas narrated: Abū Ṭalḥah and Anas ibn al-Naḍr cauterized him, and Abū Ṭalḥah performed the cauterization with his own hand."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5719، 5720، 5721)."},{"num":11576,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَوَانِي أَبُو طَلْحَةَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا، فَمَا نُهِيتُ عَنْهُ."],"takhrij":"حسن: رواه أحمد (12416)، والحاكم (8288) كلاهما من حديث عمران، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12416) and al-Ḥākim (8288).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Anas narrated: “Abū Ṭalḥah cauterized me while the Messenger of Allah ﷺ was among us, and I was not prohibited from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12416)، والحاكم (8288)."},{"num":11577,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِابْنِ زُرَارَةَ أَنْ يُكْوَى."],"takhrij":"صحيح: رواه أبو يعلى (4825)، وابن حبان (6079) كلاهما من طريق محمد بن عباد المكي قال: حدثنا ابن أبي فديك، عن ابن أبي ذئب، عن الزهري، عن عروة، عن عائشة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Yaʿlā (4825) and Ibn Ḥibbān (6079).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Prophet ﷺ ordered that Ibn Zurārah be cauterized."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو يعلى (4825)، وابن حبان (6079)."},{"num":11578,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ علَى أَسْعَدَ بْنِ زُرَارَةَ، وَبِهِ وَجَعٌ، يُقَالُ لَهُ: الشَّوْكَةُ، فَكَوَاهُ حَوْرَانَ عَلَى عُنُقِهِ، فَمَاتَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِئْسَ الْمَيِّتُ لِلْيَهُودِ، يَقُولُونَ: قَدْ دَاوَاهُ صَاحِبُه، أَفَلا نَفَعَهُ."],"takhrij":"صحيح: رواه عبد الرزاق (19515) عن معمر، عن الزهري، عن أبي أمامة فذكره.وهو مرسل.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzāq (19515).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf narrated: The Messenger of Allah ﷺ entered upon Asʿad ibn Zurārah while he was suffering from an illness called al-shawkah. He cauterized him with a circular cauterization upon his neck, but he died. The Prophet ﷺ said: “What an opportunity this death gives the Jews. They will say, ‘His companion treated him, so why did it not benefit him?’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد الرزاق (19515)."},{"num":11579,"demo":false,"sanad":"","matn":["عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَوَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَعْدًا أَوْ أَسْعَدَ بْنَ زُرَارَةَ فِي حَلْقِهِ مِنَ الذُّبْحَةِ وَقَالَ: لَا أَدَعُ فِي نَفْسِي حَرَجًا مِنْ سَعْدٍ، أَوْ أَسْعَدَ بْنِ زُرَارَةَ."],"takhrij":"حسن: رواه أحمد (23207) عن حسن (وهو ابن موسى)، حدثنا زهير، عن أبي الزبير، عن عمرو بن شعيب، عن أبيه، عن بعض أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في جواز الكي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (23207).","chapter_en":"What Has Been Reported Concerning the Permissibility of Cauterization","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["One of the Companions of the Prophet ﷺ narrated: The Messenger of Allah ﷺ cauterized Saʿd—or Asʿad ibn Zurārah—upon his throat because of al-dhubḥah, and said: “I will leave no concern within myself regarding Saʿd—or Asʿad ibn Zurārah.”"]},"buhuth":{"en":["The word al-dhubḥah refers to a painful illness of the throat. When it becomes severe, it may obstruct breathing and kill the patient."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23207)."},{"num":11580,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ احْتَجَمَ وَأَعْطَى الْحَجَّامَ أَجْرَهُ وَاسْتَعَطَ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5691)، ومسلم في المساقة والمزارعة (1202: 65) كلاهما من طريق وهيب، ثنا ابن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في السعوط","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5691) and Muslim (1202/65).","chapter_en":"What Has Been Reported Concerning Nasal Medication","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ underwent cupping, paid the cupper his wages, and used nasal medication."]},"buhuth":{"en":["The word istaʿaṭa means that he used suʿūṭ, a medicine administered by pouring it into the nose."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5691)، ومسلم (1202: 65)."},{"num":11581,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  لَدَدْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ، فَأَشَارَ أَنْ لَا تَلُدُّونِي، فَقُلْنَا: كَرَاهِيَةَُ الْمَرِيضِ لِلدَّوَاءِ، فَلَمَّا أَفَاقَ قَالَ: لَا يَبْقَى أَحَدٌ مِنْكُمْ إِلَّا لُدَّ غَيْرُ الْعَبَّاسِ فَإِنَّهُ لَمْ يَشْهَدْكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5712)، ومسلم في السلام (2213) كلاهما من طريق يحيى بن سعيد (هو القطان)، ثنا سفيان (هو الثوري)، حدثني موسى بن أبي عائشة، عن عبيد الله بن عبد الله، عن عائشة قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في اللدود","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5712) and Muslim (2213).","chapter_en":"What Has Been Reported Concerning Medicine Administered through the Side of the Mouth","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["ʿĀ’ishah narrated: We administered medicine to the Messenger of Allah ﷺ through the side of his mouth during his illness. He gestured to us not to do so, but we thought this was merely a sick person’s dislike of medicine. When he recovered consciousness, he said: “No one among you is to remain without having the medicine administered in the same manner, except al-ʿAbbās, because he was not present with you.”"]},"buhuth":{"en":["The expression “Do not administer medicine to me through the side of my mouth” refers to ladūd, medicine poured into one side of a patient’s mouth without his consent. Medicine poured directly into the throat is called wajūr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5712)، ومسلم (2213)."},{"num":11582,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ:  جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أَخِي اسْتَطْلَقَ بَطْنُهُ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْقِهِ عَسَلًا. فَسَقَاهُ، ثُمَّ جَاءَهُ فَقَالَ: إِنِّي سَقَيْتُهُ عَسَلًا فَلَمْ يَزِدْهُ إِلَّا اسْتِطْلَاقًا! فَقَالَ لَهُ ثَلَاثَ مَرَّاتٍ، ثُمَّ جَاءَ الرَّابِعَةَ فَقَالَ: اسْقِهِ عَسَلًا. فَقَالَ: لَقَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا اسْتِطْلَاقًا! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَدَقَ اللَّهُ وَكَذَبَ بَطْنُ أَخِيكَ! فَسَقَاهُ فَبَرَأَ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5684)، ومسلم في السلام (2217) كلاهما من حديث قتادة، عن أبي المتوكل، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب التداوي بالعسل","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5684) and Muslim (2217). The wording cited here is that of Muslim.","chapter_en":"Seeking Treatment with Honey","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: A man came to the Prophet ﷺ and said: “My brother is suffering from diarrhea.” The Messenger of Allah ﷺ said: “Give him honey to drink.” The man gave him honey and then returned, saying: “I gave him honey, but it only increased his diarrhea.” The Prophet ﷺ instructed him to do the same three times. When the man came a fourth time, the Prophet ﷺ said: “Give him honey to drink.” The man replied: “I have given it to him, but it has only increased his diarrhea.” The Messenger of Allah ﷺ said: “Allah has spoken the truth, and your brother’s stomach has lied.” The man gave him honey again, and he recovered."]},"buhuth":{"en":["The word istaṭlaqa refers to diarrhea. Diarrhea occurs when harmful matter has accumulated in the stomach and must be expelled. Honey is among the most beneficial and quickest substances for removing such harmful matter."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ مُخْتَلِفٌ أَلْوَانُهُ، فِيهِ شِفَاءٌ لِلنَّاسِ، إِنَّ فِي ذَلِكَ لَآيَةً لِقَوْمٍ يَتَفَكَّرُونَ﴾ [سورة النحل: ٦٩]."],"en":["Allah, the Exalted, said:","“From their bellies comes a drink of varying colors in which there is healing for people. Indeed, in that is a sign for people who reflect.”","[Sūrat al-Naḥl 16:69]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5684)، ومسلم (2217)، واللفظ لمسلم."},{"num":11583,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثٌ فِيهِنَّ شِفَاءٌ مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ، السَّنَا وَالسَّنُّوتُ."],"takhrij":"حسن: رواه النسائي في الكبرى (7533)، وأبو نعيم في الطب (178، 612)، والضياء المقدسي في المختارة (2255) كلهم من طريق حاتم بن إسماعيل، عن محمد بن عمارة، عن عبد الله بن عبد الله بن أبي طلحة، عن أنس بن مالك قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السنا والسنوت","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in al-Sunan al-Kubrā (7533), Abū Nuʿaym in al-Ṭibb (178, 612), and al-Ḍiyāʾ al-Maqdisī in al-Mukhtārah (6/236).","chapter_en":"What Has Been Reported Concerning Senna and Sanūt","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “There are three things containing a cure for every illness except death: senna and sanūt.” Muḥammad ibn ʿUmārah, one of the narrators, said: “I forgot the third.”"]},"buhuth":{"en":["Sanūt means honey, as previously mentioned. Senna is a plant used to treat constipation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في الكبرى (7533)، وأبو نعيم في الطب (178، 612)، والضياء المقدسي في المختارة (2255)."},{"num":11584,"demo":false,"sanad":"","matn":["أَنَّ أَبَا هُرَيْرَةَ، أَخْبَرَهُمَا أَنَّهُ، سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: فِي الْحَبَّةِ السَّوْدَاءِ شِفَاءٌ مِنْ كُلِّ دَاءٍ إِلاَّ السَّامَ.","قَالَ ابْنُ شِهَابٍ: وَالسَّامُ: الْمَوْتُ، وَالْحَبَّةُ السَّوْدَاءُ: الشُّونِيزُ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5688)، ومسلم في السلام (2215) كلاهما من طريق الليث، عن عُقيل، عن ابن شهاب، أخبرني أبو سلمة بن عبدالرحمن وسعيد بن المسيب، أن أبا هريرة أخبرهما فذكره.","grade":"متفق عليه","chapter_ar":"باب التداوي بالحبة السوداء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5688) and Muslim (2215).","chapter_en":"Seeking Treatment with Black Seed","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that he heard the Messenger of Allah ﷺ say: “In black seed there is healing for every illness except death.” Ibn Shihāb said: “Al-sām means death, and black seed is al-shūnīz.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5688)، ومسلم (2215)."},{"num":11585,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ سَعْدٍ، قَالَ: خَرَجْنَا وَمَعَنَا غَالِبُ بْنُ أَبْجَرَ فَمَرِضَ فِي الطَّرِيقِ، فَقَدِمْنَا الْمَدِينَةَ وَهْوَ مَرِيضٌ، فَعَادَهُ ابْنُ أَبِي عَتِيقٍ فَقَالَ لَنَا: عَلَيْكُمْ بِهَذِهِ الْحُبَيْبَةِ السَّوْدَاءِ، فَخُذُوا مِنْهَا خَمْسًا أَوْ سَبْعًا فَاسْحَقُوهَا، ثُمَّ اقْطُرُوهَا فِي أَنْفِهِ بِقَطَرَاتِ زَيْتٍ فِي هَذَا الْجَانِبِ، وَفِي هَذَا الْجَانِبِ، فَإِنَّ عَائِشَةَ حَدَّثَتْنِي أَنَّهَا سَمِعَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ هَذِهِ الْحَبَّةَ السَّوْدَاءَ شِفَاءٌ مِنْ كُلِّ دَاءٍ إِلاَّ مِنَ السَّامِ. قُلْتُ وَمَا السَّامُ؟ قَالَ: الْمَوْتُ."],"takhrij":"صحيح: رواه البخاري في الطب (5687) عن عبد الله بن أبي شيبة، ثنا عبيدالله، ثنا إسرائيل، عن منصور، عن خالد بن سعد فذكره.","grade":"صحيح","chapter_ar":"باب التداوي بالحبة السوداء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5687).","chapter_en":"Seeking Treatment with Black Seed","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Khālid ibn Saʿd narrated: We set out accompanied by Ghālib ibn Abjar, who became ill on the journey. We reached Madinah while he was still sick. Ibn Abī ʿAtīq visited him and told us: “Use this black seed. Take five or seven seeds, crush them, mix them with drops of oil, and place some into each nostril.” He then said: ʿĀ’ishah narrated to me that she heard the Prophet ﷺ say: “Indeed, this black seed contains healing for every illness except al-sām.” I asked: “What is al-sām?” He replied: “Death.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5687)."},{"num":11586,"demo":false,"sanad":"","matn":["يُحَدِّثُ عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ؛ فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ دَاءٍ إِلاَّ السَّامَ."],"takhrij":"حسن: رواه ابن ماجه (3448) عن أبي سلمة –يحيى بن خلف- قال: حدثنا أبو عاصم، عن عثمان بن عبد الملك قال: سمعت سالم بن عبد الله، يحدث عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب التداوي بالحبة السوداء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3448).","chapter_en":"Seeking Treatment with Black Seed","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Use this black seed, for it contains healing for every illness except death.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3448)."},{"num":11587,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بن شَرِيكٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فِي الْحَبَّةُ السَّوْدَاءُ شِفَاءٌ مِنْ كلِّ داءٍ إِلَّا السَّامَ."],"takhrij":"حسن: رواه الطبراني في الكبير (491) عن عبدالله بن أحمد بن حنبل، حدثنا سُريج بن يونس، عن المطلب بن زياد، عن زياد بن علاقة، عن أسامة بن شريك فذكره.","grade":"حسن","chapter_ar":"باب التداوي بالحبة السوداء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (1/153).","chapter_en":"Seeking Treatment with Black Seed","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Usāmah ibn Sharīk narrated that the Prophet ﷺ said: “In black seed there is healing for every illness except death.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (491)."},{"num":11588,"demo":false,"sanad":"","matn":["عن بُرَيْدَةَ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْكَمْأَةُ دَوَاءُ لِلْعَيْنِ، وَإِنَّ الْعَجْوَةَ مِنْ فَاكِهَةِ الْجَنَّةِ، وَإِنَّ هَذِهِ الْحَبَّةَ السَّوْدَاءَ، قَالَ: ابْنُ بُرَيْدَةَ: يَعْنِي الشُّونِيزَ الَّذِي يَكُونُ فِي الْمِلْحِ، دَوَاءٌ مِنْ كُلِّ دَاءٍ إِلَّا الْمَوْتَ."],"takhrij":"حسن: رواه أحمد (22938) عن أسود بن عامر، حدثنا زهير، عن واصل بن حيان البجلي، حدثنا عبد الله بن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب التداوي بالحبة السوداء","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22938).","chapter_en":"Seeking Treatment with Black Seed","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Buraydah narrated that the Prophet ﷺ said: “The truffle is a treatment for the eye, ʿajwah dates are among the fruits of Paradise, and this black seed is a treatment for every illness except death.” Ibn Buraydah said: “He meant al-shūnīz, the seed commonly kept with salt.”"]},"buhuth":{"en":["Al-shūnīz is black seed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22938)."},{"num":11589,"demo":false,"sanad":"","matn":["عَنْ أُمِّ قَيْسٍ، قَالَتْ: دَخَلْتُ بِابْنٍ لِي عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ أَعْلَقْتُ عَلَيْهِ مِنَ الْعُذْرَةِ، فَقَالَ: عَلَى مَا تَدْغَرْنَ أَوْلاَدَكُنَّ بِهَذَا الْعِلاَقِ؟ عَلَيْكُنَّ بِهَذَا الْعُودِ الْهِنْدِيِّ، فَإِنَّ فِيهِ سَبْعَةَ أَشْفِيَةٍ، مِنْهَا: ذَاتُ الْجَنْبِ يُسْعَطُ مِنَ الْعُذْرَةِ، وَيُلَدُّ مِنْ ذَاتِ الْجَنْبِ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5713)، ومسلم في السلام (2214) كلاهما من طريق سفيان بن عيينة، عن الزهري، عن عبيد الله بن عبد الله، عن أم قيس بنت محصن فذكرته.زاد البخاري: قال الزهري: بيّن لنا اثنين، ولم يبين لنا خمسة.","grade":"متفق عليه","chapter_ar":"باب التداوي بالعود الهندي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5713) and Muslim (2214).","chapter_en":"Seeking Treatment with Indian Costus","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Umm Qays bint Miḥṣan narrated: I brought one of my sons to the Messenger of Allah ﷺ after treating his throat ailment by pressing it with my finger. He said: “Why do you press your children’s throats in this manner? Use this Indian costus, for it contains seven cures, including treatment for pleurisy. It is administered through the nose for throat inflammation and through the side of the mouth for pleurisy.”"]},"buhuth":{"en":["Her statement “I had treated him” means that she treated the child’s throat ailment by pressing it with her finger. Al-daghr means pressing or squeezing the throat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5713)، ومسلم (2214)."},{"num":11590,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سُئِلَ عَنْ أَجْرِ الْحَجَّامِ، فَقَالَ: احْتَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَمَهُ أَبُو طَيْبَةَ، وَأَعْطَاهُ صَاعَيْنِ مِنْ طَعَامٍ، وَكَلَّمَ مَوَالِيَهُ، فَخَفَّفُوا عَنْهُ، وَقَالَ: إِنَّ أَمْثَلَ مَا تَدَاوَيْتُمْ بِهِ الْحِجَامَةُ وَالْقُسْطُ الْبَحْرِيُّ. وَقَالَ: لاَ تُعَذِّبُوا صِبْيَانَكُمْ بِالْغَمْزِ مِنَ الْعُذْرَةِ، وَعَلَيْكُمْ بِالْقُسْطِ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5696)- واللفظ له-، ومسلم في المساقاة (1577: 63) كلاهما من حديث حميد الطويل، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب التداوي بالعود الهندي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5696), whose wording is cited here, and Muslim (1577/63).","chapter_en":"Seeking Treatment with Indian Costus","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Anas was asked about the wages of a cupper. He replied: The Messenger of Allah ﷺ underwent cupping, and Abū Ṭaybah performed it for him. He gave him two sāʿs of food and spoke to his masters, who reduced his financial obligation. The Prophet ﷺ said: “Among the most effective treatments you use are cupping and sea costus.” He also said: “Do not torment your children by pressing their throats because of al-ʿudhrah. Use costus instead.”"]},"buhuth":{"en":["Sea costus is Indian costus.","The words “Do not torment your children by pressing their throats because of al-ʿudhrah” refer to an inflammation or swelling of the throat caused by blood during hot weather. People used to press the affected place with their fingers so that dark blood would emerge. The Prophet ﷺ directed them to use costus instead."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5696) واللفظ له، ومسلم (1577: 63)."},{"num":11591,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أُمِّ سَلَمَةَ - قَالَ ابْنُ أَبِي غَنِيَّةَ: دَخَلَ عَلَى عَائِشَةَ بِصَبِيٍّ يَسِيلُ مَنْخِرَاهُ دَمًا - قَالَ أَبُو مُعَاوِيَةَ فِي حَدِيثِهِ، وَعِنْدَهَا صَبِيٌّ يَثعب مَنْخِرَاهُ دَمًا، قَالَ: فَقَالَ: مَا لِهَذَا؟ قَالَ: فَقَالُوا: بِهِ الْعُذْرَةُ، قَالَ: فَقَالَ: عَلَامَ تُعَذِّبْنَ أَوْلَادَكُنَّ، إِنَّمَا يَكْفِي إِحْدَاكُنَّ أَنْ تَأْخُذَ قُسْطًا هِنْدِيًّا فَتَحُكَّهُ بِمَاءٍ سَبْعَ مَرَّاتٍ، ثُمَّ تُوجِرَهُ إِيَّاهُ - قَالَ ابْنُ أَبِي غَنِيَّةَ: ثُمَّ تُسْعِطَهُ إِيَّاهُ -، فَفَعَلُوا فَبَرَأَ."],"takhrij":"صحيح: رواه أحمد (14385)، والبزار – كشف الأستار (3024)، والحاكم (4/205) كلهم من طريق الأعمش، عن أبي سفيان، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب التداوي بالعود الهندي","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (14385), al-Bazzār in Kashf al-Astār (3024), and al-Ḥākim (4/205).","chapter_en":"Seeking Treatment with Indian Costus","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Jābir narrated: The Messenger of Allah ﷺ entered upon Umm Salamah—according to Ibn Abī Ghaniyyah, upon ʿĀ’ishah—while a child was present whose nostrils were flowing with blood. Abū Muʿāwiyah’s narration states: “A child was with her whose nostrils were pouring blood.” The Prophet ﷺ asked: “What is wrong with him?” They replied: “He is suffering from al-ʿudhrah.” He said: “Why do you torment your children? It is sufficient for one of you to take Indian costus, rub it with water seven times, and administer it to him through the side of his mouth.” Ibn Abī Ghaniyyah’s wording states: “Then administer it through his nose.” They did so, and the child recovered."]},"buhuth":{"en":["The expression “his nostrils were pouring” means that blood was flowing from them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (14385)، والبزار في كشف الأستار (3024)، والحاكم (4/205)."},{"num":11592,"demo":false,"sanad":"","matn":["عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا، فَقَالَ: أَعِنْدَكِ ذَرِيرَةٌ؟ قَالَتْ: نَعَمْ، فَدَعَا بِهَا، فَوَضَعَهَا عَلَى بَثْرَةٍ بَيْنَ أَصَابِعِ رِجْلَيْهِ، ثُمَّ قَالَ: اللَّهُمَّ مُطْفِئَ الْكَبِيرِ، وَمُكَبِّرَ الصَّغِيرِ أَطْفِهَا عَنِّي.فَطُفِئَتْ."],"takhrij":"صحيح: رواه الإمام أحمد (23141)، والنسائي في الكبرى (10803)، والحاكم (4/407) كلهم من طرقٍ عن ابن جريج، أخبرني عمرو بن يحيى بن عمارة بن أبي حسن، حدثتني مريم ابنة إياس بن البكير صاحب النبي صلى الله عليه وسلم، عن بعض أزواج النبي صلى الله عليه وسلم: فذكرته.","grade":"صحيح","chapter_ar":"باب التداوي بالذريرة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Imām Aḥmad (23141), al-Nasā’ī in al-Sunan al-Kubrā (10803), and al-Ḥākim (4/407).","chapter_en":"Seeking Treatment with Dhurayrah","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["One of the wives of the Prophet ﷺ narrated: The Prophet ﷺ entered upon her and asked: “Do you have any dhurayrah?” She replied: “Yes.” He asked for it and placed it upon a blister between his toes. He then said: “O Allah, You who make the great small and the small great, reduce it for me.” It then became smaller."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (23141)، والنسائي في الكبرى (10803)، والحاكم (4/407)."},{"num":11593,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ نَاسًا، اجْتَوَوْا فِي الْمَدِينَةِ، فَأَمَرَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَلْحَقُوا بِرَاعِيهِ ـ يَعْنِي الإِبِلَ، ـ فَيَشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا، فَلَحِقُوا بِرَاعِيهِ، فَشَرِبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا، حَتَّى صَلَحَتْ أَبْدَانُهُمْ، فَقَتَلُوا الرَّاعِيَ، وَسَاقُوا الإِبِلَ، فَبَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ فِي طَلَبِهِمْ، فَجِيءَ بِهِمْ، فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ، وَسَمَرَ أَعْيُنَهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5686)، ومسلم في القسامة (1671: ...) كلاهما من طريق همام، عن قتادة، عن أنس فذكره.والسياق للبخاري، ولم يسق مسلم لفظه، وإنما أحال على لفظ رواية قبلها.","grade":"متفق عليه","chapter_ar":"باب التداوي بأبوال الإبل وألبانها","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5686) and Muslim (1671). The sequence cited here is that of al-Bukhārī.","chapter_en":"Seeking Treatment with Camel Urine and Milk","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Anas narrated: Some people became ill because they could not tolerate the climate of Madinah. The Prophet ﷺ instructed them to join his camel herdsman and drink from the camels’ milk and urine. They joined the herdsman and drank from the camels’ milk and urine until their bodies recovered. They then killed the herdsman and drove away the camels. When this reached the Prophet ﷺ, he sent people in pursuit of them. They were brought back, and their hands and feet were cut off and their eyes were branded with heated iron."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5686)، ومسلم (1671)، والسياق للبخاري."},{"num":11594,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَنْزَلَ اللَّهُ دَاءً إِلَاّ أَنْزَلَ لَهُ دَوَاءً، فَعَلَيْكُمْ بِأَلْبَانِ الْبَقَرِ، فَإِنَّهَا تَرُمُّ مِنْ كُلِّ الشَّجَرِ."],"takhrij":"صحيح: رواه ابن حبان (6075)، والطيالسي (366)، والحاكم (7425)، والبيهقي (9/345) كلهم من طرق عن قيس بن مسلم، عن طارق بن شهاب، عن ابن مسعود فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في ألبان البقر","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (6075), al-Ṭayālisī (366), al-Ḥākim (7425), and al-Bayhaqī (9/345).","chapter_en":"What Has Been Reported Concerning Cow’s Milk","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Allah has not sent down an illness without sending down its cure. Therefore, use cow’s milk, for cows graze from every kind of plant.”"]},"buhuth":{"en":["The word tarummu means “it eats.” A cow may eat a plant containing medicinal properties, and some of its effect may remain in the milk."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (6075)، والطيالسي (366)، والحاكم (7425)، والبيهقي (9/345)."},{"num":11595,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تصبَّحَ كلَّ يومٍ سبعَ تَمَرَاتٍ عَجْوَةً لَمْ يضرُّه فِي ذَلِكَ الْيَوْمِ سُمٌّ وَلاَ سحرٌ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5445)، ومسلم في الأشربة (2047: 155) كلاهما من طريق مروان بن معاوية الفزاري، أخبرنا هاشم بن هاشم، أخبرنا عامر بن سعد، عن أبيه، فذكره.واللفظ للبخاري، وأحال به مسلم على حديث أبي أسامة، عن هاشم به مثله، لكن ليس فيه قوله: \"كل يوم\".","grade":"متفق عليه","chapter_ar":"باب التداوي بتمر العجوة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5445) and Muslim (2047/155). The wording cited here is that of al-Bukhārī.","chapter_en":"Seeking Treatment with ʿAjwah Dates","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated that the Messenger of Allah ﷺ said: “Whoever eats seven ʿajwah dates every morning will not be harmed that day by poison or sorcery.”"]},"buhuth":{"en":["ʿAjwah is among the finest and most valuable varieties of dates grown in Madinah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5445)، ومسلم (2047: 155)، واللفظ للبخاري."},{"num":11596,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ اصْطَبَحَ كُلَّ يَوْمٍ تَمَرَاتٍ عَجْوَةً لَمْ يَضُرُّهُ سُمٌّ وَلاَ سحرٌ ذَلِكَ الْيَوْمَ وَاللَّيْلِ."],"takhrij":"صحيح: رواه البخاري في الطب (5768) عن علي، حدثنا مروان، أخبرنا هشام، أخبرنا عامر بن سعد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب التداوي بتمر العجوة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5768).","chapter_en":"Seeking Treatment with ʿAjwah Dates","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated that the Prophet ﷺ said: “Whoever eats ʿajwah dates every morning will not be harmed by poison or sorcery during that day until nightfall.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5768)."},{"num":11597,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي عَجْوة الْعَالِيَةِ شِفَاءً –أَوْ إِنَّهَا تِرْيَاقٌ- أَوَّلَ الْبُكْرَةِ وَزَادَ فِي رِوَايَةِ: على الريق."],"takhrij":"صحيح: رواه مسلم في الأشربة (2048) من طرق عن إسماعيل بن جعفر، عن شريك بن أبي نمر، عن عبد الله بن أبي عتيق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب التداوي بتمر العجوة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2048).","chapter_en":"Seeking Treatment with ʿAjwah Dates","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Indeed, there is healing in the ʿajwah dates of al-ʿĀliyah—or they are an antidote—when eaten at the beginning of the morning.” Another narration adds: “On an empty stomach.”"]},"buhuth":{"en":["Al-ʿĀliyah refers to the elevated district of Madinah situated toward its southern and eastern sides.","The words “Poison or sorcery will not harm him during that day until nightfall” may have two meanings. The apparent meaning is that even if he consumes poison, it will not harm him. The second is that the body will resist poisoning arising from food or other causes.","Tiryāq means a medicine or compound used as an antidote against poison. It is an Arabicized term.","The words “at the beginning of the morning” mean that the dates are eaten before any other food.","The wording “whoever eats them in the morning” is general for every time and place. There is no evidence restricting it to the people of Madinah or to the Prophetic era alone, although some scholars held such a view. It means eating them in the morning before consuming anything else.","The wording “the ʿajwah of al-ʿĀliyah” specifies one category from the general class of Madinan ʿajwah dates. This specification does not remove the general ruling. Rather, the dates of al-ʿĀliyah possess an additional distinction because of the climate of that area.","The number seven is not open to personal reasoning. The Prophet ﷺ specified this number of ʿajwah dates for protection from poison and sorcery. This resembles a physician prescribing medicine together with its precise dosage, since the quantities used in medicines are of great importance in treatment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2048)."},{"num":11598,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْعَجْوَةُ مِنَ الْجَنَّةِ وَفِيهَا شِفَاءٌ مِنَ السُّمِّ، وَالْكَمْأَةُ مِنَ الْمَنِّ، وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ."],"takhrij":"حسن: رواه الترمذي (2066) من طرق عن سعيد بن عامر، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب العجوة من الجنة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2066).","chapter_en":"ʿAjwah Dates Are from Paradise","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “ʿAjwah dates are from Paradise and contain healing from poison. Truffles are from the manna, and their water is a cure for the eye.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2066)."},{"num":11599,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، وَجَابِرٍ، قَالاَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْكَمْأَةُ مِنَ الْمَنِّ، وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنَ الْجَنَّةِ وَهِي شِفَاءٌ مِنَ الْجَنَّةَ."],"takhrij":"حسن: رواه ابن ماجه (3453)، وأحمد (11453) كلاهما من طريق أسباط بن محمد ، حدثنا الأعمش ، عن جعفر بن إياس ، عن شهر بن حوشب ، عن أبي سعيد ، وجابر فذكراه.","grade":"حسن","chapter_ar":"باب العجوة من الجنة","chapter_ur":"","part_ar":"كتاب الطب","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3453) and Aḥmad (11453).","chapter_en":"ʿAjwah Dates Are from Paradise","part_en":"Medicine","group_ar":"مجموع ما جاء في الطب","group_en":"A Collection of What Has Been Reported Concerning Medicine","part_no":57,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abū Saʿīd and Jābir narrated that the Messenger of Allah ﷺ said: “Truffles are from the manna, and their water is a cure for the eye. ʿAjwah dates are from Paradise and are a cure for poison.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3453)، وأحمد (11453)."}]);